SgScopeStatement *normalizeNamespaceScope(SgScopeStatement *scope);
static bool declaration_has_real_source(SgDeclarationStatement *decl);

void publishExactFriendModifier(SgDeclarationStatement *declaration) {
  if (declaration == nullptr) {
    return;
  }
  declaration->get_declarationModifier().setFriend();
  SgAccessModifier &access =
      declaration->get_declarationModifier().get_accessModifier();
  access.setNotApplicable();
  access.set_is_explicit(false);
}

void requireExactDeclarationAccess(SgDeclarationStatement *declaration,
                                   const char *producer) {
  ASSERT_not_null(declaration);
  ASSERT_not_null(producer);
  const SgAccessModifier &access =
      declaration->get_declarationModifier().get_accessModifier();
  if (access.isUnknown() || access.isDefault()) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[declaration-access-publication]: "
            "producer=%s declaration=%p/%s has no exact lexical access\n",
            producer, static_cast<void *>(declaration),
            declaration->class_name().c_str());
    ROSE_ABORT();
  }
}

static void
publishDeclarationFamilyAccessFromExactSource(SgDeclarationStatement *source,
                                              SgDeclarationStatement *candidate,
                                              const char *producer) {
  if (source == nullptr || candidate == nullptr || producer == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[declaration-family-access]: producer=%s "
            "requires exact source=%p and candidate=%p\n",
            producer != nullptr ? producer : "<null>",
            static_cast<void *>(source), static_cast<void *>(candidate));
    ROSE_ABORT();
  }

  const SgAccessModifier &source_access =
      source->get_declarationModifier().get_accessModifier();
  requireExactDeclarationAccess(source, producer);
  SgAccessModifier &candidate_access =
      candidate->get_declarationModifier().get_accessModifier();

  // Access belongs to a declaration's exact lexical position, not to the
  // semantic redeclaration family.  This distinction is observable for C
  // tags: a tag first written inside a record can have record-member access
  // while a later file-scope redeclaration of the same tag has access marked
  // not-applicable.  Every source-backed family member is published from its
  // own Clang declaration and must retain that independently derived value.
  if (candidate == source || declaration_has_real_source(candidate)) {
    requireExactDeclarationAccess(candidate, producer);
    return;
  }

  // A compiler-generated canonical declaration has no independent lexical
  // position.  Publish its access from the exact source declaration that
  // created this semantic family, replacing any Sage builder default.
  switch (source_access.get_modifier()) {
  case SgAccessModifier::e_public:
    candidate_access.setPublic();
    break;
  case SgAccessModifier::e_protected:
    candidate_access.setProtected();
    break;
  case SgAccessModifier::e_private:
    candidate_access.setPrivate();
    break;
  case SgAccessModifier::e_not_applicable:
    candidate_access.setNotApplicable();
    break;
  default:
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[declaration-family-access]: producer=%s "
            "source=%p/%s has invalid exact access=%d\n",
            producer, static_cast<void *>(source), source->class_name().c_str(),
            static_cast<int>(source_access.get_modifier()));
    ROSE_ABORT();
  }
  candidate_access.set_is_explicit(source_access.get_is_explicit());
  requireExactDeclarationAccess(candidate, producer);
}

static SgType *stripSageDeclaratorBaseType(SgType *type) {
  ROSE_ASSERT(type != nullptr);

  std::unordered_set<SgType *> seen;
  SgType *current = type;
  while (current != nullptr) {
    if (!seen.insert(current).second) {
      std::cerr << "Runtime error: cyclic Sage type chain while resolving "
                   "declarator base type at "
                << current << " (" << current->class_name() << ")" << std::endl;
      ROSE_ABORT();
    }

    if (SgModifierType *modifier_type = isSgModifierType(current)) {
      current = modifier_type->get_base_type();
      continue;
    }
    if (SgReferenceType *reference_type = isSgReferenceType(current)) {
      current = reference_type->get_base_type();
      continue;
    }
    if (SgRvalueReferenceType *reference_type =
            isSgRvalueReferenceType(current)) {
      current = reference_type->get_base_type();
      continue;
    }
    if (SgPointerType *pointer_type = isSgPointerType(current)) {
      if (isSgPointerMemberType(current) == nullptr) {
        current = pointer_type->get_base_type();
        continue;
      }
    }
    if (SgPointerMemberType *pointer_type = isSgPointerMemberType(current)) {
      current = pointer_type->get_base_type();
      continue;
    }
    if (SgArrayType *array_type = isSgArrayType(current)) {
      current = array_type->get_base_type();
      continue;
    }
    if (SgTypedefType *typedef_type = isSgTypedefType(current)) {
      current = typedef_type->get_base_type();
      continue;
    }

    return current;
  }

  std::cerr << "Runtime error: null Sage type reached while resolving "
               "declarator base type"
            << std::endl;
  ROSE_ABORT();
}

void roseClangPhaseTrace(const char *phase) {
  if (getenv("ROSE_PHASE_TRACE") != nullptr) {
    fprintf(stderr, "ROSE_PHASE %s\n", phase);
    fflush(stderr);
  }
}

double roseSlowTemplateSpecTraceThresholdMs() {
  static const double threshold_ms = []() -> double {
    const char *value = getenv("ROSE_SLOW_TEMPLATE_SPEC_TRACE_MS");
    if (value == nullptr || *value == '\0') {
      return 0.0;
    }

    char *end = nullptr;
    double parsed = std::strtod(value, &end);
    if (end == value || parsed <= 0.0) {
      return 0.0;
    }

    return parsed;
  }();

  return threshold_ms;
}

double roseSlowDeclTraceThresholdMs() {
  static const double threshold_ms = []() -> double {
    const char *value = getenv("ROSE_SLOW_DECL_TRACE_MS");
    if (value == nullptr || *value == '\0') {
      return 0.0;
    }

    char *end = nullptr;
    double parsed = std::strtod(value, &end);
    if (end == value || parsed <= 0.0) {
      return 0.0;
    }

    return parsed;
  }();

  return threshold_ms;
}

double roseSlowFunctionTraceThresholdMs() {
  static const double threshold_ms = []() -> double {
    const char *value = getenv("ROSE_SLOW_FUNCTION_TRACE_MS");
    if (value == nullptr || *value == '\0') {
      return roseSlowDeclTraceThresholdMs();
    }

    char *end = nullptr;
    double parsed = std::strtod(value, &end);
    if (end == value || parsed <= 0.0) {
      return roseSlowDeclTraceThresholdMs();
    }

    return parsed;
  }();

  return threshold_ms;
}

struct ScopedTranslationCacheRebuild {
  unsigned &depth;
  bool active;

  ScopedTranslationCacheRebuild(unsigned &depth_ref, bool should_rebuild)
      : depth(depth_ref), active(should_rebuild) {
    if (active) {
      ++depth;
    }
  }

  ~ScopedTranslationCacheRebuild() {
    if (active) {
      ROSE_ASSERT(depth > 0);
      --depth;
    }
  }
};

class ScopedOnDemandDeclarationExpressionRole {
public:
  ScopedOnDemandDeclarationExpressionRole(unsigned &semantic_depth,
                                          const clang::Decl *declaration)
      : semantic_depth_(semantic_depth), suspended_depth_(semantic_depth),
        declaration_(declaration) {
    if (declaration_ == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[on-demand-expression-role]: cannot "
              "isolate expression provenance for a null declaration\n");
      ROSE_ABORT();
    }
    semantic_depth_ = 0;
  }

  ~ScopedOnDemandDeclarationExpressionRole() {
    if (semantic_depth_ != 0) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[on-demand-expression-role]: "
              "declaration=%p suspended semantic depth=%u but completed "
              "with unbalanced nested depth=%u\n",
              static_cast<const void *>(declaration_), suspended_depth_,
              semantic_depth_);
      ROSE_ABORT();
    }
    semantic_depth_ = suspended_depth_;
  }

  ScopedOnDemandDeclarationExpressionRole(
      const ScopedOnDemandDeclarationExpressionRole &) = delete;
  ScopedOnDemandDeclarationExpressionRole &
  operator=(const ScopedOnDemandDeclarationExpressionRole &) = delete;

private:
  unsigned &semantic_depth_;
  const unsigned suspended_depth_;
  const clang::Decl *declaration_;
};

class ScopedOnDemandDeclarationTypeSurfaceRole {
public:
  ScopedOnDemandDeclarationTypeSurfaceRole(
      unsigned &explicit_template_id_depth,
      unsigned &reconstructed_argument_depth,
      unsigned &written_specialization_depth,
      unsigned &written_named_qualification_depth,
      unsigned &omitted_injected_template_id_depth,
      unsigned &nonlocal_injected_class_name_depth,
      const clang::Decl *declaration)
      : depths_{&explicit_template_id_depth,
                &reconstructed_argument_depth,
                &written_specialization_depth,
                &written_named_qualification_depth,
                &omitted_injected_template_id_depth,
                &nonlocal_injected_class_name_depth},
        declaration_(declaration) {
    if (declaration_ == nullptr) {
      fprintf(stderr, "REX_FRONTEND_INVARIANT[on-demand-type-surface]: cannot "
                      "isolate source type state for a null declaration\n");
      ROSE_ABORT();
    }
    for (size_t index = 0; index < depths_.size(); ++index) {
      suspended_depths_[index] = *depths_[index];
      *depths_[index] = 0;
    }
  }

  ~ScopedOnDemandDeclarationTypeSurfaceRole() {
    for (size_t index = 0; index < depths_.size(); ++index) {
      if (*depths_[index] != 0) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[on-demand-type-surface]: "
                "declaration=%p role=%zu suspended depth=%u but completed "
                "with unbalanced nested depth=%u\n",
                static_cast<const void *>(declaration_), index,
                suspended_depths_[index], *depths_[index]);
        ROSE_ABORT();
      }
      *depths_[index] = suspended_depths_[index];
    }
  }

  ScopedOnDemandDeclarationTypeSurfaceRole(
      const ScopedOnDemandDeclarationTypeSurfaceRole &) = delete;
  ScopedOnDemandDeclarationTypeSurfaceRole &
  operator=(const ScopedOnDemandDeclarationTypeSurfaceRole &) = delete;

private:
  std::array<unsigned *, 6> depths_;
  std::array<unsigned, 6> suspended_depths_{};
  const clang::Decl *declaration_;
};

static void markClangAstStorageDefined(const void *address, size_t size) {
  markClangAstStorageRangeDefinedForFrontend(address, size);
}

static void markClangPrintedStringDefined(const std::string &value) {
#if ROSE_USE_VALGRIND
  if (clangFrontendRunningOnValgrind()) {
    VALGRIND_MAKE_MEM_DEFINED(const_cast<std::string *>(&value), sizeof(value));
    if (!value.empty()) {
      VALGRIND_MAKE_MEM_DEFINED(const_cast<char *>(value.data()), value.size());
    }
  }
#else
  (void)value;
#endif
}

template <typename T> T *markClangAstObjectDefined(T *node) {
#if ROSE_USE_VALGRIND
  if (clangFrontendRunningOnValgrind()) {
    // Clang's ASTContext uses bump allocation and leaves padding/unused bits in
    // AST objects undefined. REX only reads through Clang's public AST API;
    // make the Clang-owned object storage visible to Memcheck at that boundary.
    VALGRIND_MAKE_MEM_DEFINED(&node, sizeof(node));
    markClangAstStorageDefined(node, sizeof(*node));
  }
#endif
  return node;
}

template <typename T> const T *markClangAstObjectDefined(const T *node) {
#if ROSE_USE_VALGRIND
  if (clangFrontendRunningOnValgrind()) {
    VALGRIND_MAKE_MEM_DEFINED(&node, sizeof(node));
    markClangAstStorageDefined(node, sizeof(*node));
  }
#endif
  return node;
}

template <typename T> const T *markClangLocalObjectDefined(const T *object) {
#if ROSE_USE_VALGRIND
  if (clangFrontendRunningOnValgrind()) {
    VALGRIND_MAKE_MEM_DEFINED(&object, sizeof(object));
    if (object != nullptr) {
      VALGRIND_MAKE_MEM_DEFINED(const_cast<T *>(object), sizeof(*object));
    }
  }
#endif
  return object;
}

template <typename T> const T &markClangValueDefined(const T &value) {
#if ROSE_USE_VALGRIND
  if (clangFrontendRunningOnValgrind()) {
    VALGRIND_MAKE_MEM_DEFINED(const_cast<T *>(&value), sizeof(value));
  }
#endif
  return value;
}

template <typename F>
static auto readClangApiValueDefined(F &&read) -> decltype(read()) {
#if ROSE_USE_VALGRIND
  if (clangFrontendRunningOnValgrind()) {
    VALGRIND_DISABLE_ERROR_REPORTING;
    auto value = read();
    VALGRIND_ENABLE_ERROR_REPORTING;
    markClangValueDefined(value);
    return value;
  }
#endif
  auto value = read();
  markClangValueDefined(value);
  return value;
}

static clang::FileID
exactExpandedEnumBodyFile(clang::EnumDecl *enum_decl,
                          clang::CompilerInstance *compiler_instance) {
  if (enum_decl == nullptr || compiler_instance == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enum-source-ownership]: enum body has "
            "no exact frontend inputs\n");
    ROSE_ABORT();
  }
  clang::SourceManager &source_manager = compiler_instance->getSourceManager();
  const clang::SourceRange brace_range =
      readClangApiValueDefined([&]() { return enum_decl->getBraceRange(); });
  if (!brace_range.isValid()) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enum-source-ownership]: enum=%s "
            "definition has no exact brace range\n",
            enum_decl->getQualifiedNameAsString().c_str());
    ROSE_ABORT();
  }
  const clang::SourceLocation brace_begin = source_manager.getExpansionLoc(
      readClangApiValueDefined([&]() { return brace_range.getBegin(); }));
  const clang::SourceLocation brace_end = source_manager.getExpansionLoc(
      readClangApiValueDefined([&]() { return brace_range.getEnd(); }));
  if (!brace_begin.isValid() || !brace_end.isValid()) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enum-source-ownership]: enum=%s "
            "definition has no exact expanded brace location\n",
            enum_decl->getQualifiedNameAsString().c_str());
    ROSE_ABORT();
  }
  const clang::FileID begin_file = source_manager.getFileID(brace_begin);
  const clang::FileID end_file = source_manager.getFileID(brace_end);
  if (begin_file.isInvalid() || end_file.isInvalid() ||
      begin_file != end_file) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enum-source-ownership]: enum=%s "
            "definition crosses physical source files\n",
            enum_decl->getQualifiedNameAsString().c_str());
    ROSE_ABORT();
  }
  return begin_file;
}

static SgInitializedName::enum_constant_source_ownership_enum
exactEnumConstantSourceRole(clang::EnumConstantDecl *enum_constant,
                            clang::FileID enum_body_file,
                            clang::CompilerInstance *compiler_instance) {
  if (enum_constant == nullptr || enum_body_file.isInvalid() ||
      compiler_instance == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enum-source-ownership]: enum constant "
            "has no exact frontend inputs\n");
    ROSE_ABORT();
  }
  clang::SourceManager &source_manager = compiler_instance->getSourceManager();
  const clang::SourceRange enumerator_range = readClangApiValueDefined(
      [&]() { return enum_constant->getSourceRange(); });
  if (!enumerator_range.isValid()) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enum-source-ownership]: constant=%s has "
            "no exact source range\n",
            enum_constant->getNameAsString().c_str());
    ROSE_ABORT();
  }
  const clang::SourceLocation enumerator_begin = source_manager.getExpansionLoc(
      readClangApiValueDefined([&]() { return enumerator_range.getBegin(); }));
  const clang::SourceLocation enumerator_end = source_manager.getExpansionLoc(
      readClangApiValueDefined([&]() { return enumerator_range.getEnd(); }));
  if (!enumerator_begin.isValid() || !enumerator_end.isValid()) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enum-source-ownership]: constant=%s has "
            "no exact expanded source range\n",
            enum_constant->getNameAsString().c_str());
    ROSE_ABORT();
  }
  const clang::FileID begin_file = source_manager.getFileID(enumerator_begin);
  const clang::FileID end_file = source_manager.getFileID(enumerator_end);
  if (begin_file.isInvalid() || end_file.isInvalid() ||
      begin_file != end_file) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enum-source-ownership]: constant=%s "
            "crosses physical source files\n",
            enum_constant->getNameAsString().c_str());
    ROSE_ABORT();
  }
  return begin_file == enum_body_file
             ? SgInitializedName::e_enum_constant_source_body
             : SgInitializedName::e_enum_constant_source_external;
}

using ClangDeclAttrSnapshot = std::vector<const clang::Attr *>;

static ClangDeclAttrSnapshot clangDeclAttrsDefined(const clang::Decl *decl) {
  ClangDeclAttrSnapshot result;
#if ROSE_USE_VALGRIND
  decl = markClangAstObjectDefined(decl);
  if (clangFrontendRunningOnValgrind()) {
    if (decl == nullptr) {
      return result;
    }

    bool has_attrs = false;
    VALGRIND_DISABLE_ERROR_REPORTING;
    has_attrs = decl->hasAttrs();
    VALGRIND_ENABLE_ERROR_REPORTING;
    VALGRIND_MAKE_MEM_DEFINED(&has_attrs, sizeof(has_attrs));
    if (!has_attrs) {
      return result;
    }

    // Clang stores declaration attributes in ASTContext::DeclAttrs.  Its
    // DenseMap lookup can inspect padding in the separately built Clang DSO,
    // so take one explicit foreign-library snapshot and only traverse the
    // REX-owned copy after this boundary.
    const clang::AttrVec *attrs = nullptr;
    size_t attr_count = 0;
    VALGRIND_DISABLE_ERROR_REPORTING;
    attrs = &decl->getAttrs();
    attr_count = attrs->size();
    VALGRIND_ENABLE_ERROR_REPORTING;
    VALGRIND_MAKE_MEM_DEFINED(&attrs, sizeof(attrs));
    VALGRIND_MAKE_MEM_DEFINED(&attr_count, sizeof(attr_count));
    ROSE_ASSERT(attrs != nullptr);

    result.reserve(attr_count);
    for (size_t index = 0; index < attr_count; ++index) {
      const clang::Attr *attr = nullptr;
      VALGRIND_DISABLE_ERROR_REPORTING;
      attr = (*attrs)[index];
      VALGRIND_ENABLE_ERROR_REPORTING;
      VALGRIND_MAKE_MEM_DEFINED(&attr, sizeof(attr));
      result.push_back(markClangAstObjectDefined(attr));
    }
    return result;
  }
#endif

  if (decl != nullptr && decl->hasAttrs()) {
    const clang::AttrVec &attrs = decl->getAttrs();
    result.assign(attrs.begin(), attrs.end());
  }
  return result;
}

static clang::Decl *markClangDeclObjectDefinedByKind(clang::Decl *decl);

static clang::DeclGroupRef
markClangDeclGroupRefStorageDefined(clang::DeclGroupRef group) {
#if ROSE_USE_VALGRIND
  markClangValueDefined(group);
  if (!clangFrontendRunningOnValgrind() || group.isNull()) {
    return group;
  }

  if (group.isSingleDecl()) {
    markClangDeclObjectDefinedByKind(
        readClangApiValueDefined([&]() { return group.getSingleDecl(); }));
    return group;
  }

  clang::DeclGroup *decl_group_ptr = nullptr;
  VALGRIND_DISABLE_ERROR_REPORTING;
  decl_group_ptr = &group.getDeclGroup();
  VALGRIND_ENABLE_ERROR_REPORTING;
  markClangValueDefined(decl_group_ptr);
  ROSE_ASSERT(decl_group_ptr != nullptr);
  clang::DeclGroup &decl_group = *decl_group_ptr;
  VALGRIND_MAKE_MEM_DEFINED(&decl_group, sizeof(decl_group));
  const unsigned count =
      readClangApiValueDefined([&]() { return decl_group.size(); });
  clang::Decl **begin =
      readClangApiValueDefined([&]() { return group.begin(); });
  if (begin != nullptr && count != 0) {
    VALGRIND_MAKE_MEM_DEFINED(begin, count * sizeof(clang::Decl *));
    for (unsigned i = 0; i < count; ++i) {
      markClangDeclObjectDefinedByKind(begin[i]);
    }
  }
#endif
  return group;
}

static const clang::DeclStmt *
markClangDeclStmtStorageDefined(const clang::DeclStmt *stmt) {
#if ROSE_USE_VALGRIND
  if (!clangFrontendRunningOnValgrind() || stmt == nullptr) {
    return stmt;
  }

  stmt = markClangAstObjectDefined(stmt);
  markClangDeclGroupRefStorageDefined(
      readClangApiValueDefined([&]() { return stmt->getDeclGroup(); }));
  readClangApiValueDefined([&]() { return stmt->getBeginLoc(); });
  readClangApiValueDefined([&]() { return stmt->getEndLoc(); });
#endif
  return stmt;
}

