std::string normalizedDeclFilePath(const clang::Decl *decl,
                                   clang::SourceManager &sm) {
  decl = markClangDeclObjectDefinedByKind(decl);
  if (decl == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[declaration-source-provenance]: path "
            "classification received a null Clang declaration\n");
    ROSE_ABORT();
  }

  clang::SourceLocation loc = decl->getLocation();
  if (loc.isMacroID()) {
    loc = sm.getFileLoc(loc);
  }
  if (!loc.isValid() || sm.isWrittenInBuiltinFile(loc) ||
      sm.isWrittenInCommandLineFile(loc)) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[declaration-source-provenance]: "
            "declaration=%p/%s has no physical header path\n",
            static_cast<const void *>(decl), decl->getDeclKindName());
    ROSE_ABORT();
  }

  const std::string filename = sm.getFilename(loc).str();
  if (filename.empty()) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[declaration-source-provenance]: "
            "declaration=%p/%s has an empty physical filename\n",
            static_cast<const void *>(decl), decl->getDeclKindName());
    ROSE_ABORT();
  }

  return FileHelper::normalizePathIfPossible(filename);
}

std::string normalizedSourceLocationFilePath(clang::SourceLocation location,
                                             clang::SourceManager &sm,
                                             const char *context) {
  if (location.isMacroID()) {
    location = sm.getFileLoc(location);
  }
  if (!location.isValid() || sm.isWrittenInBuiltinFile(location) ||
      sm.isWrittenInCommandLineFile(location)) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[declaration-source-provenance]: "
            "context=%s has no exact physical source location\n",
            context != nullptr ? context : "<null>");
    ROSE_ABORT();
  }
  const std::string filename = sm.getFilename(location).str();
  if (filename.empty()) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[declaration-source-provenance]: "
            "context=%s has an empty physical filename\n",
            context != nullptr ? context : "<null>");
    ROSE_ABORT();
  }
  return FileHelper::normalizePathIfPossible(filename);
}

