static SgFunctionDeclaration::source_return_type_elaboration_kind_enum
functionReturnTypeElaborationKind(
    SgNonrealDecl::source_elaboration_kind_enum kind) {
  switch (kind) {
  case SgNonrealDecl::e_source_elaboration_none:
    return SgFunctionDeclaration::e_source_return_type_elaboration_none;
  case SgNonrealDecl::e_source_elaboration_typename:
    return SgFunctionDeclaration::e_source_return_type_elaboration_typename;
  case SgNonrealDecl::e_source_elaboration_class:
    return SgFunctionDeclaration::e_source_return_type_elaboration_class;
  case SgNonrealDecl::e_source_elaboration_struct:
    return SgFunctionDeclaration::e_source_return_type_elaboration_struct;
  case SgNonrealDecl::e_source_elaboration_union:
    return SgFunctionDeclaration::e_source_return_type_elaboration_union;
  case SgNonrealDecl::e_source_elaboration_enum:
    return SgFunctionDeclaration::e_source_return_type_elaboration_enum;
  case SgNonrealDecl::e_source_elaboration_unspecified:
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[source-return-type-elaboration]: exact "
            "return TypeLoc produced an unspecified elaboration kind\n");
    ROSE_ABORT();
  }
  ROSE_ABORT();
}

