bool ClangToSageTranslator::VisitMSPropertyDecl(
    clang::MSPropertyDecl *ms_property_decl, SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitMSPropertyDecl" << std::endl;
#endif
  ms_property_decl = llvm::dyn_cast_or_null<clang::MSPropertyDecl>(
      markClangDeclObjectDefinedByKind(ms_property_decl));
  if (ms_property_decl == nullptr || node == nullptr) {
    std::cerr << "REX_FRONTEND_INVARIANT[unsupported-ms-property]: Clang "
                 "property translation has no exact declaration or result "
                 "slot"
              << std::endl;
    ROSE_ABORT();
  }

  // Sage has no typed node that can preserve __declspec(property(...)), its
  // getter/setter clauses, and its declaration semantics.  Modeling it as an
  // ordinary variable and then suppressing that variable silently erased
  // source syntax and left a misleading symbol behind.  Reject the construct
  // at the producer boundary until a lossless typed representation exists.
  std::cerr
      << "REX_FRONTEND_INVARIANT[unsupported-ms-property]: source-written "
         "Microsoft property '"
      << ms_property_decl->getQualifiedNameAsString()
      << "' has no lossless typed Sage representation" << std::endl;
  ROSE_ABORT();
}

bool ClangToSageTranslator::VisitNonTypeTemplateParmDecl(
    clang::NonTypeTemplateParmDecl *non_type_template_param_decl,
    SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitNonTypeTemplateParmDecl"
            << std::endl;
#endif

  SgDeclarationStatement *owning_template = resolveTemplateParameterOwner(
      non_type_template_param_decl, /*allow_on_demand=*/true);
  SgTemplateParameter *sg_param = requirePublishedTemplateParameter(
      non_type_template_param_decl, owning_template,
      "VisitNonTypeTemplateParmDecl");

  *node = sg_param;
  return sg_param != nullptr;
}

namespace {

clang::SourceLocation
projectInitializerElementToPhysicalFile(clang::SourceManager &source_manager,
                                        clang::SourceLocation element_location,
                                        clang::FileID owner_file) {
  if (element_location.isInvalid() || !owner_file.isValid()) {
    return clang::SourceLocation();
  }

  clang::SourceLocation current =
      source_manager.getExpansionLoc(element_location);
  std::set<unsigned> visited_files;
  while (current.isValid()) {
    clang::SourceLocation file_location = source_manager.getFileLoc(current);
    clang::FileID file_id = source_manager.getFileID(file_location);
    if (file_location.isInvalid() || !file_id.isValid() ||
        !visited_files.insert(file_id.getHashValue()).second) {
      return clang::SourceLocation();
    }
    if (file_id == owner_file) {
      return file_location;
    }
    current = source_manager.getIncludeLoc(file_id);
  }
  return clang::SourceLocation();
}

unsigned
initializerIncludeDirectiveEndOffset(clang::SourceManager &source_manager,
                                     clang::FileID file_id,
                                     unsigned begin_offset) {
  auto buffer = source_manager.getBufferDataOrNone(file_id);
  if (!buffer || begin_offset >= buffer->size()) {
    return begin_offset;
  }

  unsigned cursor = begin_offset;
  while (cursor < buffer->size()) {
    unsigned line_end = cursor;
    while (line_end < buffer->size() && (*buffer)[line_end] != '\n' &&
           (*buffer)[line_end] != '\r') {
      ++line_end;
    }

    unsigned last_non_space = line_end;
    while (last_non_space > cursor && std::isspace(static_cast<unsigned char>(
                                          (*buffer)[last_non_space - 1]))) {
      --last_non_space;
    }
    const bool continued =
        last_non_space > cursor && (*buffer)[last_non_space - 1] == '\\';

    if (line_end == buffer->size()) {
      return line_end;
    }
    if ((*buffer)[line_end] == '\r' && line_end + 1 < buffer->size() &&
        (*buffer)[line_end + 1] == '\n') {
      cursor = line_end + 2;
    } else {
      cursor = line_end + 1;
    }
    if (!continued) {
      return cursor;
    }
  }
  return cursor;
}

size_t countInitializerOwnerSeparatorTokens(
    clang::SourceManager &source_manager,
    const clang::LangOptions &lang_options, clang::FileID owner_file,
    unsigned begin_offset, unsigned end_offset) {
  if (!owner_file.isValid() || begin_offset > end_offset) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[initializer-owner-separator]: invalid "
            "physical source interval\n");
    ROSE_ABORT();
  }
  if (begin_offset == end_offset) {
    return 0;
  }

  clang::SourceLocation file_start =
      source_manager.getLocForStartOfFile(owner_file);
  if (file_start.isInvalid()) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[initializer-owner-separator]: aggregate "
            "owner has no exact source start\n");
    ROSE_ABORT();
  }

  size_t comma_count = 0;
  clang::SourceLocation cursor = file_start.getLocWithOffset(begin_offset);
  while (cursor.isValid()) {
    clang::Token token;
    if (clang::Lexer::getRawToken(cursor, token, source_manager, lang_options,
                                  /*IgnoreWhiteSpace=*/true)) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[initializer-owner-separator]: exact "
              "source interval could not be tokenized\n");
      ROSE_ABORT();
    }
    clang::SourceLocation token_location =
        source_manager.getFileLoc(token.getLocation());
    if (token_location.isInvalid() ||
        source_manager.getFileID(token_location) != owner_file) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[initializer-owner-separator]: source "
              "interval produced a token outside its aggregate owner\n");
      ROSE_ABORT();
    }
    const unsigned token_offset = source_manager.getFileOffset(token_location);
    if (token_offset >= end_offset || token.is(clang::tok::eof)) {
      break;
    }
    if (token.is(clang::tok::comma)) {
      ++comma_count;
    }
    if (token.getLength() == 0) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[initializer-owner-separator]: exact "
              "source interval produced a zero-length token\n");
      ROSE_ABORT();
    }
    cursor = token_location.getLocWithOffset(token.getLength());
  }
  return comma_count;
}

} // namespace

bool ClangToSageTranslator::VisitVarDecl(clang::VarDecl *var_decl,
                                         SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitVarDecl" << std::endl;
  std::cerr << "isStaticLocal " << var_decl->isStaticLocal() << std::endl;
  std::cerr << "isStaticDataMember " << var_decl->isStaticDataMember()
            << std::endl;
#endif
  var_decl =
      llvm::cast<clang::VarDecl>(markClangDeclObjectDefinedByKind(var_decl));
  var_decl = markClangVarDeclInitStorageDefined(var_decl);
  // std::cerr << "DEBUG: VisitVarDecl for " << var_decl->getNameAsString() <<
  // std::endl;
  if (var_decl->getNameAsString() == "pack") {
    // std::cerr << "DEBUG: VisitVarDecl for pack. Type: " <<
    // var_decl->getType().getAsString() << std::endl;
  }
  bool res = true;

  if (clang::VarTemplateDecl *tmpl = var_decl->getDescribedVarTemplate()) {
    auto it_existing = p_decl_translation_map.find(var_decl);
    if (it_existing != p_decl_translation_map.end()) {
      *node = it_existing->second;
      return true;
    }
    auto it_template = p_decl_translation_map.find(tmpl);
    if (it_template != p_decl_translation_map.end()) {
      p_decl_translation_map[var_decl] = it_template->second;
      *node = it_template->second;
      return true;
    }
    if (p_decl_translation_in_progress.find(tmpl) ==
            p_decl_translation_in_progress.end() &&
        p_decl_translation_on_demand.find(tmpl) ==
            p_decl_translation_on_demand.end()) {
      if (SgNode *translated = TraverseOnDemand(tmpl)) {
        p_decl_translation_map[var_decl] = translated;
        *node = translated;
        return true;
      }
    }
  }

  // Create the SAGE node: SgVariableDeclaration

  SgName name(
      readClangApiValueDefined([&]() { return var_decl->getNameAsString(); }));

  clang::QualType varQualType = markClangQualTypeDefined(
      readClangApiValueDefined([&]() { return var_decl->getType(); }));
  const clang::QualType original_var_type = varQualType;
  const clang::Type *varType =
      markClangTypeObjectDefinedByClass(varQualType.getTypePtr());
  const clang::RecordType *initial_record_type =
      llvm::dyn_cast_or_null<clang::RecordType>(varType);
  const clang::RecordDecl *initial_record_decl =
      initial_record_type != nullptr
          ? markClangSpecificDeclDefined(readClangApiValueDefined(
                [&]() { return initial_record_type->getDecl(); }))
          : nullptr;
  const bool implicit_anonymous_aggregate_source_owner =
      readClangApiValueDefined([&]() { return var_decl->isImplicit(); }) &&
      readClangApiValueDefined(
          [&]() { return var_decl->getIdentifier() == nullptr; }) &&
      initial_record_decl != nullptr && readClangApiValueDefined([&]() {
        return initial_record_decl->isAnonymousStructOrUnion();
      });

  if (p_compiler_instance == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[variable-source-surface]: variable=%s "
            "has no compiler state for its exact source/semantic "
            "classification\n",
            name.getString().c_str());
    ROSE_ABORT();
  }
  const bool variable_preserves_eager_non_main_leaf_surface =
      shouldSuppressDeclNotWrittenInMainFile(
          var_decl, p_compiler_instance->getSourceManager()) &&
      ((shouldEagerlyTraverseApplicationHeaderLeafDecl(
            var_decl, p_compiler_instance, p_sage_preprocessor_recorder) &&
        applicationHeaderHasIndependentPhysicalOutputOwner(
            var_decl, p_compiler_instance)) ||
       shouldEagerlyTraverseNonMainFileLeafDecl(var_decl, p_sage_source_file));
  const bool semantic_template_instantiation_variable =
      declaration_is_within_function_template_instantiation(var_decl) ||
      is_semantic_template_instantiation_record_member(var_decl) ||
      is_instantiated_static_data_member_from_template_pattern(var_decl);
  const bool active_source_function_body_variable =
      activeSourceFunctionBodyDeclStmtOwnsDeclaration(
          var_decl, SageBuilder::topScopeStack());
  const bool variable_owns_lexical_source_surface =
      active_source_function_body_variable ||
      ((!readClangApiValueDefined([&]() { return var_decl->isImplicit(); }) ||
        implicit_anonymous_aggregate_source_owner) &&
       !semantic_template_instantiation_variable &&
       (!shouldSuppressDeclNotWrittenInMainFile(
            var_decl, p_compiler_instance->getSourceManager()) ||
        shouldKeepTextualHeaderDeclForUnparse(var_decl, p_compiler_instance,
                                              p_sage_source_file,
                                              p_sage_preprocessor_recorder) ||
        variable_preserves_eager_non_main_leaf_surface));

#if DEBUG_VISIT_DECL
  // Wrap debug output in conditional to prevent production output
  if (name.getString() == "x") {
    // std::cerr << "DEBUG VarDecl: Variable 'x' has type class = " <<
    // varType->getTypeClassName() << std::endl;
  }
#endif

  // Pei-Hung (06/01/2022) check if the declaration is considered embedded in
  // Clang AST. If it is embedded, no explicit SgDeclaration should be placed
  // for ROSE AST.
  bool isembedded = false;
  bool iscompleteDefined = false;
  bool isDefinitionRequired = false;
  // Definitions embedded in a declarator are not autonomous.
  bool isAutonomousDeclaration = true;

  // Adding check for EaboratedType and PointerType to retrieve base EnumType
  // while((varType->getTypeClass() == clang::Type::Elaborated) ||
  // (varType->getTypeClass() == clang::Type::Pointer) ||
  // (varType->getTypeClass() == clang::Type::Array))
  clang::TagDecl *ownedTagDecl = nullptr;
  varQualType =
      stripQualifiedPointerArrayType(varQualType, nullptr, &ownedTagDecl);
  varType = markClangTypeObjectDefinedByClass(varQualType.getTypePtr());

  // Every Clang declarator in a comma-separated declaration repeats the
  // common declaration-specifier TypeLoc.  The source tag definition or tag
  // introduction in that specifier nevertheless has exactly one physical
  // owner: the first declarator in the atomic declaration group.
  SgDeclarationGroupStatement *active_source_group =
      activeExactSourceDeclarationGroupOwner(var_decl);
  const bool owns_source_declaration_specifier =
      active_source_group == nullptr ||
      active_source_group->get_declarations().empty();

  auto exact_inline_tag_semantic_scope = [&]() -> SgScopeStatement * {
    SgScopeStatement *semantic_scope = SageBuilder::topScopeStack();
    const bool declaration_has_decl_context_scope =
        readClangApiValueDefined([&]() {
          return var_decl->isFileVarDecl() || var_decl->isStaticDataMember();
        });
    if (declaration_has_decl_context_scope) {
      clang::DeclContext *decl_context =
          markClangDeclContextObjectDefined(readClangApiValueDefined(
              [&]() { return var_decl->getDeclContext(); }));
      semantic_scope = resolveScopeFromDeclContext(decl_context);
    }
    semantic_scope = normalizeNamespaceScope(semantic_scope);
    if (semantic_scope == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[embedded-variable-scope]: variable=%s "
              "has no exact semantic scope for its inline tag definition\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    return semantic_scope;
  };

  auto is_inline_tag_definition = [&](clang::TagDecl *tag_decl) -> bool {
    if (tag_decl == nullptr || p_compiler_instance == nullptr ||
        !owns_source_declaration_specifier ||
        !variable_owns_lexical_source_surface) {
      return false;
    }
    if (tagIsSemanticTemplateInstantiation(tag_decl)) {
      return false;
    }
    clang::SourceRange decl_range = clangVarDeclSourceRangeDefined(var_decl);
    if (clang::TypeSourceInfo *tsi =
            markClangTypeSourceInfoDefined(readClangApiValueDefined(
                [&]() { return var_decl->getTypeSourceInfo(); }))) {
      tsi = markClangTypeSourceInfoDefined(tsi);
      clang::TypeLoc type_loc =
          readClangTypeLocDefined([&]() { return tsi->getTypeLoc(); });
      clang::SourceRange type_range =
          readClangApiValueDefined([&]() { return type_loc.getSourceRange(); });
      if (type_range.isValid()) {
        decl_range = type_range;
      }
    }
    if (!decl_range.isValid()) {
      return false;
    }
    return tagDefinitionWrittenInRange(
        tag_decl, decl_range, &p_compiler_instance->getSourceManager());
  };
  auto is_exact_semantic_declarator_owned_tag_definition =
      [&](clang::TagDecl *tag_decl) -> bool {
    if (tag_decl == nullptr || !semantic_template_instantiation_variable ||
        variable_owns_lexical_source_surface ||
        !tagIsSemanticTemplateInstantiation(tag_decl) ||
        !readClangApiValueDefined(
            [&]() { return tag_decl->isThisDeclarationADefinition(); })) {
      return false;
    }

    clang::ASTContext &ast_context = p_compiler_instance->getASTContext();
    auto exact_decl_stmt_parent =
        [&](const clang::Decl *declaration,
            const char *role) -> const clang::DeclStmt * {
      declaration = markClangDeclObjectDefinedByKind(declaration);
      if (declaration == nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[semantic-declarator-tag-owner]: "
                "variable=%s %s declaration is null\n",
                name.getString().c_str(), role);
        ROSE_ABORT();
      }
      const clang::DeclStmt *result = nullptr;
      for (const clang::DynTypedNode &parent :
           ast_context.getParents(*declaration)) {
        markClangValueDefined(parent);
        const clang::DeclStmt *candidate =
            markClangDeclStmtStorageDefined(readClangApiValueDefined(
                [&]() { return parent.get<clang::DeclStmt>(); }));
        if (candidate == nullptr) {
          continue;
        }
        if (result != nullptr && result != candidate) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[semantic-declarator-tag-owner]: "
                  "variable=%s %s=%p belongs to multiple Clang DeclStmt "
                  "owners=%p/%p\n",
                  name.getString().c_str(), role,
                  static_cast<const void *>(declaration),
                  static_cast<const void *>(result),
                  static_cast<const void *>(candidate));
          ROSE_ABORT();
        }
        result = candidate;
      }
      return result;
    };

    const clang::DeclStmt *tag_owner = exact_decl_stmt_parent(tag_decl, "tag");
    const clang::DeclStmt *variable_owner =
        exact_decl_stmt_parent(var_decl, "declarator");
    if (tag_owner == nullptr || variable_owner == nullptr ||
        tag_owner != variable_owner) {
      return false;
    }
    tag_owner = markClangDeclStmtStorageDefined(tag_owner);

    // Clang does not preserve TagDecl::isEmbeddedInDeclarator on the cloned
    // local tag produced while instantiating a function template. The common
    // typed DeclStmt is the authoritative semantic relation: a standalone tag
    // and a later variable have distinct statement parents.
    clang::TagDecl *canonical_tag =
        markClangSpecificDeclDefined(readClangApiValueDefined(
            [&]() { return tag_decl->getCanonicalDecl(); }));
    bool saw_tag = false;
    unsigned tag_occurrences = 0;
    unsigned variable_occurrences = 0;
    clang::VarDecl *first_exact_declarator = nullptr;
    const clang::DeclGroupRef tag_owner_group =
        markClangDeclGroupRefStorageDefined(readClangApiValueDefined(
            [&]() { return tag_owner->getDeclGroup(); }));
    for (clang::Decl *member : tag_owner_group) {
      member = markClangDeclObjectDefinedByKind(member);
      if (member == tag_decl) {
        saw_tag = true;
        ++tag_occurrences;
        continue;
      }
      if (member == var_decl) {
        ++variable_occurrences;
      }
      clang::VarDecl *candidate =
          llvm::dyn_cast_or_null<clang::VarDecl>(member);
      if (!saw_tag || candidate == nullptr ||
          first_exact_declarator != nullptr) {
        continue;
      }
      clang::QualType candidate_type = stripQualifiedPointerArrayType(
          markClangQualTypeDefined(readClangApiValueDefined(
              [&]() { return candidate->getType(); })));
      const clang::Type *base_type =
          markClangTypeObjectDefinedByClass(candidate_type.getTypePtrOrNull());
      clang::TagDecl *candidate_tag =
          base_type != nullptr
              ? markClangSpecificDeclDefined(base_type->getAsTagDecl())
              : nullptr;
      if (candidate_tag != nullptr &&
          markClangSpecificDeclDefined(readClangApiValueDefined([&]() {
            return candidate_tag->getCanonicalDecl();
          })) == canonical_tag) {
        first_exact_declarator = candidate;
      }
    }

    if (tag_occurrences != 1 || variable_occurrences != 1 ||
        first_exact_declarator == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[semantic-declarator-tag-owner]: "
              "variable=%s DeclStmt=%p contains tag/declarator %u/%u times "
              "and first exact typed declarator=%p\n",
              name.getString().c_str(), static_cast<const void *>(tag_owner),
              tag_occurrences, variable_occurrences,
              static_cast<void *>(first_exact_declarator));
      ROSE_ABORT();
    }

    // A shared declaration specifier belongs to the first matching declarator
    // in its atomic DeclStmt. Later comma-separated declarators refer to the
    // same tag identity but do not acquire a second defining child.
    return first_exact_declarator == var_decl;
  };
  SgDeclarationStatement *materialized_inline_tag_definition = nullptr;
  auto materialize_inline_tag_definition = [&](clang::TagDecl *tag_decl) {
    if (tag_decl == nullptr) {
      return;
    }
    if (materialized_inline_tag_definition != nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[embedded-variable-producer]: "
              "variable=%s attempted to materialize multiple inline tag "
              "definitions\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    beginTypedOwnerTagConstruction(tag_decl, exact_inline_tag_semantic_scope(),
                                   "VisitVarDecl:inline-tag-definition");
    (void)lookupSgDeclarationForClangDecl(tag_decl, /*allow_on_demand=*/true);
    materialized_inline_tag_definition = finishTypedOwnerTagConstruction(
        tag_decl, "VisitVarDecl:inline-tag-definition");
  };

  clang::RecordDecl *embeddedRecordDecl = nullptr;
  clang::EnumDecl *embeddedEnumDecl = nullptr;
  bool semantic_declarator_owned_tag_definition = false;
  auto lookup_embedded_record_decl =
      [&](clang::RecordDecl *record_decl) -> SgClassDeclaration * {
    if (record_decl == nullptr) {
      return nullptr;
    }
    SgClassDeclaration *sg_decl = isSgClassDeclaration(
        lookupExactSgDeclarationForClangDecl(record_decl,
                                             /*allow_on_demand=*/true));
    if (sg_decl == nullptr) {
      sg_decl = isSgClassDeclaration(lookupSgDeclarationForClangDecl(
          record_decl, /*allow_on_demand=*/true));
    }
    if (sg_decl == nullptr) {
      return nullptr;
    }
    if (SgClassDeclaration *def_decl =
            isSgClassDeclaration(sg_decl->get_definingDeclaration())) {
      return def_decl;
    }
    return sg_decl;
  };
  auto lookup_embedded_enum_decl =
      [&](clang::EnumDecl *enum_decl) -> SgEnumDeclaration * {
    if (enum_decl == nullptr) {
      return nullptr;
    }
    SgEnumDeclaration *sg_decl = isSgEnumDeclaration(
        lookupExactSgDeclarationForClangDecl(enum_decl,
                                             /*allow_on_demand=*/true));
    if (sg_decl == nullptr) {
      sg_decl = isSgEnumDeclaration(
          lookupSgDeclarationForClangDecl(enum_decl, /*allow_on_demand=*/true));
    }
    if (sg_decl == nullptr) {
      return nullptr;
    }
    if (SgEnumDeclaration *def_decl =
            isSgEnumDeclaration(sg_decl->get_definingDeclaration())) {
      return def_decl;
    }
    return sg_decl;
  };

  if (llvm::isa<clang::EnumType>(varType)) {
    clang::EnumType *underlyingEnumType = (clang::EnumType *)varType;
    clang::EnumDecl *enumDeclaration = underlyingEnumType->getDecl();
    if (clang::EnumDecl *writtenEnum =
            llvm::dyn_cast_or_null<clang::EnumDecl>(ownedTagDecl)) {
      if (is_inline_tag_definition(writtenEnum)) {
        enumDeclaration = writtenEnum;
      }
    }
    const bool inline_tag_definition =
        is_inline_tag_definition(enumDeclaration);
    const bool semantic_tag_definition =
        is_exact_semantic_declarator_owned_tag_definition(enumDeclaration);
    // For declarator-owned definitions, trust the written type range rather
    // than the tag's semantic context. In C, Clang can place a nested named
    // tag into translation-unit scope even when its definition is spelled
    // inline as part of the declarator.
    iscompleteDefined = enumDeclaration->isThisDeclarationADefinition() &&
                        (inline_tag_definition || semantic_tag_definition);
    isembedded = iscompleteDefined;
    if (isembedded) {
      embeddedEnumDecl = enumDeclaration;
      semantic_declarator_owned_tag_definition = semantic_tag_definition;
      if (inline_tag_definition) {
        materialize_inline_tag_definition(enumDeclaration);
      }
    }
  }

  if (llvm::isa<clang::RecordType>(varType)) {
    clang::RecordType *underlyingRecordType = (clang::RecordType *)varType;
    clang::RecordDecl *recordDeclaration = underlyingRecordType->getDecl();
    if (clang::RecordDecl *writtenRecord =
            llvm::dyn_cast_or_null<clang::RecordDecl>(ownedTagDecl)) {
      if (is_inline_tag_definition(writtenRecord)) {
        recordDeclaration = writtenRecord;
      }
    }
    const bool inline_tag_definition =
        is_inline_tag_definition(recordDeclaration);
    const bool semantic_tag_definition =
        is_exact_semantic_declarator_owned_tag_definition(recordDeclaration);
    // For declarator-owned definitions, trust the written type range rather
    // than the tag's semantic context. In C, Clang can place a nested named
    // tag into translation-unit scope even when its definition is spelled
    // inline as part of the declarator.
    iscompleteDefined = recordDeclaration->isThisDeclarationADefinition() &&
                        (inline_tag_definition || semantic_tag_definition);
    isembedded = iscompleteDefined;
    if (isembedded) {
      embeddedRecordDecl = recordDeclaration;
      semantic_declarator_owned_tag_definition = semantic_tag_definition;
      if (inline_tag_definition) {
        materialize_inline_tag_definition(recordDeclaration);
      }
    }
  }

  // Only inline tag definitions owned by this declarator should be attached as
  // base-type defining declarations.
  isDefinitionRequired = iscompleteDefined;

  bool isStaticDataMember = readClangApiValueDefined(
      [&]() { return var_decl->isStaticDataMember(); });
  bool isOutOfLineStaticMember = is_out_of_line_static_data_member(var_decl);
  auto defined_var_decl_context = [&]() -> clang::DeclContext * {
    return const_cast<clang::DeclContext *>(
        markClangDeclContextObjectDefined(readClangApiValueDefined(
            [&]() { return var_decl->getDeclContext(); })));
  };
  auto defined_var_lexical_context = [&]() -> clang::DeclContext * {
    return const_cast<clang::DeclContext *>(
        markClangDeclContextObjectDefined(readClangApiValueDefined(
            [&]() { return var_decl->getLexicalDeclContext(); })));
  };
  auto defined_var_record_context = [&]() -> clang::RecordDecl * {
    clang::DeclContext *ctx = defined_var_decl_context();
    auto *record_ctx = llvm::dyn_cast_or_null<clang::RecordDecl>(ctx);
    return llvm::dyn_cast_or_null<clang::RecordDecl>(
        markClangDeclObjectDefinedByKind(record_ctx));
  };
  const bool var_is_file_var_decl =
      readClangApiValueDefined([&]() { return var_decl->isFileVarDecl(); });
  const bool var_is_constexpr =
      readClangApiValueDefined([&]() { return var_decl->isConstexpr(); });
  const bool var_is_direct_init =
      readClangApiValueDefined([&]() { return var_decl->isDirectInit(); });
  const bool var_is_init_capture =
      readClangApiValueDefined([&]() { return var_decl->isInitCapture(); });
  const clang::VarDecl::InitializationStyle var_init_style =
      readClangApiValueDefined([&]() { return var_decl->getInitStyle(); });

  const unsigned semantic_template_header_count = readClangApiValueDefined(
      [&]() { return var_decl->getNumTemplateParameterLists(); });
  std::vector<clang::TemplateParameterList *> written_template_headers;
  written_template_headers.reserve(semantic_template_header_count);
  for (unsigned header_index = 0; header_index < semantic_template_header_count;
       ++header_index) {
    clang::TemplateParameterList *clang_header =
        markClangTemplateParameterListDefined(readClangApiValueDefined([&]() {
          return var_decl->getTemplateParameterList(header_index);
        }));
    if (clang_header == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-template-header]: "
              "variable=%s semantic header=%u/%u is null\n",
              var_decl->getQualifiedNameAsString().c_str(), header_index,
              semantic_template_header_count);
      ROSE_ABORT();
    }

    clang::SourceLocation template_loc = readClangApiValueDefined(
        [&]() { return clang_header->getTemplateLoc(); });
    if (!template_loc.isValid()) {
      continue;
    }
    if (p_compiler_instance != nullptr &&
        !sourceRangeContainsLocation(
            clangVarDeclSourceRangeDefined(var_decl), template_loc,
            &p_compiler_instance->getSourceManager())) {
      continue;
    }
    written_template_headers.push_back(clang_header);
  }

  ClangTemplateParameterNameMap exact_written_variable_parameter_names;
  for (clang::TemplateParameterList *header : written_template_headers) {
    for (const clang::NamedDecl *parameter : *header) {
      parameter = llvm::dyn_cast_or_null<clang::NamedDecl>(
          markClangDeclObjectDefinedByKind(parameter));
      if (parameter == nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-template-header]: "
                "variable=%s contains a non-named template parameter\n",
                var_decl->getQualifiedNameAsString().c_str());
        ROSE_ABORT();
      }

      unsigned depth = 0;
      unsigned index = 0;
      if (const clang::TemplateTypeParmDecl *type_parameter =
              llvm::dyn_cast<clang::TemplateTypeParmDecl>(parameter)) {
        depth = type_parameter->getDepth();
        index = type_parameter->getIndex();
      } else if (const clang::NonTypeTemplateParmDecl *non_type_parameter =
                     llvm::dyn_cast<clang::NonTypeTemplateParmDecl>(
                         parameter)) {
        depth = non_type_parameter->getDepth();
        index = non_type_parameter->getIndex();
      } else if (const clang::TemplateTemplateParmDecl *template_parameter =
                     llvm::dyn_cast<clang::TemplateTemplateParmDecl>(
                         parameter)) {
        depth = template_parameter->getDepth();
        index = template_parameter->getIndex();
      } else {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-template-header]: "
                "variable=%s has unsupported template parameter kind=%s\n",
                var_decl->getQualifiedNameAsString().c_str(),
                parameter->getDeclKindName());
        ROSE_ABORT();
      }

      const std::string parameter_name =
          normalizeClangTemplateParamName(parameter->getNameAsString());
      auto inserted = exact_written_variable_parameter_names.emplace(
          std::make_pair(depth, index),
          ClangTemplateParameterIdentity{
              parameter_name, const_cast<clang::NamedDecl *>(parameter)});
      if (!inserted.second &&
          (inserted.first->second.name != parameter_name ||
           inserted.first->second.declaration != parameter)) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-template-header]: "
                "variable=%s depth=%u index=%u has conflicting source names "
                "'%s' and '%s'\n",
                var_decl->getQualifiedNameAsString().c_str(), depth, index,
                inserted.first->second.name.c_str(), parameter_name.c_str());
        ROSE_ABORT();
      }
    }
  }
  const bool has_exact_written_variable_parameter_names =
      !exact_written_variable_parameter_names.empty();
  if (has_exact_written_variable_parameter_names) {
    p_exact_template_parameter_name_stack.push_back(
        std::move(exact_written_variable_parameter_names));
  }
  struct ExactWrittenVariableParameterGuard {
    ClangTemplateParameterNameContextStack &stack;
    bool active;
    ~ExactWrittenVariableParameterGuard() {
      if (active) {
        ROSE_ASSERT(!stack.empty());
        stack.pop_back();
      }
    }
  } exact_written_variable_parameter_guard{
      p_exact_template_parameter_name_stack,
      has_exact_written_variable_parameter_names};

  SgScopeStatement *written_template_semantic_scope = nullptr;
  std::vector<std::unique_ptr<SgTemplateParameterPtrList>>
      translated_written_template_headers;
  translated_written_template_headers.reserve(written_template_headers.size());
  const size_t written_template_surface_stack_base =
      p_template_parameter_surface_stack.size();
  if (!written_template_headers.empty()) {
    if (!isOutOfLineStaticMember) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-template-header-owner]: "
              "variable=%s has %u written enclosing template headers but is "
              "not an out-of-line static data member\n",
              var_decl->getQualifiedNameAsString().c_str(),
              static_cast<unsigned>(written_template_headers.size()));
      ROSE_ABORT();
    }
    written_template_semantic_scope =
        resolveScopeFromDeclContext(defined_var_decl_context());
    if (isSgClassDefinition(written_template_semantic_scope) == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-template-header-owner]: "
              "variable=%s has no exact semantic class-definition scope for "
              "its written enclosing template headers\n",
              var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }

    std::set<const clang::TemplateParameterList *> exact_headers;
    for (size_t header_index = 0;
         header_index < written_template_headers.size(); ++header_index) {
      clang::TemplateParameterList *clang_header =
          written_template_headers[header_index];
      if (clang_header == nullptr ||
          !exact_headers.insert(clang_header).second) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-template-header]: "
                "variable=%s header=%zu is null or duplicated in one exact "
                "source transaction\n",
                var_decl->getQualifiedNameAsString().c_str(), header_index);
        ROSE_ABORT();
      }

      std::unique_ptr<SgTemplateParameterPtrList> translated_header =
          translateDetachedTemplateParameterList(
              clang_header, written_template_semantic_scope);
      if (translated_header == nullptr ||
          translated_header->size() != clang_header->size()) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-template-header]: "
                "variable=%s header=%zu translated %zu of %u parameters\n",
                var_decl->getQualifiedNameAsString().c_str(), header_index,
                translated_header != nullptr ? translated_header->size() : 0,
                clang_header->size());
        ROSE_ABORT();
      }
      clearTranslatedTemplateParameterDefaults(*translated_header, clang_header,
                                               false);
      p_template_parameter_surface_stack.push_back(
          {clang_header, translated_header.get()});
      translated_written_template_headers.push_back(
          std::move(translated_header));
    }
  }
  struct WrittenVariableTemplateSurfaceGuard {
    std::vector<TemplateParameterSurfaceFrame> &stack;
    const std::vector<clang::TemplateParameterList *> &clang_headers;
    const std::vector<std::unique_ptr<SgTemplateParameterPtrList>>
        &sage_headers;
    size_t base_size;
    ~WrittenVariableTemplateSurfaceGuard() {
      if (clang_headers.size() != sage_headers.size() ||
          stack.size() != base_size + clang_headers.size()) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-template-parameter-"
                "surface]: written static-member transaction changed its "
                "exact active surface count\n");
        ROSE_ABORT();
      }
      for (size_t index = 0; index < clang_headers.size(); ++index) {
        const TemplateParameterSurfaceFrame &frame = stack[base_size + index];
        if (frame.clang_parameters != clang_headers[index] ||
            frame.sage_parameters != sage_headers[index].get() ||
            frame.owner != nullptr || frame.semantic_parameters != nullptr ||
            frame.construction_scope != nullptr) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[variable-template-parameter-"
                  "surface]: written static-member header=%zu lost its exact "
                  "Clang/Sage construction identity\n",
                  index);
          ROSE_ABORT();
        }
      }
      stack.resize(base_size);
    }
  } written_variable_template_surface_guard{
      p_template_parameter_surface_stack, written_template_headers,
      translated_written_template_headers, written_template_surface_stack_base};

  const clang::DeclContext *var_type_decl_context =
      isOutOfLineStaticMember ? defined_var_decl_context() : nullptr;
  if (var_type_decl_context != nullptr) {
    ++p_preserve_current_class_qualifier_depth;
    p_template_parameter_decl_context_stack.push_back(var_type_decl_context);
  }

  // A source-written placeholder type owns its spelling independently of the
  // deduced semantic type.  In particular, Clang exposes a lambda closure as
  // the semantic type of `auto value = [] { ... };`.  Translating that type
  // before the initializer would construct the closure before VisitLambdaExpr
  // can publish its exact physical-output ownership transaction.
  bool written_variable_type_contains_auto = false;
  if (variable_owns_lexical_source_surface) {
    if (clang::TypeSourceInfo *type_info =
            markClangTypeSourceInfoDefined(readClangApiValueDefined(
                [&]() { return var_decl->getTypeSourceInfo(); }))) {
      clang::TypeLoc type_loc =
          readClangTypeLocDefined([&]() { return type_info->getTypeLoc(); });
      written_variable_type_contains_auto = typeLocContainsAutoType(type_loc);
    }
  }
  SgType *sg_varType = written_variable_type_contains_auto
                           ? nullptr
                           : buildTypeFromQualifiedType(varQualType);
  SgType *type = nullptr;
  SgType *cxx_source_type = nullptr;
  bool written_type_spells_elaborated_keyword = false;
  bool written_type_spells_elaborated_tag_keyword = false;
  clang::TagDecl *written_variable_tag_decl = nullptr;
  clang::NestedNameSpecifierLoc written_type_qualifier_loc;
  bool saw_written_var_type_loc = false;
  bool constexpr_top_level_const_is_implicit = false;
  if (!variable_owns_lexical_source_surface) {
    type = buildSemanticTypeFromQualifiedType(
        original_var_type, "VisitVarDecl:semantic-variable-type");
  } else if (clang::TypeSourceInfo *type_info =
                 markClangTypeSourceInfoDefined(readClangApiValueDefined(
                     [&]() { return var_decl->getTypeSourceInfo(); }))) {
    clang::TypeLoc type_loc =
        readClangTypeLocDefined([&]() { return type_info->getTypeLoc(); });
    saw_written_var_type_loc = !type_loc.isNull();
    markClangTypeObjectDefinedByClass(type_loc.getTypePtr());
    if (var_is_constexpr && !var_decl->isImplicit() &&
        original_var_type.isLocalConstQualified()) {
      constexpr_top_level_const_is_implicit =
          !sourceSpellsTopLevelConstQualifier(var_decl, type_loc,
                                              p_compiler_instance);
    }
    written_type_spells_elaborated_keyword =
        typeLocSpellsDirectElaboratedKeyword(type_loc);
    written_type_spells_elaborated_tag_keyword =
        typeLocSpellsDirectElaboratedTagKeyword(type_loc);
    written_variable_tag_decl = typeLocSpellsDirectTagDecl(type_loc);
    written_type_qualifier_loc = typeLocQualifierLoc(type_loc);
    SgType *shared_group_type = nullptr;
    if (active_source_group != nullptr &&
        !active_source_group->get_declarations().empty()) {
      const SourceDeclarationGroupConstruction *construction = nullptr;
      for (const SourceDeclarationGroupConstruction &candidate :
           p_source_declaration_group_constructions) {
        if (candidate.group != active_source_group) {
          continue;
        }
        if (construction != nullptr) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[source-declaration-group-type]: "
                  "group=%p has multiple active construction records\n",
                  static_cast<void *>(active_source_group));
          ROSE_ABORT();
        }
        construction = &candidate;
      }

      clang::VarDecl *first_clang_variable =
          construction != nullptr && !construction->clang_members.empty()
              ? llvm::dyn_cast_or_null<clang::VarDecl>(
                    construction->clang_members.front())
              : nullptr;
      SgVariableDeclaration *first_sage_variable = isSgVariableDeclaration(
          active_source_group->get_declarations().front());
      clang::TypeSourceInfo *first_type_info =
          first_clang_variable != nullptr
              ? markClangTypeSourceInfoDefined(readClangApiValueDefined([&]() {
                  return first_clang_variable->getTypeSourceInfo();
                }))
              : nullptr;
      SgInitializedName *first_initialized_name =
          first_sage_variable != nullptr
              ? SageInterface::getFirstInitializedName(first_sage_variable)
              : nullptr;
      if (first_clang_variable != nullptr && first_type_info != nullptr &&
          first_sage_variable != nullptr && first_initialized_name != nullptr) {
        clang::TypeLoc first_type_loc = readClangTypeLocDefined(
            [&]() { return first_type_info->getTypeLoc(); });
        const clang::SourceRange first_type_range = readClangApiValueDefined(
            [&]() { return first_type_loc.getSourceRange(); });
        const clang::SourceRange current_type_range = readClangApiValueDefined(
            [&]() { return type_loc.getSourceRange(); });
        const bool same_semantic_type =
            p_compiler_instance != nullptr && readClangApiValueDefined([&]() {
              return p_compiler_instance->getASTContext().hasSameType(
                  first_clang_variable->getType(), var_decl->getType());
            });
        const bool same_exact_type_surface =
            !first_type_loc.isNull() &&
            first_type_loc.getTypeLocClass() == type_loc.getTypeLocClass() &&
            first_type_range.isValid() && current_type_range.isValid() &&
            first_type_range.getBegin() == current_type_range.getBegin() &&
            first_type_range.getEnd() == current_type_range.getEnd();
        if (same_semantic_type && same_exact_type_surface) {
          shared_group_type = first_initialized_name->get_type();
          if (shared_group_type == nullptr ||
              first_sage_variable->get_parent() != active_source_group) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[source-declaration-group-type]: "
                    "group=%p first variable has no exact published type "
                    "identity\n",
                    static_cast<void *>(active_source_group));
            ROSE_ABORT();
          }
        }
      }
    }
    type = shared_group_type != nullptr ? shared_group_type
                                        : buildTypeFromTypeLoc(type_loc);
    struct MemberPointerTypeRoles {
      bool source = false;
      bool semantic = false;
      bool valid_semantic_identity = true;
    };
    auto member_pointer_type_roles = [](SgType *root) {
      MemberPointerTypeRoles roles;
      std::unordered_set<SgType *> seen;
      std::function<void(SgType *)> visit = [&](SgType *current) {
        if (current == nullptr || !seen.insert(current).second) {
          return;
        }
        if (SgPointerMemberType *member_pointer =
                isSgPointerMemberType(current)) {
          if (SgPointerMemberType::isCanonicalSemanticType(member_pointer)) {
            roles.semantic = true;
            roles.valid_semantic_identity =
                roles.valid_semantic_identity &&
                SageBuilder::buildPointerMemberType(
                    member_pointer->get_base_type(),
                    member_pointer->get_class_type()) == member_pointer;
          } else {
            roles.source = true;
          }
        }
        for (const auto &successor : current->returnDataMemberPointers()) {
          if (SgType *child = isSgType(successor.first)) {
            visit(child);
          }
        }
      };
      visit(root);
      return roles;
    };
    const MemberPointerTypeRoles source_type_roles =
        member_pointer_type_roles(type);
    if (source_type_roles.source) {
      SgType *semantic_declarator_type =
          buildTypeFromQualifiedType(original_var_type);
      const MemberPointerTypeRoles semantic_type_roles =
          member_pointer_type_roles(semantic_declarator_type);
      if (semantic_declarator_type == nullptr ||
          type == semantic_declarator_type || semantic_type_roles.source ||
          !semantic_type_roles.semantic ||
          !semantic_type_roles.valid_semantic_identity) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-pointer-member-type]: "
                "variable=%s did not separate its exact source graph from "
                "canonical semantic member-pointer identities\n",
                var_decl->getQualifiedNameAsString().c_str());
        ROSE_ABORT();
      }

      // SgInitializedName::type is the declaration's semantic type.  A
      // MemberPointerTypeLoc deliberately produces a per-use wrapper so that
      // translating source spelling cannot mutate the canonical type; that
      // wrapper must not escape into the semantic initialized-name edge.
      // Explicit spelling is carried by the declaration use site's typed
      // qualification fields and by the source declaration group.
      type = semantic_declarator_type;
    }
    const bool preserve_semantic_elaborated_tag_type =
        written_type_spells_elaborated_keyword && !original_var_type.isNull() &&
        !original_var_type->isDependentType() && !written_type_qualifier_loc;
    if (preserve_semantic_elaborated_tag_type &&
        isSgNonrealType(type) != nullptr && sg_varType != nullptr) {
      type = sg_varType;
    }

    auto find_template_specialization_loc =
        [](clang::TypeLoc type_loc) -> clang::TemplateSpecializationTypeLoc {
      markClangTypeLocDataDefined(type_loc);
      while (!type_loc.isNull()) {
        markClangTypeLocDataDefined(type_loc);
        markClangTypeObjectDefinedByClass(type_loc.getTypePtr());
        if (auto spec_loc =
                type_loc.getAs<clang::TemplateSpecializationTypeLoc>()) {
          markClangTypeLocDataDefined(spec_loc);
          markClangTypeObjectDefinedByClass(spec_loc.getTypePtr());
          return spec_loc;
        }
        type_loc = type_loc.getNextTypeLoc();
      }
      return clang::TemplateSpecializationTypeLoc();
    };

    // Preserve semantic class types for ordinary template specializations such
    // as `X<A> a;`. Keeping the written spelling as SgNonrealType here loses
    // the instantiated class identity needed by downstream analyses and
    // member-call resolution.
    if (isSgNonrealType(type) != nullptr &&
        isSgClassType(sg_varType) != nullptr) {
      clang::TemplateSpecializationTypeLoc spec_loc =
          find_template_specialization_loc(type_info->getTypeLoc());
      if (!spec_loc.isNull()) {
        markClangTypeLocDataDefined(spec_loc);
        markClangTypeObjectDefinedByClass(spec_loc.getTypePtr());
        if (isSgNonrealType(type) != nullptr) {
          SgNonrealType *written_nonreal_type = isSgNonrealType(type);
          SgNonrealDecl *written_nonreal_decl =
              isSgNonrealDecl(written_nonreal_type != nullptr
                                  ? written_nonreal_type->get_declaration()
                                  : nullptr);
          SgClassType *semantic_class_type = isSgClassType(sg_varType);
          SgClassDeclaration *semantic_class_decl =
              isSgClassDeclaration(semantic_class_type != nullptr
                                       ? semantic_class_type->get_declaration()
                                       : nullptr);
          SgTemplateInstantiationDecl *semantic_instantiation =
              isSgTemplateInstantiationDecl(semantic_class_decl);
          if (semantic_instantiation == nullptr &&
              semantic_class_decl != nullptr) {
            semantic_instantiation = isSgTemplateInstantiationDecl(
                semantic_class_decl->get_firstNondefiningDeclaration());
          }
          if (semantic_instantiation == nullptr &&
              semantic_class_decl != nullptr) {
            semantic_instantiation = isSgTemplateInstantiationDecl(
                semantic_class_decl->get_definingDeclaration());
          }
          if (written_nonreal_decl == nullptr ||
              semantic_instantiation == nullptr) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[variable-template-type-surface]: "
                    "variable=%s cannot replace its written template-id "
                    "type=%p/%s with semantic type=%p/%s without exact "
                    "written and semantic declarations\n",
                    var_decl->getQualifiedNameAsString().c_str(),
                    static_cast<void *>(type),
                    type != nullptr ? type->class_name().c_str() : "<null>",
                    static_cast<void *>(sg_varType),
                    sg_varType != nullptr ? sg_varType->class_name().c_str()
                                          : "<null>");
            ROSE_ABORT();
          }

          const SgTemplateArgumentPtrList &written_arguments =
              written_nonreal_decl->get_tpl_args();
          SgTemplateArgumentPtrList &semantic_arguments =
              semantic_instantiation->get_templateArguments();
          const clang::RecordType *semantic_record_type =
              readClangApiValueDefined([&]() {
                return var_decl->getType()->getAs<clang::RecordType>();
              });
          clang::ClassTemplateSpecializationDecl *clang_semantic_instantiation =
              semantic_record_type != nullptr
                  ? llvm::dyn_cast<clang::ClassTemplateSpecializationDecl>(
                        markClangDeclObjectDefinedByKind(
                            semantic_record_type->getDecl()))
                  : nullptr;
          const clang::TemplateArgumentList *clang_semantic_arguments =
              clang_semantic_instantiation != nullptr
                  ? markClangTemplateArgumentListDefined(
                        &clang_semantic_instantiation->getTemplateArgs())
                  : nullptr;
          if (semantic_arguments.size() < written_arguments.size()) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[variable-template-type-surface]: "
                    "variable=%s has %zu exact written template arguments "
                    "but semantic instantiation=%p/%s has %zu arguments\n",
                    var_decl->getQualifiedNameAsString().c_str(),
                    written_arguments.size(),
                    static_cast<void *>(semantic_instantiation),
                    semantic_instantiation->get_name().getString().c_str(),
                    semantic_arguments.size());
            ROSE_ABORT();
          }
          std::vector<clang::TemplateArgument>
              flattened_clang_semantic_arguments;
          if (clang_semantic_arguments != nullptr) {
            std::function<void(const clang::TemplateArgument &)>
                append_flattened_argument =
                    [&](const clang::TemplateArgument &argument) {
                      markClangTemplateArgumentDefined(argument);
                      if (argument.getKind() == clang::TemplateArgument::Pack) {
                        for (const clang::TemplateArgument &pack_element :
                             markClangTemplateArgumentArrayDefined(
                                 argument.pack_elements())) {
                          append_flattened_argument(pack_element);
                        }
                        return;
                      }
                      flattened_clang_semantic_arguments.push_back(argument);
                    };
            for (unsigned index = 0; index < clang_semantic_arguments->size();
                 ++index) {
              append_flattened_argument(clang_semantic_arguments->get(index));
            }
          }
          if (clang_semantic_arguments == nullptr ||
              flattened_clang_semantic_arguments.size() <
                  written_arguments.size() ||
              spec_loc.getNumArgs() != written_arguments.size()) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[variable-template-type-"
                    "surface]: variable=%s has no exact Clang written-to-"
                    "semantic argument correspondence written=%zu "
                    "TypeLoc=%u semantic=%u flattened-semantic=%zu\n",
                    var_decl->getQualifiedNameAsString().c_str(),
                    written_arguments.size(), spec_loc.getNumArgs(),
                    clang_semantic_arguments != nullptr
                        ? clang_semantic_arguments->size()
                        : 0,
                    flattened_clang_semantic_arguments.size());
            ROSE_ABORT();
          }

          for (size_t index = 0; index < written_arguments.size(); ++index) {
            SgTemplateArgument *written_argument = written_arguments[index];
            SgTemplateArgument *semantic_argument = semantic_arguments[index];
            // TemplateArgumentLoc::getArgument() returns a value.  Keep the
            // value alive locally before passing it through the Valgrind
            // boundary helper; binding the helper's returned reference
            // directly would leave a dangling reference to the temporary.
            clang::TemplateArgument clang_written_argument =
                spec_loc.getArgLoc(index).getArgument();
            markClangTemplateArgumentDefined(clang_written_argument);
            clang::TemplateArgument clang_semantic_argument =
                flattened_clang_semantic_arguments[index];
            markClangTemplateArgumentDefined(clang_semantic_argument);
            bool exact_clang_identity =
                var_decl->getASTContext().isSameTemplateArgument(
                    clang_written_argument, clang_semantic_argument);
            if (!exact_clang_identity &&
                clang_written_argument.getKind() ==
                    clang::TemplateArgument::Expression &&
                clang_semantic_argument.getKind() ==
                    clang::TemplateArgument::Integral) {
              // Clang retains the exact written expression in TypeLoc while
              // the specialization owns its evaluated integral argument.
              // Prove their correspondence with Clang's constant evaluator;
              // textual or SAGE-mangle equality would incorrectly require
              // the source and semantic representations to be identical.
              clang::Expr *written_expression =
                  clang_written_argument.getAsExpr();
              clang::Expr::EvalResult evaluation;
              exact_clang_identity =
                  written_expression != nullptr &&
                  written_expression->EvaluateAsInt(
                      evaluation, var_decl->getASTContext()) &&
                  evaluation.Val.isInt() &&
                  var_decl->getASTContext().hasSameType(
                      written_expression->getType(),
                      clang_semantic_argument.getIntegralType()) &&
                  llvm::APSInt::isSameValue(
                      evaluation.Val.getInt(),
                      clang_semantic_argument.getAsIntegral());
            }
            if (!exact_clang_identity &&
                clang_written_argument.getKind() ==
                    clang::TemplateArgument::Expression &&
                clang_semantic_argument.getKind() ==
                    clang::TemplateArgument::Declaration) {
              // TypeLoc retains the exact source expression for converted
              // non-type arguments such as `X<array>` and `X<&S::member>`,
              // while the specialization canonicalizes the same value to its
              // declaration identity.  Prove that correspondence through
              // Clang constant evaluation.  A textual or Sage-expression
              // comparison cannot establish overload resolution, array decay,
              // or qualification conversions.
              clang::Expr *written_expression =
                  clang_written_argument.getAsExpr();
              clang::ValueDecl *semantic_declaration =
                  llvm::dyn_cast_or_null<clang::ValueDecl>(
                      markClangDeclObjectDefinedByKind(
                          clang_semantic_argument.getAsDecl()));
              const clang::Expr *written_identity_expression =
                  written_expression != nullptr
                      ? written_expression->IgnoreParenImpCasts()
                      : nullptr;
              const clang::DeclRefExpr *written_decl_ref =
                  llvm::dyn_cast_or_null<clang::DeclRefExpr>(
                      written_identity_expression);
              const clang::ValueDecl *written_referenced_declaration =
                  written_decl_ref != nullptr ? markClangSpecificDeclDefined(
                                                    written_decl_ref->getDecl())
                                              : nullptr;
              const clang::QualType semantic_parameter_type =
                  markClangQualTypeDefined(
                      clang_semantic_argument.getParamTypeForDecl());
              const bool exact_reference_identity =
                  semantic_declaration != nullptr &&
                  written_referenced_declaration != nullptr &&
                  !semantic_parameter_type.isNull() &&
                  semantic_parameter_type->isReferenceType() &&
                  written_expression->isLValue() &&
                  semantic_declaration->getCanonicalDecl() ==
                      written_referenced_declaration->getCanonicalDecl();
              clang::Expr::EvalResult evaluation;
              const bool evaluated = written_expression != nullptr &&
                                     written_expression->EvaluateAsRValue(
                                         evaluation, var_decl->getASTContext());
              if (evaluated) {
                markClangLocalObjectDefined(&evaluation.Val);
              }
              const clang::ValueDecl *evaluated_declaration = nullptr;
              if (evaluated && evaluation.Val.isLValue() &&
                  !evaluation.Val.isNullPointer()) {
                clang::APValue::LValueBase base =
                    evaluation.Val.getLValueBase();
                evaluated_declaration =
                    base.dyn_cast<const clang::ValueDecl *>();
                if (evaluated_declaration != nullptr) {
                  markClangDeclObjectDefinedByKind(
                      const_cast<clang::ValueDecl *>(evaluated_declaration));
                }
              }
              const bool exact_declaration_designator =
                  evaluated_declaration != nullptr &&
                  ((!evaluation.Val.hasLValuePath() ||
                    evaluation.Val.getLValuePath().empty()) ||
                   (evaluated_declaration->getType()->isArrayType() &&
                    evaluation.Val.getLValuePath().size() == 1 &&
                    evaluation.Val.getLValuePath().front().getAsArrayIndex() ==
                        0));
              const bool exact_evaluated_identity =
                  semantic_declaration != nullptr &&
                  evaluated_declaration != nullptr &&
                  semantic_declaration->getCanonicalDecl() ==
                      evaluated_declaration->getCanonicalDecl() &&
                  evaluation.Val.getLValueOffset().isZero() &&
                  !evaluation.Val.isLValueOnePastTheEnd() &&
                  exact_declaration_designator;
              exact_clang_identity =
                  exact_reference_identity || exact_evaluated_identity;
            }
            bool exact_sage_shape =
                written_argument != nullptr && semantic_argument != nullptr &&
                written_argument->get_argumentType() ==
                    semantic_argument->get_argumentType() &&
                written_argument->get_is_pack_element() ==
                    semantic_argument->get_is_pack_element();
            if (exact_sage_shape && written_argument->get_argumentType() ==
                                        SgTemplateArgument::nontype_argument) {
              const bool written_has_expression =
                  written_argument->get_expression() != nullptr;
              const bool written_has_name =
                  written_argument->get_initializedName() != nullptr;
              const bool semantic_has_expression =
                  semantic_argument->get_expression() != nullptr;
              const bool semantic_has_name =
                  semantic_argument->get_initializedName() != nullptr;
              exact_sage_shape =
                  written_has_expression != written_has_name &&
                  semantic_has_expression != semantic_has_name &&
                  written_has_expression == semantic_has_expression &&
                  written_argument->get_type() == semantic_argument->get_type();
              if (exact_sage_shape && written_has_name) {
                exact_sage_shape = SageInterface::templateArgumentEquivalence(
                    written_argument, semantic_argument);
              }
            } else if (exact_sage_shape) {
              exact_sage_shape = SageInterface::templateArgumentEquivalence(
                  written_argument, semantic_argument);
            }
            if (!exact_clang_identity || !exact_sage_shape) {
              fprintf(
                  stderr,
                  "REX_FRONTEND_INVARIANT[variable-template-type-"
                  "surface]: variable=%s written argument=%zu has no "
                  "exact semantic counterpart on instantiation=%p/%s "
                  "written=%p/%s type=%p/%s source-type=%p/%s "
                  "semantic=%p/%s type=%p/%s source-type=%p/%s "
                  "clang-kinds=%d/%d clang-identity=%d sage-shape=%d\n",
                  var_decl->getQualifiedNameAsString().c_str(), index,
                  static_cast<void *>(semantic_instantiation),
                  semantic_instantiation->get_name().getString().c_str(),
                  static_cast<void *>(written_argument),
                  written_argument != nullptr
                      ? written_argument->class_name().c_str()
                      : "<null>",
                  static_cast<void *>(written_argument != nullptr
                                          ? written_argument->get_type()
                                          : nullptr),
                  written_argument != nullptr &&
                          written_argument->get_type() != nullptr
                      ? written_argument->get_type()->class_name().c_str()
                      : "<null>",
                  static_cast<void *>(
                      written_argument != nullptr
                          ? written_argument->get_sourceSpelledType()
                          : nullptr),
                  written_argument != nullptr &&
                          written_argument->get_sourceSpelledType() != nullptr
                      ? written_argument->get_sourceSpelledType()
                            ->class_name()
                            .c_str()
                      : "<null>",
                  static_cast<void *>(semantic_argument),
                  semantic_argument != nullptr
                      ? semantic_argument->class_name().c_str()
                      : "<null>",
                  static_cast<void *>(semantic_argument != nullptr
                                          ? semantic_argument->get_type()
                                          : nullptr),
                  semantic_argument != nullptr &&
                          semantic_argument->get_type() != nullptr
                      ? semantic_argument->get_type()->class_name().c_str()
                      : "<null>",
                  static_cast<void *>(
                      semantic_argument != nullptr
                          ? semantic_argument->get_sourceSpelledType()
                          : nullptr),
                  semantic_argument != nullptr &&
                          semantic_argument->get_sourceSpelledType() != nullptr
                      ? semantic_argument->get_sourceSpelledType()
                            ->class_name()
                            .c_str()
                      : "<null>",
                  static_cast<int>(clang_written_argument.getKind()),
                  static_cast<int>(clang_semantic_argument.getKind()),
                  exact_clang_identity ? 1 : 0, exact_sage_shape ? 1 : 0);
              ROSE_ABORT();
            }

            if (written_argument->get_argumentType() ==
                    SgTemplateArgument::type_argument &&
                written_argument->get_sourceSpelledType() == nullptr) {
              fprintf(stderr,
                      "REX_FRONTEND_INVARIANT[variable-template-type-"
                      "surface]: variable=%s type argument=%zu has no exact "
                      "source-spelled type\n",
                      var_decl->getQualifiedNameAsString().c_str(), index);
              ROSE_ABORT();
            }
          }
          // The initialized name retains canonical type identity for semantic
          // consumers.  Its independent TypeLoc graph owns all written
          // template arguments and qualification state for this use site.
          cxx_source_type = type;
          type = sg_varType;
        }
      }
    }
  }
  if (type == nullptr) {
    if (written_variable_type_contains_auto) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[auto-type-source]: variable=%s has a "
              "written placeholder type but no exact TypeLoc translation\n",
              var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }
    type = buildTypeFromQualifiedType(markClangQualTypeDefined(
        readClangApiValueDefined([&]() { return var_decl->getType(); })));
  }
  if (variable_owns_lexical_source_surface && var_is_constexpr &&
      !var_decl->isImplicit() && original_var_type.isLocalConstQualified() &&
      !saw_written_var_type_loc) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[constexpr-source-type]: source variable=%s "
            "has no written type location\n",
            var_decl->getNameAsString().c_str());
    ROSE_ABORT();
  }
  if (constexpr_top_level_const_is_implicit) {
    type = removeImplicitConstexprTopLevelConst(type, var_decl);
  }
  // Resolve a source-spelled inline tag definition before constructing its
  // declarator.  VisitRecordDecl/VisitEnumDecl deliberately leave the exact
  // defining surface detached; the strict variable builder adopts that surface
  // in the same construction transaction.  Publishing it temporarily and
  // moving it under the variable after the fact creates two contradictory
  // physical owners and hides a malformed producer.
  SgDeclarationStatement *embedded_variable_definition = nullptr;
  if (isembedded && isDefinitionRequired) {
    if (embeddedRecordDecl != nullptr) {
      SgClassDeclaration *class_definition =
          lookup_embedded_record_decl(embeddedRecordDecl);
      if (semantic_declarator_owned_tag_definition) {
        SgScopeStatement *semantic_scope = exact_inline_tag_semantic_scope();
        SgAuxiliaryDeclarationList *container =
            class_definition != nullptr
                ? isSgAuxiliaryDeclarationList(class_definition->get_parent())
                : nullptr;
        SgClassDeclaration *first_nondefining =
            class_definition != nullptr
                ? isSgClassDeclaration(
                      class_definition->get_firstNondefiningDeclaration())
                : nullptr;
        if (class_definition == nullptr ||
            materialized_inline_tag_definition != nullptr ||
            class_definition->get_definingDeclaration() != class_definition ||
            class_definition->get_definition() == nullptr ||
            class_definition->get_scope() != semantic_scope ||
            container == nullptr || container->get_parent() != semantic_scope ||
            semantic_scope->get_auxiliary_declarations() != container ||
            std::count(container->get_declarations().begin(),
                       container->get_declarations().end(),
                       class_definition) != 1 ||
            first_nondefining == nullptr ||
            first_nondefining->get_scope() != semantic_scope ||
            first_nondefining->get_definingDeclaration() != class_definition ||
            first_nondefining->get_firstNondefiningDeclaration() !=
                first_nondefining ||
            (first_nondefining != class_definition &&
             (first_nondefining->get_parent() != container ||
              std::count(container->get_declarations().begin(),
                         container->get_declarations().end(),
                         first_nondefining) != 1)) ||
            class_definition->get_definition()
                    ->get_construction_physical_output_owner() != nullptr ||
            declaration_has_real_source(class_definition)) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[semantic-declarator-class-"
                  "producer]: variable=%s did not receive one exact "
                  "semantic auxiliary defining class transaction\n",
                  name.getString().c_str());
          ROSE_ABORT();
        }
        validate_semantic_provenance(
            class_definition, true,
            "VisitVarDecl:semantic-declarator-class-definition");
        validate_semantic_provenance(
            class_definition->get_definition(), true,
            "VisitVarDecl:semantic-declarator-class-body");
        detach_embedded_tag_for_declarator_owner(
            p_decl_attachment_session, class_definition,
            "VisitVarDecl:semantic-declarator-class");
      } else if (class_definition == nullptr ||
                 class_definition != materialized_inline_tag_definition ||
                 class_definition->get_definingDeclaration() !=
                     class_definition ||
                 class_definition->get_parent() != nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[embedded-variable-class-producer]: "
                "variable=%s did not receive one detached exact defining "
                "class surface\n",
                name.getString().c_str());
        ROSE_ABORT();
      }
      markClassDeclarationChainNonAutonomous(class_definition);
      embedded_variable_definition = class_definition;
    } else if (embeddedEnumDecl != nullptr) {
      SgEnumDeclaration *enum_definition =
          lookup_embedded_enum_decl(embeddedEnumDecl);
      if (semantic_declarator_owned_tag_definition) {
        SgScopeStatement *semantic_scope = exact_inline_tag_semantic_scope();
        SgAuxiliaryDeclarationList *container =
            enum_definition != nullptr
                ? isSgAuxiliaryDeclarationList(enum_definition->get_parent())
                : nullptr;
        SgEnumDeclaration *first_nondefining =
            enum_definition != nullptr
                ? isSgEnumDeclaration(
                      enum_definition->get_firstNondefiningDeclaration())
                : nullptr;
        if (enum_definition == nullptr ||
            materialized_inline_tag_definition != nullptr ||
            enum_definition->get_definingDeclaration() != enum_definition ||
            enum_definition->get_scope() != semantic_scope ||
            container == nullptr || container->get_parent() != semantic_scope ||
            semantic_scope->get_auxiliary_declarations() != container ||
            std::count(container->get_declarations().begin(),
                       container->get_declarations().end(),
                       enum_definition) != 1 ||
            first_nondefining == nullptr ||
            first_nondefining->get_scope() != semantic_scope ||
            first_nondefining->get_definingDeclaration() != enum_definition ||
            first_nondefining->get_firstNondefiningDeclaration() !=
                first_nondefining ||
            (first_nondefining != enum_definition &&
             (first_nondefining->get_parent() != container ||
              std::count(container->get_declarations().begin(),
                         container->get_declarations().end(),
                         first_nondefining) != 1)) ||
            declaration_has_real_source(enum_definition)) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[semantic-declarator-enum-producer]: "
                  "variable=%s did not receive one exact semantic auxiliary "
                  "defining enum transaction\n",
                  name.getString().c_str());
          ROSE_ABORT();
        }
        validate_semantic_provenance(
            enum_definition, true,
            "VisitVarDecl:semantic-declarator-enum-definition");
        detach_embedded_tag_for_declarator_owner(
            p_decl_attachment_session, enum_definition,
            "VisitVarDecl:semantic-declarator-enum");
      } else if (enum_definition == nullptr ||
                 enum_definition != materialized_inline_tag_definition ||
                 enum_definition->get_definingDeclaration() !=
                     enum_definition ||
                 enum_definition->get_parent() != nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[embedded-variable-enum-producer]: "
                "variable=%s did not receive one detached exact defining "
                "enum surface\n",
                name.getString().c_str());
        ROSE_ABORT();
      }
      markEnumDeclarationChainNonAutonomous(enum_definition);
      embedded_variable_definition = enum_definition;
    } else {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[embedded-variable-producer]: variable=%s "
              "requires an inline tag definition but has no exact Clang tag\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
  }

  if (var_type_decl_context != nullptr) {
    ROSE_ASSERT(!p_template_parameter_decl_context_stack.empty());
    p_template_parameter_decl_context_stack.pop_back();
    ROSE_ASSERT(p_preserve_current_class_qualifier_depth > 0);
    --p_preserve_current_class_qualifier_depth;
  }

  SgDeclarationStatement *declarator_owned_nondefining_tag = nullptr;
  if (p_compiler_instance != nullptr) {
    auto prepare_declarator_owned_variable_tag_decl =
        [&](clang::TagDecl *tag_decl) {
          if (tag_decl == nullptr || tag_decl->getPreviousDecl() != nullptr) {
            return;
          }
          if (tag_decl->isThisDeclarationADefinition()) {
            return;
          }

          clang::SourceManager &sm = p_compiler_instance->getSourceManager();
          clang::SourceRange owner_range =
              clangVarDeclSourceRangeDefined(var_decl);
          clang::SourceLocation tag_loc =
              sm.getSpellingLoc(tag_decl->getBeginLoc());
          clang::SourceLocation range_begin =
              sm.getSpellingLoc(owner_range.getBegin());
          clang::SourceLocation range_end =
              sm.getSpellingLoc(owner_range.getEnd());
          if (!tag_loc.isValid() || !range_begin.isValid() ||
              !range_end.isValid() ||
              sm.getFileID(tag_loc) != sm.getFileID(range_begin) ||
              sm.getFileID(tag_loc) != sm.getFileID(range_end)) {
            return;
          }
          if (sm.isBeforeInTranslationUnit(tag_loc, range_begin) ||
              sm.isBeforeInTranslationUnit(range_end, tag_loc)) {
            return;
          }

          SgDeclarationStatement *decl_stmt = lookupSgDeclarationForClangDecl(
              tag_decl, /*allow_on_demand=*/true);
          if (decl_stmt == nullptr) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[declarator-owned-tag-producer]: "
                    "variable=%s written tag=%p/%s has no translated "
                    "declaration\n",
                    name.getString().c_str(), static_cast<void *>(tag_decl),
                    tag_decl->getNameAsString().c_str());
            ROSE_ABORT();
          }

          SgClassDeclaration *class_decl = isSgClassDeclaration(decl_stmt);
          SgEnumDeclaration *enum_decl = isSgEnumDeclaration(decl_stmt);
          const bool exact_class_introduction =
              class_decl != nullptr && class_decl->get_definition() == nullptr;
          const bool exact_enum_introduction =
              enum_decl != nullptr && enum_decl->isForward();
          if (decl_stmt == embedded_variable_definition ||
              decl_stmt->get_firstNondefiningDeclaration() != decl_stmt ||
              decl_stmt->get_definingDeclaration() == decl_stmt ||
              (!exact_class_introduction && !exact_enum_introduction) ||
              declarator_owned_nondefining_tag != nullptr) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[declarator-owned-tag-producer]: "
                    "variable=%s written tag=%p/%s translated to %p/%s without "
                    "one exact nondefining ownership surface\n",
                    name.getString().c_str(), static_cast<void *>(tag_decl),
                    tag_decl->getNameAsString().c_str(),
                    static_cast<void *>(decl_stmt),
                    decl_stmt->class_name().c_str());
            ROSE_ABORT();
          }

          if (class_decl != nullptr) {
            class_decl->set_isAutonomousDeclaration(false);
          } else {
            enum_decl->set_isAutonomousDeclaration(false);
          }
          detach_decl_from_known_scope_child_lists(p_decl_attachment_session,
                                                   decl_stmt);
          if (decl_stmt->get_parent() != nullptr) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[declarator-owned-tag-producer]: "
                    "variable=%s declaration=%p/%s did not detach from its "
                    "temporary owner\n",
                    name.getString().c_str(), static_cast<void *>(decl_stmt),
                    decl_stmt->class_name().c_str());
            ROSE_ABORT();
          }
          declarator_owned_nondefining_tag = decl_stmt;
        };

    if (owns_source_declaration_specifier) {
      prepare_declarator_owned_variable_tag_decl(written_variable_tag_decl);
    }
  }

  bool implicit_anonymous_aggregate_var = false;
  if (var_decl->isImplicit() && name.getString().empty()) {
    const clang::RecordType *record_type =
        llvm::dyn_cast_or_null<clang::RecordType>(varType);
    const clang::RecordDecl *record_decl_for_var =
        record_type != nullptr ? record_type->getDecl() : nullptr;
    implicit_anonymous_aggregate_var =
        record_decl_for_var != nullptr &&
        record_decl_for_var->isAnonymousStructOrUnion();
  }
  if (implicit_anonymous_aggregate_var) {
    SgType *base_type = type != nullptr ? type->findBaseType() : nullptr;
    if (SgClassType *class_type = isSgClassType(base_type)) {
      auto mark_unnamed = [](SgClassDeclaration *decl) {
        if (decl != nullptr) {
          // Keep the synthesized internal name so symbol-table lookups for the
          // anonymous aggregate remain stable; isUnNamed controls user-visible
          // anonymity.
          decl->set_isUnNamed(true);
        }
      };
      if (SgClassDeclaration *decl =
              isSgClassDeclaration(class_type->get_declaration())) {
        mark_unnamed(decl);
        mark_unnamed(
            isSgClassDeclaration(decl->get_firstNondefiningDeclaration()));
        mark_unnamed(isSgClassDeclaration(decl->get_definingDeclaration()));
      }
    }
  }

  const clang::TemplateSpecializationKind var_specialization_kind =
      readClangApiValueDefined(
          [&]() { return var_decl->getTemplateSpecializationKind(); });
  const bool instantiated_static_member_pattern =
      is_instantiated_static_data_member_from_template_pattern(var_decl);

  SgDeclarationGroupStatement *source_group_owner =
      activeExactSourceDeclarationGroupOwner(var_decl);
  const bool semantic_declaration_group =
      source_group_owner != nullptr &&
      activeExactDeclarationGroupIsSemantic(var_decl);
  clang::RecordDecl *static_member_record_context =
      isStaticDataMember ? defined_var_record_context() : nullptr;
  const bool exact_typed_owner_static_member_source =
      static_member_record_context != nullptr && !var_decl->isImplicit() &&
      defined_var_lexical_context() == static_member_record_context &&
      activeTypedOwnerTagConstructionScope(static_member_record_context) !=
          nullptr;
  if (exact_typed_owner_static_member_source &&
      instantiated_static_member_pattern) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[typed-owner-static-member-source]: "
            "source member=%s in active declarator-owned record=%s was "
            "misclassified as a template-instantiation pattern\n",
            var_decl->getQualifiedNameAsString().c_str(),
            static_member_record_context->getQualifiedNameAsString().c_str());
    ROSE_ABORT();
  }
  const bool semantic_static_member_instantiation =
      instantiated_static_member_pattern && source_group_owner == nullptr;
  if (instantiated_static_member_pattern && source_group_owner != nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[semantic-static-member-owner]: implicit "
            "static-member instantiation=%s was admitted to a lexical source "
            "declaration group\n",
            var_decl->getQualifiedNameAsString().c_str());
    ROSE_ABORT();
  }
  SgScopeStatement *pending_for_init_scope = nullptr;
  auto require_exact_pending_typed_declaration_scope =
      [&](SgScopeStatement *candidate_scope) -> bool {
    if (SgScopeStatement *condition_scope =
            activePendingConditionDeclarationScopeFor(var_decl)) {
      const bool exact_pending_slot =
          (isSgIfStmt(condition_scope) != nullptr &&
           isSgIfStmt(condition_scope)->get_conditional() == nullptr) ||
          (isSgForStatement(condition_scope) != nullptr &&
           isSgForStatement(condition_scope)->get_test() == nullptr) ||
          (isSgWhileStmt(condition_scope) != nullptr &&
           isSgWhileStmt(condition_scope)->get_condition() == nullptr) ||
          (isSgSwitchStatement(condition_scope) != nullptr &&
           isSgSwitchStatement(condition_scope)->get_item_selector() ==
               nullptr);
      if (candidate_scope != condition_scope || !exact_pending_slot) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[condition-declaration-transaction]: "
                "variable=%s candidate-scope=%p expected=%p/%s does not "
                "belong to one empty typed condition slot\n",
                name.getString().c_str(), static_cast<void *>(candidate_scope),
                static_cast<void *>(condition_scope),
                condition_scope != nullptr
                    ? condition_scope->class_name().c_str()
                    : "<null>");
        ROSE_ABORT();
      }
      return true;
    }

    if (p_in_for_init_translation) {
      if (SgForStatement *for_scope = isSgForStatement(candidate_scope)) {
        SgForInitStatement *for_init = for_scope->get_for_init_stmt();
        if (for_scope->get_loop_body() != nullptr || for_init == nullptr ||
            for_init->get_parent() != for_scope ||
            !for_init->get_init_stmt().empty()) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[for-init-declaration-transaction]: "
                  "variable=%s does not belong to one empty typed for-init "
                  "construction\n",
                  name.getString().c_str());
          ROSE_ABORT();
        }
        return true;
      }

      if (SgRangeBasedForStatement *range_scope =
              isSgRangeBasedForStatement(candidate_scope)) {
        if (range_scope->get_iterator_declaration() != nullptr ||
            range_scope->get_range_declaration() != nullptr ||
            range_scope->get_begin_declaration() != nullptr ||
            range_scope->get_end_declaration() != nullptr ||
            range_scope->get_not_equal_expression() != nullptr ||
            range_scope->get_increment_expression() != nullptr ||
            range_scope->get_loop_body() != nullptr) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[range-for-declaration-transaction]: "
                  "variable=%s does not belong to one empty typed range-for "
                  "construction\n",
                  name.getString().c_str());
          ROSE_ABORT();
        }
        return true;
      }
    }

    if (readClangApiValueDefined(
            [&]() { return var_decl->isExceptionVariable(); })) {
      if (SgCatchOptionStmt *catch_scope =
              isSgCatchOptionStmt(candidate_scope)) {
        if (catch_scope->get_condition() != nullptr) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[catch-condition-transaction]: "
                  "exception variable=%s was translated after the typed "
                  "catch condition was already published\n",
                  name.getString().c_str());
          ROSE_ABORT();
        }
        return true;
      }
    }

    const DeclStatementConstruction *direct_statement_construction =
        activeDeclStatementConstructionFor(var_decl);
    if (direct_statement_construction != nullptr &&
        direct_statement_construction->typed_child_owner != nullptr) {
      if (direct_statement_construction->lexical_scope == nullptr ||
          candidate_scope != direct_statement_construction->lexical_scope) {
        fprintf(
            stderr,
            "REX_FRONTEND_INVARIANT[direct-declaration-body-transaction]: "
            "variable=%s candidate-scope=%p does not match its exact "
            "DeclStmt scope=%p\n",
            name.getString().c_str(), static_cast<void *>(candidate_scope),
            static_cast<void *>(direct_statement_construction->lexical_scope));
        ROSE_ABORT();
      }
      // The active statement producer has published the concrete typed owner
      // before this DeclStmt began. Keep the declaration detached until that
      // producer acquires its sole child edge.
      return true;
    }

    return false;
  };
  auto build_var_declaration = [&](SgScopeStatement *decl_scope,
                                   SgScopeStatement *lexical_scope,
                                   SgInitializedName *previous_declaration =
                                       nullptr) -> SgVariableDeclaration * {
    ROSE_ASSERT(decl_scope != nullptr);
    SgScopeStatement *symbol_scope = normalizeNamespaceScope(decl_scope);
    ROSE_ASSERT(symbol_scope != nullptr);
    if (lexical_scope == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-lexical-owner]: variable=%s "
              "has no active lexical scope during construction\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    // Clang already gives every VarDecl an exact canonical/redeclaration
    // identity.  SageBuilder's legacy name lookup crosses all SgGlobal nodes
    // in a project and therefore merges unrelated entities from separate
    // translation units (including internal-linkage variables).  Construct a
    // fresh lexical declaration and publish its local symbol here; exact Clang
    // redeclaration links are installed below from getPreviousDecl().
    if (embedded_variable_definition != nullptr &&
        previous_declaration != nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[embedded-variable-redeclaration]: "
              "variable=%s cannot redeclare an entity while owning a fresh "
              "inline tag definition\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    SgVariableDeclaration *declaration =
        embedded_variable_definition != nullptr
            ? SageBuilder::
                  buildUnpublishedVariableDeclarationWithEmbeddedTag_nfi(
                      name, type, nullptr, symbol_scope,
                      embedded_variable_definition)
            : new SgVariableDeclaration(name, type, nullptr);
    ROSE_ASSERT(declaration != nullptr);
    ROSE_ASSERT(declaration->get_variables().size() == 1);
    SgInitializedName *initialized_name = declaration->get_variables().front();
    ROSE_ASSERT(initialized_name != nullptr);

    initialized_name->set_scope(symbol_scope);
    initialized_name->set_parent(declaration);
    if (source_group_owner != nullptr) {
      if (source_group_owner->get_scope() != lexical_scope) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-source-group-owner]: "
                "variable=%s group scope differs from its lexical scope\n",
                name.getString().c_str());
        ROSE_ABORT();
      }
      source_group_owner->append_declaration(declaration);
      if (!activeExactSourceDeclarationGroupOwnsPublishedMember(var_decl,
                                                                declaration)) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-source-group-owner]: "
                "variable=%s was not published by its exact active "
                "declaration group\n",
                name.getString().c_str());
        ROSE_ABORT();
      }
    }
    declaration->set_firstNondefiningDeclaration(declaration);
    if (previous_declaration != nullptr) {
      if (previous_declaration->get_name() != initialized_name->get_name() ||
          !scopeMatchesForDeclarationReuse(previous_declaration->get_scope(),
                                           symbol_scope)) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-redeclaration]: "
                "variable=%s previous declaration has a different semantic "
                "owner\n",
                initialized_name->get_name().str());
        ROSE_ABORT();
      }
      initialized_name->set_prev_decl_item(previous_declaration);
    }
    SageInterface::setOneSourcePositionNull(declaration);
    SageInterface::setOneSourcePositionNull(initialized_name);
    if (SgVariableDefinition *definition = declaration->get_definition()) {
      SageInterface::setOneSourcePositionNull(definition);
    }
    const bool clang_declaration_is_named =
        var_decl->getIdentifier() != nullptr;
    if (clang_declaration_is_named != !initialized_name->get_name().is_null()) {
      std::cerr << "REX_FRONTEND_INVARIANT[variable-declaration-name]: Clang "
                   "and Sage disagree about whether the declaration is named"
                << std::endl;
      ROSE_ABORT();
    }
    // A DecompositionDecl is the unnamed storage owner for a structured
    // binding.  Only its named BindingDecl children participate in lookup, so
    // publishing a symbol for this shell creates an impossible empty-name
    // variable entity before those bindings are translated.
    if (clang_declaration_is_named && !var_is_init_capture) {
      registerDeclarationSymbol(declaration);
    }
    const bool pending_for_init_owner =
        source_group_owner == nullptr &&
        require_exact_pending_typed_declaration_scope(lexical_scope);
    const bool init_capture_auxiliary_owner =
        source_group_owner == nullptr && var_is_init_capture;
    const bool static_instantiation_auxiliary_owner =
        semantic_static_member_instantiation;
    if (static_instantiation_auxiliary_owner &&
        (source_group_owner != nullptr || pending_for_init_owner ||
         init_capture_auxiliary_owner || decl_scope != lexical_scope ||
         !is_class_like_scope(decl_scope))) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[semantic-static-member-owner]: "
              "instantiation=%s has conflicting lexical or typed construction "
              "ownership\n",
              var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }
    if (pending_for_init_owner && init_capture_auxiliary_owner) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[lambda-capture-owner]: init-capture "
              "'%s' cannot also be a pending for-init declaration\n",
              initialized_name->get_name().str());
      ROSE_ABORT();
    }
    if (pending_for_init_owner) {
      if (declaration->get_parent() != nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[typed-declaration-transaction]: "
                "variable=%s is not detached before its typed statement "
                "owner acquires it\n",
                initialized_name->get_name().str());
        ROSE_ABORT();
      }
      if (pending_for_init_scope != nullptr &&
          pending_for_init_scope != lexical_scope) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[typed-declaration-transaction]: "
                "variable=%s was assigned two pending typed statement "
                "owners\n",
                initialized_name->get_name().str());
        ROSE_ABORT();
      }
      pending_for_init_scope = lexical_scope;
    } else if (source_group_owner == nullptr) {
      if (init_capture_auxiliary_owner ||
          static_instantiation_auxiliary_owner) {
        if (decl_scope != lexical_scope || symbol_scope != lexical_scope ||
            declaration->get_parent() != nullptr) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[variable-auxiliary-owner]: "
                  "variable='%s' has inconsistent semantic, symbol, or "
                  "structural construction ownership\n",
                  initialized_name->get_name().str());
          ROSE_ABORT();
        }
        SageBuilder::attachAuxiliaryDeclaration(lexical_scope, declaration);
      } else {
        // Ordered declaration insertion may inspect every declaration already
        // published in the lexical scope.  Initializer translation can
        // materialize another declaration before this VarDecl reaches the
        // generic VisitDecl provenance boundary, so publishing a source
        // variable with null file information exposes a half-constructed
        // declaration to that insertion.  The Clang VarDecl already owns the
        // complete lexical range at this point; publish that immutable
        // provenance before the structural child edge.  Symbol publication
        // remains independent and already occurred above, preserving the
        // language rule that a variable is visible in its own initializer.
        if (variable_owns_lexical_source_surface) {
          clang::SourceRange variable_source_range = preferredDeclSourceRange(
              var_decl, declaration, &p_compiler_instance->getSourceManager());
          if (!variable_source_range.isValid()) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[variable-source-publication]: "
                    "source variable=%s has no exact lexical range before "
                    "structural publication\n",
                    var_decl->getQualifiedNameAsString().c_str());
            ROSE_ABORT();
          }
          const bool range_ends_in_macro =
              variable_source_range.getEnd().isMacroID();
          if (!var_decl->isFromASTFile() &&
              decl_range_should_consume_trailing_semicolon(
                  var_decl, p_compiler_instance->getASTContext()) &&
              !range_ends_in_macro) {
            variable_source_range = extendDeclSourceRangeWithTrailingSemicolon(
                variable_source_range, p_compiler_instance->getSourceManager(),
                p_compiler_instance->getLangOpts(),
                p_compiler_instance->getPreprocessor(), var_decl);
          }
          applySourceRange(declaration, variable_source_range);
          if (!declaration->get_translation_unit_source_order().has_value()) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[variable-source-publication]: "
                    "source variable=%s did not acquire immutable "
                    "translation-unit order before structural publication\n",
                    var_decl->getQualifiedNameAsString().c_str());
            ROSE_ABORT();
          }
        }
        publish_fresh_decl_in_scope_child_list(p_decl_attachment_session,
                                               declaration, lexical_scope,
                                               "VisitVarDecl:construction");
      }
    }
    if (clang_declaration_is_named) {
      // Publish or validate the one symbol owned by the exact variable
      // redeclaration family.  Builders publish the first declaration, while a
      // later redeclaration intentionally has no declaration-specific symbol;
      // registerDeclarationSymbol validates and reuses the family symbol in
      // that case.  Init captures additionally require their typed auxiliary
      // owner to be visible before this boundary, which was established above.
      registerDeclarationSymbol(declaration);
    }
    SgSymbol *declaration_symbol = nullptr;
    std::set<SgInitializedName *> exact_redeclaration_family;
    for (SgInitializedName *candidate = initialized_name; candidate != nullptr;
         candidate = candidate->get_prev_decl_item()) {
      if (!exact_redeclaration_family.insert(candidate).second ||
          !scopeMatchesForDeclarationReuse(candidate->get_scope(),
                                           symbol_scope) ||
          candidate->get_name() != initialized_name->get_name()) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-redeclaration]: "
                "variable=%s has a cyclic or scope-inconsistent exact "
                "redeclaration family\n",
                initialized_name->get_name().str());
        ROSE_ABORT();
      }
      SgSymbol *candidate_symbol =
          symbol_scope->find_symbol_from_declaration(candidate);
      if (candidate_symbol != nullptr) {
        if (declaration_symbol != nullptr &&
            declaration_symbol != candidate_symbol) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[variable-declaration-symbol]: "
                  "variable=%s has conflicting exact family symbols\n",
                  initialized_name->get_name().str());
          ROSE_ABORT();
        }
        declaration_symbol = candidate_symbol;
      }
    }
    if (clang_declaration_is_named && declaration_symbol == nullptr) {
      std::cerr << "REX_FRONTEND_INVARIANT[variable-declaration-symbol]: "
                   "SageBuilder did not register variable '"
                << initialized_name->get_name()
                << "' in its requested semantic scope" << std::endl;
      ROSE_ABORT();
    }
    if (!clang_declaration_is_named && declaration_symbol != nullptr) {
      std::cerr << "REX_FRONTEND_INVARIANT[variable-declaration-symbol]: "
                   "unnamed variable declaration unexpectedly owns a symbol"
                << std::endl;
      ROSE_ABORT();
    }
    // SgVariableDeclaration has a structural scope derived from its parent;
    // each SgInitializedName stores the possibly-distinct semantic symbol
    // scope.  Conflating those owners corrupts declarations translated on
    // demand (for example, a file variable first referenced from a function)
    // and out-of-line static data-member definitions.
    SgNode *expected_parent =
        source_group_owner != nullptr
            ? static_cast<SgNode *>(source_group_owner)
        : pending_for_init_owner ? nullptr
        : init_capture_auxiliary_owner || static_instantiation_auxiliary_owner
            ? static_cast<SgNode *>(lexical_scope->get_auxiliary_declarations())
            : static_cast<SgNode *>(lexical_scope);
    SgAuxiliaryDeclarationList *init_capture_container =
        init_capture_auxiliary_owner || static_instantiation_auxiliary_owner
            ? isSgAuxiliaryDeclarationList(declaration->get_parent())
            : nullptr;
    const bool exact_init_capture_auxiliary_owner =
        (!init_capture_auxiliary_owner &&
         !static_instantiation_auxiliary_owner) ||
        (init_capture_container != nullptr &&
         init_capture_container->get_parent() == lexical_scope &&
         lexical_scope->get_auxiliary_declarations() ==
             init_capture_container &&
         std::count(init_capture_container->get_declarations().begin(),
                    init_capture_container->get_declarations().end(),
                    declaration) == 1 &&
         !lexical_scope->statementExistsInScope(declaration));
    if (declaration->get_parent() != expected_parent ||
        (!pending_for_init_owner &&
         declaration->get_scope() != lexical_scope) ||
        initialized_name->get_scope() != symbol_scope ||
        !exact_init_capture_auxiliary_owner) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-construction-owner]: "
              "variable=%s did not preserve its exact lexical declaration "
              "owner and semantic symbol owner\n",
              initialized_name->get_name().str());
      ROSE_ABORT();
    }
    return declaration;
  };
  auto resolve_static_member_scope = [&]() -> SgScopeStatement * {
    if (!isStaticDataMember) {
      return nullptr;
    }
    clang::RecordDecl *record_ctx = defined_var_record_context();
    if (record_ctx == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[semantic-static-member-owner]: "
              "variable=%s has no Clang record declaration context\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    SgScopeStatement *resolved_scope = resolveScopeFromDeclContext(record_ctx);
    SgClassDefinition *class_def = isSgClassDefinition(resolved_scope);
    if (class_def == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[semantic-static-member-owner]: "
              "variable=%s record context resolved to %s instead of an "
              "exact class definition\n",
              name.getString().c_str(), resolved_scope->class_name().c_str());
      ROSE_ABORT();
    }
    return class_def;
  };
  SgScopeStatement *static_member_owner_scope = resolve_static_member_scope();
  auto resolve_exact_variable_lexical_scope = [&]() -> SgScopeStatement * {
    SgScopeStatement *active_scope = SageBuilder::topScopeStack();
    if (active_scope == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-lexical-owner]: variable=%s "
              "has no active lexical scope\n",
              name.getString().c_str());
      ROSE_ABORT();
    }

    // Compound statements are not Clang DeclContexts, so local variables must
    // retain the active statement scope.  File variables and static data
    // members do have an exact lexical DeclContext; resolving it is mandatory
    // because on-demand translation can run while an unrelated local scope is
    // active.
    if (!var_is_file_var_decl && !isStaticDataMember) {
      return active_scope;
    }
    return resolveScopeFromDeclContext(defined_var_lexical_context());
  };

  //    SgVariableDeclaration * sg_var_decl = new SgVariableDeclaration(name,
  //    type, init); // scope: obtain from the scope stack.
  // Pei-Hung (09/01/2022) In test2022_3.c, the variable symbol needs to be
  // avaiable before processing the RHS. calling buildVariableDeclaration_nfi to
  // get the symbol in place.
  SgVariableDeclaration *sg_var_decl = nullptr;
  // Preserve Clang's exact redeclaration identity; no spelling lookup is
  // permitted when linking a static data-member definition to its declaration.
  clang::VarDecl *previous_variable_decl =
      llvm::dyn_cast_or_null<clang::VarDecl>(
          markClangDeclObjectDefinedByKind(readClangApiValueDefined(
              [&]() { return var_decl->getPreviousDecl(); })));
  SgInitializedName *exact_previous_init = nullptr;
  if (previous_variable_decl != nullptr) {
    clang::VarDecl *prevDecl = previous_variable_decl;
    auto it_prev = p_decl_translation_map.find(prevDecl);
    if (it_prev != p_decl_translation_map.end()) {
      exact_previous_init =
          exactInitializedNameFromTranslatedVariableNode(it_prev->second);
    }
    if (exact_previous_init == nullptr) {
      // Clang can visit an out-of-line static data-member definition before
      // ROSE has populated the member subtree of its class-template pattern.
      // The predecessor pointer is the authoritative declaration-order edge;
      // materialize that exact producer now instead of guessing by name or
      // attaching the definition to a same-spelled symbol.
      if (p_decl_translation_in_progress.count(prevDecl) != 0 ||
          p_decl_translation_on_demand.count(prevDecl) != 0) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-redeclaration-order]: "
                "variable=%s predecessor=%p is unpublished while its exact "
                "translation is already in progress\n",
                name.getString().c_str(), static_cast<void *>(prevDecl));
        ROSE_ABORT();
      }
      SgNode *translated_previous = TraverseOnDemand(prevDecl);
      auto published_previous = p_decl_translation_map.find(prevDecl);
      if (published_previous != p_decl_translation_map.end()) {
        exact_previous_init = exactInitializedNameFromTranslatedVariableNode(
            published_previous->second);
      }
      if (exact_previous_init == nullptr && translated_previous != nullptr) {
        exact_previous_init =
            exactInitializedNameFromTranslatedVariableNode(translated_previous);
      }
    }
    if (exact_previous_init == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-redeclaration-order]: "
              "variable=%s predecessor=%p was not published before its "
              "redeclaration\n",
              name.getString().c_str(), static_cast<void *>(prevDecl));
      ROSE_ABORT();
    }
    SgVariableDeclaration *sgPrevDecl =
        isSgVariableDeclaration(exact_previous_init->get_parent());
    if (sgPrevDecl == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[static-data-member-redeclaration]: "
              "previous Sage initialized name has no variable declaration "
              "owner\n");
      ROSE_ABORT();
    }
    // Every Clang redeclaration belongs to the exact semantic symbol owner of
    // its predecessor.  The declaration statement can be lexically parented by
    // a distinct namespace/class/template fragment, so deriving the symbol
    // scope from that parent creates a second, non-canonical symbol table.
    SgScopeStatement *decl_scope = exact_previous_init->get_scope();
    if (decl_scope == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-redeclaration]: previous "
              "variable=%s has no published semantic scope\n",
              exact_previous_init->get_name().str());
      ROSE_ABORT();
    }
    SgScopeStatement *lexical_scope =
        semantic_static_member_instantiation
            ? decl_scope
            : resolve_exact_variable_lexical_scope();
    sg_var_decl =
        build_var_declaration(decl_scope, lexical_scope, exact_previous_init);
    SgInitializedName *current_init =
        sg_var_decl->get_variables().empty()
            ? nullptr
            : sg_var_decl->get_variables().front();
    if (current_init == nullptr ||
        current_init->get_prev_decl_item() != exact_previous_init) {
      fprintf(stderr, "REX_FRONTEND_INVARIANT[variable-redeclaration]: current "
                      "declaration did not preserve its exact predecessor\n");
      ROSE_ABORT();
    }
  } else {
    SgScopeStatement *decl_scope = SageBuilder::topScopeStack();
    SgScopeStatement *lexical_scope = decl_scope;
    if (decl_scope == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-lexical-owner]: variable=%s "
              "has no active lexical scope\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    if (var_is_init_capture) {
      const clang::FunctionDecl *capture_function_owner = nullptr;
      unsigned capture_owner_occurrences = 0;
      for (auto frame = p_lambda_init_capture_owner_stack.rbegin();
           frame != p_lambda_init_capture_owner_stack.rend(); ++frame) {
        if (frame->declarations.count(var_decl) == 0) {
          continue;
        }
        ++capture_owner_occurrences;
        capture_function_owner = frame->call_operator;
      }
      if (capture_owner_occurrences != 1 || capture_function_owner == nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[lambda-capture-owner]: "
                "init-capture '%s' has %u active LambdaExpr owners instead "
                "of exactly one\n",
                name.str(), capture_owner_occurrences);
        ROSE_ABORT();
      }
      clang::DeclContext *capture_context =
          const_cast<clang::FunctionDecl *>(capture_function_owner);
      SgScopeStatement *resolved_capture_scope =
          resolveScopeFromDeclContext(capture_context);
      SgFunctionDefinition *capture_function =
          isSgFunctionDefinition(resolved_capture_scope);
      SgBasicBlock *active_capture_body =
          capture_function != nullptr ? capture_function->get_body() : nullptr;
      if (capture_function == nullptr || active_capture_body == nullptr ||
          active_capture_body->get_parent() != capture_function) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[lambda-capture-scope]: init-capture "
                "'%s' has no exact published lambda body\n",
                name.str());
        ROSE_ABORT();
      }
      decl_scope = active_capture_body;
      lexical_scope = active_capture_body;
    }
    if (!isStaticDataMember && var_is_file_var_decl) {
      decl_scope = resolveScopeFromDeclContext(defined_var_decl_context());
      lexical_scope = resolve_exact_variable_lexical_scope();
    }
    if (static_member_owner_scope != nullptr) {
      // Out-of-line static-member declarations are lexically emitted in the
      // surrounding namespace, but their initialized-name identity and symbol
      // belong to the declaring class. Implicit instantiations own no source
      // surface and are born directly in that class's auxiliary semantic list.
      decl_scope = static_member_owner_scope;
      lexical_scope = semantic_static_member_instantiation
                          ? static_member_owner_scope
                          : resolve_exact_variable_lexical_scope();
    }
    sg_var_decl = build_var_declaration(decl_scope, lexical_scope);
    if (var_is_init_capture) {
      SgInitializedName *capture_name =
          SageInterface::getFirstInitializedName(sg_var_decl);
      if (capture_name == nullptr || capture_name->get_scope() != decl_scope ||
          decl_scope->find_symbol_from_declaration(capture_name) == nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[lambda-capture-symbol]: "
                "init-capture '%s' was not registered in the lambda body\n",
                name.str());
        ROSE_ABORT();
      }
    }
  }

  ROSE_ASSERT(sg_var_decl != nullptr);
  const bool semantic_range_for_declaration =
      !p_semantic_range_for_declaration_shell_stack.empty() &&
      p_semantic_range_for_declaration_shell_stack.back() == var_decl;
  if (semantic_range_for_declaration) {
    SgInitializedName *semantic_name =
        SageInterface::getFirstInitializedName(sg_var_decl);
    SgVariableDefinition *semantic_definition =
        semantic_name != nullptr ? semantic_name->get_definition() : nullptr;
    if (semantic_name == nullptr || semantic_definition == nullptr ||
        !p_semantic_range_declaration_shell_nodes.insert(sg_var_decl).second ||
        !p_semantic_range_declaration_shell_nodes.insert(semantic_name)
             .second ||
        !p_semantic_range_declaration_shell_nodes.insert(semantic_definition)
             .second) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[range-for-semantic-declaration]: "
              "variable=%s did not publish exactly one declaration/name/"
              "definition shell transaction\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
  }
  if (declarator_owned_nondefining_tag != nullptr) {
    attach_exact_base_type_nondefining_declaration(
        sg_var_decl, declarator_owned_nondefining_tag, type,
        "VisitVarDecl:declarator-owned-nondefining-tag");
  }
  if (sg_var_decl->get_baseTypeNondefiningDeclaration() !=
      declarator_owned_nondefining_tag) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[embedded-base-introduction-owner]: new "
            "variable=%s does not own exactly its construction-time "
            "nondefining tag introduction\n",
            name.getString().c_str());
    ROSE_ABORT();
  }
  if (sg_var_decl->get_baseTypeDefiningDeclaration() !=
      embedded_variable_definition) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[embedded-base-owner]: new variable=%s "
            "does not own exactly its construction-time base-type definition\n",
            name.getString().c_str());
    ROSE_ABORT();
  }
  if (embedded_variable_definition != nullptr) {
    if (semantic_declarator_owned_tag_definition) {
      if (embedded_variable_definition->get_parent() != sg_var_decl ||
          sg_var_decl->get_baseTypeDefiningDeclaration() !=
              embedded_variable_definition ||
          embedded_variable_definition->get_scope() !=
              sg_var_decl->get_variables().front()->get_scope() ||
          declaration_has_real_source(embedded_variable_definition)) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[semantic-declarator-tag-owner]: "
                "variable=%s did not adopt its exact source-less semantic "
                "definition child\n",
                name.getString().c_str());
        ROSE_ABORT();
      }
      validate_semantic_provenance(
          embedded_variable_definition, true,
          "VisitVarDecl:semantic-declarator-tag-publication");
    } else {
      publish_exact_typed_owner_tag_output_role(
          embedded_variable_definition, sg_var_decl,
          "VisitVarDecl:inline-tag-definition-publication");
    }
  }
  SgInitializedName *current_redeclaration_name =
      sg_var_decl->get_variables().size() == 1
          ? sg_var_decl->get_variables().front()
          : nullptr;
  ROSE_ASSERT(current_redeclaration_name != nullptr);
  if (previous_variable_decl != nullptr &&
      current_redeclaration_name->get_prev_decl_item() == nullptr) {
    std::cerr << "REX_FRONTEND_INVARIANT[variable-redeclaration]: variable "
                 "redeclaration was published without its exact Clang "
                 "predecessor"
              << std::endl;
    ROSE_ABORT();
  }

  if (!written_template_headers.empty()) {
    for (size_t header_index = 0;
         header_index < written_template_headers.size(); ++header_index) {
      clang::TemplateParameterList *clang_header =
          written_template_headers[header_index];
      std::unique_ptr<SgTemplateParameterPtrList> &translated_header =
          translated_written_template_headers[header_index];
      if (translated_header == nullptr ||
          translated_header->size() != clang_header->size()) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-template-header]: "
                "variable=%s header=%u translated %zu of %u parameters\n",
                var_decl->getQualifiedNameAsString().c_str(),
                static_cast<unsigned>(header_index),
                translated_header != nullptr ? translated_header->size() : 0,
                clang_header->size());
        ROSE_ABORT();
      }

      SgTemplateParameterList *source_header = new SgTemplateParameterList();
      source_header->set_args(*translated_header);
      source_header->set_parent(sg_var_decl);
      publishSourceSpelledTemplateHeaderSeparator(
          source_header, clang_header, p_compiler_instance,
          "VisitVarDecl:source-spelled-outer-template-header");
      for (SgTemplateParameter *parameter : source_header->get_args()) {
        if (parameter == nullptr) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[variable-template-header]: "
                  "variable=%s header=%u contains a null parameter\n",
                  var_decl->getQualifiedNameAsString().c_str(),
                  static_cast<unsigned>(header_index));
          ROSE_ABORT();
        }
        parameter->set_parent(source_header);
      }
      sg_var_decl->get_sourceSpelledTemplateHeaders().push_back(source_header);
    }

    if (current_redeclaration_name->get_scope() !=
        written_template_semantic_scope) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-template-header-owner]: "
              "variable=%s initialized-name semantic scope=%p changed from "
              "the exact pretranslated header scope=%p\n",
              var_decl->getQualifiedNameAsString().c_str(),
              static_cast<void *>(current_redeclaration_name->get_scope()),
              static_cast<void *>(written_template_semantic_scope));
      ROSE_ABORT();
    }

    clang::NestedNameSpecifierLoc written_owner_loc =
        markClangNestedNameSpecifierLocDefined(readClangApiValueDefined(
            [&]() { return var_decl->getQualifierLoc(); }));
    if (!written_owner_loc) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-template-owner]: "
              "variable=%s has written enclosing template headers but no "
              "exact written owner qualifier location\n",
              var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }

    clang::TypeLoc written_owner_type_loc = readClangTypeLocDefined(
        [&]() { return written_owner_loc.getAsTypeLoc(); });
    if (written_owner_type_loc.isNull()) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-template-owner]: "
              "variable=%s exact written owner qualifier does not terminate "
              "in a type\n",
              var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }

    clang::DeclContext *semantic_context = defined_var_decl_context();
    p_template_parameter_decl_context_stack.push_back(semantic_context);
    ++p_force_written_named_type_qualification_depth;
    SgType *translated_source_owner =
        buildTypeFromTypeLoc(written_owner_type_loc);
    ROSE_ASSERT(p_force_written_named_type_qualification_depth > 0);
    --p_force_written_named_type_qualification_depth;
    p_template_parameter_decl_context_stack.pop_back();
    SgNamedType *source_owner_type = isSgNamedType(translated_source_owner);
    SgDeclarationStatement *source_owner_decl =
        source_owner_type != nullptr ? source_owner_type->get_declaration()
                                     : nullptr;
    const bool exact_source_surface =
        isSgNonrealType(source_owner_type) != nullptr &&
        isSgNonrealDecl(source_owner_decl) != nullptr;
    if (!exact_source_surface ||
        source_owner_type->get_declaration() != source_owner_decl) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-template-owner]: "
              "variable=%s written-type=%s translated=%p/%s declaration=%p/%s "
              "did not produce one exact per-use source template owner "
              "surface\n",
              var_decl->getQualifiedNameAsString().c_str(),
              clangQualTypeAsStringDefinedForFrontend(
                  written_owner_type_loc.getType(),
                  p_compiler_instance->getLangOpts())
                  .c_str(),
              static_cast<void *>(translated_source_owner),
              translated_source_owner != nullptr
                  ? translated_source_owner->class_name().c_str()
                  : "<null>",
              static_cast<void *>(source_owner_decl),
              source_owner_decl != nullptr
                  ? source_owner_decl->class_name().c_str()
                  : "<null>");
      ROSE_ABORT();
    }
    if (SgNonrealDecl *dependent_owner_decl =
            isSgNonrealDecl(source_owner_decl)) {
      dependent_owner_decl->set_suppress_typename(true);
    }
    sg_var_decl->set_sourceSpelledTemplateOwnerType(source_owner_type);
  }

  const bool ordinary_variable_redeclaration =
      previous_variable_decl != nullptr && !isStaticDataMember;
  sg_var_decl->set_isAssociatedWithDeclarationList(
      !implicit_anonymous_aggregate_var && !ordinary_variable_redeclaration);
  if (var_is_constexpr) {
    sg_var_decl->set_is_constexpr(true);
  }
  if (p_compiler_instance->getLangOpts().CPlusPlus &&
      !written_type_spells_elaborated_keyword) {
    sg_var_decl->setSkipElaborateType();
  }

  if (var_specialization_kind == clang::TSK_ExplicitSpecialization &&
      !instantiated_static_member_pattern) {
    // The out-of-line VarDecl is the sole source surface for an explicit
    // static-member specialization.  Clang also inserts a predecessor into
    // the implicitly instantiated class, gives that semantic declaration the
    // same specialization kind and source location, but gives it no written
    // `template <>` header.  The predecessor remains an auxiliary lookup
    // identity; assigning it a source specialization form would invent a
    // header and make the declaration independently emit-able.
    sg_var_decl->set_specialization(SgDeclarationStatement::e_specialization);
    const unsigned header_count =
        countWrittenExplicitTemplateSpecializationHeaders(var_decl);
    if (header_count == 0) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-specialization-header]: "
              "explicit specialization=%s has no exact source-written "
              "empty template header\n",
              var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }
    sg_var_decl->set_explicitTemplateSpecializationHeaderCount(header_count);
  }

  // A variable is in scope within its own initializer. Publish the exact
  // declaration identity after the declaration and symbol exist, but before
  // traversing the initializer, so expressions such as `sizeof *value` bind
  // to this declaration instead of entering an on-demand translation cycle.
  auto published_variable = p_decl_translation_map.find(var_decl);
  const bool replaces_hidden_source_placeholder =
      published_variable != p_decl_translation_map.end() &&
      is_hidden_frontend_placeholder(published_variable->second) &&
      !var_decl->isImplicit() &&
      clangDeclHasNonBuiltinSourceLocation(p_compiler_instance, var_decl);
  if (published_variable != p_decl_translation_map.end() &&
      published_variable->second != sg_var_decl &&
      !replaces_hidden_source_placeholder &&
      !(p_rebuild_translation_cache_depth != 0 &&
        activeFunctionBodyOwnerForDeclaration(var_decl) != nullptr)) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[variable-publication]: Clang variable "
            "'%s' decl=%p canonical=%p previous=%p already maps to "
            "%p/%s instead of new declaration %p/%s before initializer "
            "translation\n",
            var_decl->getQualifiedNameAsString().c_str(),
            static_cast<void *>(var_decl),
            static_cast<void *>(var_decl->getCanonicalDecl()),
            static_cast<void *>(var_decl->getPreviousDecl()),
            static_cast<void *>(published_variable->second),
            published_variable->second != nullptr
                ? published_variable->second->class_name().c_str()
                : "<null>",
            static_cast<void *>(sg_var_decl),
            sg_var_decl->class_name().c_str());
    ROSE_ABORT();
  }
  p_decl_translation_map[var_decl] = sg_var_decl;

  // CLANG FRONTEND FIX: Check if variable has an initializer before traversing
  clang::Expr *init_expr =
      markClangExprObjectDefinedByClass(readClangApiValueDefined([&]() {
        return var_decl->isExceptionVariable() ? nullptr : var_decl->getInit();
      }));
  SgExpression *expr = nullptr;
  SgExprListExp *expr_list_expr = nullptr;
  SgInitializer *init = nullptr;
  SgInitializer *initializer_translated_from_exact_source = nullptr;
  SgNode *tmp_init = nullptr;
  if (init_expr != nullptr) {
    tmp_init = Traverse(init_expr);
    expr = isSgExpression(tmp_init);
    if (expr != nullptr) {
      expr = prepareExpressionForAttachment(expr);
      if (expr == nullptr) {
        std::cerr
            << "REX_FRONTEND_INVARIANT[variable-initializer-owner]: variable="
            << name
            << " initializer could not produce an exact owned expression "
               "tree"
            << std::endl;
        ROSE_ABORT();
      }
      tmp_init = expr;
    }
    initializer_translated_from_exact_source = isSgInitializer(tmp_init);
    if (tmp_init != nullptr && expr == nullptr) {
      if (SgInitializer *tmp_init_initializer = isSgInitializer(tmp_init)) {
        init = tmp_init_initializer;
      } else {
        std::cerr << "REX_FRONTEND_INVARIANT[variable-initializer]: variable="
                  << name << " Clang initializer translated to "
                  << tmp_init->class_name()
                  << " instead of an expression or initializer" << std::endl;
        ROSE_ABORT();
      }
    }
    if (expr != nullptr) {
      expr_list_expr = isSgExprListExp(expr);
      if (expr_list_expr != nullptr) {
        if (var_is_direct_init && var_init_style != clang::VarDecl::ListInit) {
          const bool class_unknown =
              constructorInitializerAssociatedClassUnknown(type);
          SgConstructorInitializer *ctor_init =
              SageBuilder::buildConstructorInitializer_nfi(
                  nullptr, expr_list_expr, type,
                  false, // need_name
                  false, // need_qualifier
                  true,  // need_parenthesis_after_name
                  class_unknown);
          ctor_init->set_is_braced_initialized(false);
          init = ctor_init;
        } else if (var_is_direct_init &&
                   var_init_style == clang::VarDecl::ListInit) {
          const bool class_unknown =
              constructorInitializerAssociatedClassUnknown(type);
          SgConstructorInitializer *ctor_init =
              SageBuilder::buildConstructorInitializer_nfi(
                  nullptr, expr_list_expr, type,
                  false, // need_name
                  false, // need_qualifier
                  false, // need_parenthesis_after_name
                  class_unknown);
          ctor_init->set_is_braced_initialized(true);
          init = ctor_init;
        } else {
          init = SageBuilder::buildAggregateInitializer_nfi(
              expr_list_expr, type,
              SgAggregateInitializer::e_aggregate_initializer_source_braced);
        }
      } else if (SgConstructorInitializer *ctor_init =
                     isSgConstructorInitializer(expr)) {
        if (var_init_style == clang::VarDecl::CInit) {
          init = SageBuilder::buildAssignInitializer_nfi(ctor_init, type);
        } else {
          init = ctor_init;
        }
      } else if (SgInitializer *existing_init = isSgInitializer(expr)) {
        init = existing_init;
      } else if (p_compiler_instance->getLangOpts().CPlusPlus &&
                 var_is_direct_init &&
                 var_init_style != clang::VarDecl::ListInit) {
        SgExprListExp *args = SageBuilder::buildExprListExp_nfi();
        args->append_expression(expr);
        applySourceRange(args, init_expr->getSourceRange());

        const bool class_unknown =
            constructorInitializerAssociatedClassUnknown(type);
        SgConstructorInitializer *ctor_init =
            SageBuilder::buildConstructorInitializer_nfi(
                nullptr, args, type,
                false, // need_name
                false, // need_qualifier
                true,  // need_parenthesis_after_name
                class_unknown);
        ctor_init->set_is_braced_initialized(false);
        init = ctor_init;
      } else {
        init = SageBuilder::buildAssignInitializer_nfi(expr, type);
      }
    }
  }
  if (init_expr != nullptr && init == nullptr) {
    std::cerr << "REX_FRONTEND_INVARIANT[variable-initializer]: variable="
              << name
              << " has a Clang initializer but no exact Sage initializer"
              << std::endl;
    ROSE_ABORT();
  }

  // Pei-Hung (09/01/2022) setup initializer once the RHS is processed.
  // CLANG FRONTEND FIX: Only set initializer if it's not nullptr
  if (init != nullptr) {
    sg_var_decl->reset_initializer(init);
  }

  // CLANG FRONTEND FIX: Set initializer parent AFTER reset_initializer
  // reset_initializer sets the parent of the initializer to the
  // SgInitializedName, not the SgVariableDeclaration. Setting it to sg_var_decl
  // here was wrong. Only apply source range if we have both the initializer and
  // the original expression
  if (init != nullptr && init_expr != nullptr) {
    // Pei-Hung (07/12/2023):
    // applySourceRange should be set whenever the SgInitializer was just
    // created. Otherwise, it could overwrite the setting done in
    // setSynthesizedFileInfo.
    if (init != initializer_translated_from_exact_source) {
      clang::SourceRange init_range =
          isSgAssignInitializer(init) != nullptr
              ? computeAssignmentInitializerLexicalSurface(
                    p_compiler_instance->getSourceManager(),
                    p_compiler_instance->getLangOpts(),
                    clangVarDeclSourceRangeDefined(var_decl),
                    init_expr->getSourceRange())
                    .range
              : computeInitializerLexicalRange(
                    p_compiler_instance->getSourceManager(),
                    clangVarDeclSourceRangeDefined(var_decl),
                    init_expr->getSourceRange());
      applySourceRange(init, init_range);
    }
  }

  if (init != nullptr && init_expr != nullptr &&
      p_sage_preprocessor_recorder != nullptr &&
      isSgAssignInitializer(init) != nullptr) {
    clang::SourceManager &source_manager =
        p_compiler_instance->getSourceManager();
    const AssignmentInitializerLexicalSurface initializer_surface =
        computeAssignmentInitializerLexicalSurface(
            source_manager, p_compiler_instance->getLangOpts(),
            clangVarDeclSourceRangeDefined(var_decl),
            init_expr->getSourceRange());
    const clang::SourceRange initializer_range = initializer_surface.range;
    const bool complete_include_expansion =
        initializer_surface.source_form ==
        SgAssignInitializer::
            e_assignment_initializer_source_include_complete_expansion;
    clang::SourceLocation physical_begin =
        source_manager.getFileLoc(initializer_range.getBegin());
    clang::SourceLocation physical_end =
        source_manager.getFileLoc(initializer_range.getEnd());
    clang::SourceLocation physical_after_end =
        physical_end.isValid()
            ? source_manager.getFileLoc(clang::Lexer::getLocForEndOfToken(
                  physical_end, 0, source_manager,
                  p_compiler_instance->getLangOpts()))
            : clang::SourceLocation();
    const clang::FileID physical_file =
        physical_begin.isValid() ? source_manager.getFileID(physical_begin)
                                 : clang::FileID();
    const bool has_physical_interval =
        physical_begin.isValid() && physical_end.isValid() &&
        physical_after_end.isValid() && physical_file.isValid() &&
        source_manager.getFileID(physical_end) == physical_file &&
        source_manager.getFileID(physical_after_end) == physical_file &&
        source_manager.getFileOffset(physical_begin) <
            source_manager.getFileOffset(physical_after_end);
    const bool macro_owned_ast_surface =
        initializer_surface.source_form ==
            SgAssignInitializer::e_assignment_initializer_source_ast &&
        (initializer_range.getBegin().isMacroID() ||
         initializer_range.getEnd().isMacroID());
    if (!has_physical_interval && !macro_owned_ast_surface) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[assignment-initializer-include-owner]: "
              "variable=%s has neither an exact physical initializer interval "
              "nor an AST-owned macro surface\n",
              name.getString().c_str());
      ROSE_ABORT();
    }

    // Preprocessor directives cannot be introduced by a macro replacement
    // list.  A macro-owned AST initializer can therefore have a retrograde
    // pair of expansion locations (for example, an argument followed by a
    // replacement-list token) without defining any physical interval in which
    // an include directive could live.
    std::vector<clang::SourceLocation> initializer_includes;
    if (has_physical_interval) {
      initializer_includes =
          complete_include_expansion
              ? p_sage_preprocessor_recorder
                    ->includeDirectiveLocationsAtStartOrStrictlyInside(
                        initializer_range)
              : p_sage_preprocessor_recorder
                    ->includeDirectiveLocationsStrictlyInside(
                        initializer_range);
    }
    if (initializer_surface.source_form !=
            SgAssignInitializer::e_assignment_initializer_source_ast &&
        initializer_includes.empty()) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[assignment-initializer-include-owner]: "
              "variable=%s directive-expanded initializer has no exact "
              "recorded include owner\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    if (!initializer_includes.empty()) {
      SgAssignInitializer *assignment_initializer = isSgAssignInitializer(init);
      if (initializer_surface.source_form ==
          SgAssignInitializer::e_assignment_initializer_source_ast) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[assignment-initializer-include-owner]: "
                "variable=%s scalar initializer mixes AST-owned and "
                "include-owned source tokens\n",
                name.getString().c_str());
        ROSE_ABORT();
      }
      SgExpression *operand = assignment_initializer->get_operand_i();
      clang::SourceLocation range_begin =
          source_manager.getFileLoc(initializer_range.getBegin());
      clang::SourceLocation range_end =
          source_manager.getFileLoc(initializer_range.getEnd());
      clang::FileID owner_file = source_manager.getFileID(range_begin);
      if (operand == nullptr ||
          operand->get_parent() != assignment_initializer ||
          initializer_includes.size() != 1 || range_begin.isInvalid() ||
          range_end.isInvalid() || !owner_file.isValid() ||
          source_manager.getFileID(range_end) != owner_file) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[assignment-initializer-include-owner]: "
                "variable=%s include-expanded scalar initializer has no one "
                "exact operand, directive, or physical owner\n",
                name.getString().c_str());
        ROSE_ABORT();
      }

      clang::SourceLocation physical_include =
          source_manager.getFileLoc(initializer_includes.front());
      clang::SourceLocation expansion_begin = source_manager.getFileLoc(
          source_manager.getExpansionLoc(init_expr->getBeginLoc()));
      clang::SourceLocation expansion_end = source_manager.getFileLoc(
          source_manager.getExpansionLoc(init_expr->getEndLoc()));
      clang::SourceLocation projected_begin =
          projectInitializerElementToPhysicalFile(
              source_manager, init_expr->getBeginLoc(), owner_file);
      clang::SourceLocation projected_end =
          projectInitializerElementToPhysicalFile(
              source_manager, init_expr->getEndLoc(), owner_file);
      clang::FileID expansion_file = source_manager.getFileID(expansion_begin);
      const unsigned include_begin =
          physical_include.isValid()
              ? source_manager.getFileOffset(physical_include)
              : 0;
      const unsigned include_end =
          physical_include.isValid()
              ? initializerIncludeDirectiveEndOffset(source_manager, owner_file,
                                                     include_begin)
              : include_begin;
      const unsigned projected_begin_offset =
          projected_begin.isValid()
              ? source_manager.getFileOffset(projected_begin)
              : include_end;
      const unsigned projected_end_offset =
          projected_end.isValid() ? source_manager.getFileOffset(projected_end)
                                  : include_end;
      if (physical_include.isInvalid() ||
          source_manager.getFileID(physical_include) != owner_file ||
          expansion_begin.isInvalid() || expansion_end.isInvalid() ||
          !expansion_file.isValid() || expansion_file == owner_file ||
          source_manager.getFileID(expansion_end) != expansion_file ||
          projected_begin.isInvalid() || projected_end.isInvalid() ||
          projected_begin_offset < include_begin ||
          projected_begin_offset >= include_end ||
          projected_end_offset < include_begin ||
          projected_end_offset >= include_end) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[assignment-initializer-include-owner]: "
                "variable=%s scalar operand is not wholly owned by its one "
                "recorded include directive\n",
                name.getString().c_str());
        ROSE_ABORT();
      }

      assignment_initializer->set_source_form(initializer_surface.source_form);
      p_sage_preprocessor_recorder
          ->transferIncludeDirectiveToAssignmentInitializer(
              initializer_includes.front(), assignment_initializer);
    }
  }

  if (init != nullptr && init_expr != nullptr &&
      p_sage_preprocessor_recorder != nullptr &&
      isSgAggregateInitializer(init) != nullptr &&
      llvm::isa<clang::InitListExpr>(init_expr)) {
    clang::SourceManager &source_manager =
        p_compiler_instance->getSourceManager();
    clang::SourceRange initializer_range = computeInitializerLexicalRange(
        source_manager, clangVarDeclSourceRangeDefined(var_decl),
        init_expr->getSourceRange());
    std::vector<clang::SourceLocation> initializer_includes =
        p_sage_preprocessor_recorder->includeDirectiveLocationsStrictlyInside(
            initializer_range);
    if (!initializer_includes.empty()) {
      SgAggregateInitializer *aggregate_initializer =
          isSgAggregateInitializer(init);
      clang::InitListExpr *clang_initializer_list =
          llvm::dyn_cast<clang::InitListExpr>(init_expr);
      if (aggregate_initializer == nullptr ||
          clang_initializer_list == nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                "source include inside variable=%s has no typed aggregate "
                "initializer surface\n",
                name.getString().c_str());
        ROSE_ABORT();
      }

      clang_initializer_list =
          markClangAstObjectDefined(clang_initializer_list);
      if (clang::InitListExpr *syntactic_form =
              markClangAstObjectDefined(readClangApiValueDefined([&]() {
                return clang_initializer_list->getSyntacticForm();
              }))) {
        clang_initializer_list = syntactic_form;
      }
      SgExprListExp *sage_initializer_list =
          aggregate_initializer->get_initializers();
      const unsigned clang_element_count = readClangApiValueDefined(
          [&]() { return clang_initializer_list->getNumInits(); });
      if (sage_initializer_list == nullptr ||
          sage_initializer_list->get_parent() != aggregate_initializer ||
          sage_initializer_list->get_expressions().size() !=
              clang_element_count) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                "variable=%s does not preserve one Sage element per exact "
                "Clang source initializer\n",
                name.getString().c_str());
        ROSE_ABORT();
      }

      clang::SourceLocation range_begin =
          source_manager.getFileLoc(initializer_range.getBegin());
      clang::SourceLocation range_end =
          source_manager.getFileLoc(initializer_range.getEnd());
      if (range_begin.isInvalid() || range_end.isInvalid()) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                "variable=%s initializer has no exact file locations\n",
                name.getString().c_str());
        ROSE_ABORT();
      }
      clang::FileID owner_file = source_manager.getFileID(range_begin);
      if (!owner_file.isValid() ||
          source_manager.getFileID(range_end) != owner_file) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                "variable=%s initializer has no exact physical source file\n",
                name.getString().c_str());
        ROSE_ABORT();
      }

      std::vector<unsigned> element_offsets;
      std::vector<unsigned> element_source_begins;
      std::vector<unsigned> element_source_ends;
      std::vector<int> element_include_range_indices;
      SgUnsignedCharList source_element_roles;
      element_offsets.reserve(clang_element_count);
      element_source_begins.reserve(clang_element_count);
      element_source_ends.reserve(clang_element_count);
      element_include_range_indices.reserve(clang_element_count);
      source_element_roles.reserve(clang_element_count);
      std::vector<std::pair<unsigned, unsigned>> include_ranges;
      for (clang::SourceLocation include_location : initializer_includes) {
        clang::SourceLocation physical_include =
            source_manager.getFileLoc(include_location);
        if (physical_include.isInvalid() ||
            source_manager.getFileID(physical_include) != owner_file) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                  "variable=%s include does not belong to the aggregate's "
                  "physical source file\n",
                  name.getString().c_str());
          ROSE_ABORT();
        }
        const unsigned include_begin =
            source_manager.getFileOffset(physical_include);
        const unsigned include_end = initializerIncludeDirectiveEndOffset(
            source_manager, owner_file, include_begin);
        if (include_end <= include_begin) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                  "variable=%s include has no exact physical directive "
                  "range\n",
                  name.getString().c_str());
          ROSE_ABORT();
        }
        if (!include_ranges.empty() &&
            include_begin < include_ranges.back().second) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                  "variable=%s has overlapping include directive ranges\n",
                  name.getString().c_str());
          ROSE_ABORT();
        }
        include_ranges.emplace_back(include_begin, include_end);
      }
      for (unsigned index = 0; index < clang_element_count; ++index) {
        clang::Expr *clang_element =
            markClangAstObjectDefined(readClangApiValueDefined(
                [&]() { return clang_initializer_list->getInit(index); }));
        clang::SourceLocation projected =
            clang_element != nullptr
                ? projectInitializerElementToPhysicalFile(
                      source_manager, clang_element->getBeginLoc(), owner_file)
                : clang::SourceLocation();
        if (projected.isInvalid()) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                  "variable=%s element=%u has no exact source projection "
                  "into its aggregate owner\n",
                  name.getString().c_str(), index);
          ROSE_ABORT();
        }
        const unsigned offset = source_manager.getFileOffset(projected);
        if (!element_offsets.empty() && offset < element_offsets.back()) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                  "variable=%s initializer source boundaries are not "
                  "monotonic at element=%u\n",
                  name.getString().c_str(), index);
          ROSE_ABORT();
        }
        element_offsets.push_back(offset);

        clang::SourceLocation expansion_location = source_manager.getFileLoc(
            source_manager.getExpansionLoc(clang_element->getBeginLoc()));
        clang::FileID expansion_file =
            source_manager.getFileID(expansion_location);
        if (expansion_location.isInvalid() || !expansion_file.isValid()) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                  "variable=%s element=%u has no exact expansion file\n",
                  name.getString().c_str(), index);
          ROSE_ABORT();
        }
        const bool include_owned = expansion_file != owner_file;
        int matching_include_index = -1;
        size_t matching_include_count = 0;
        for (size_t include_index = 0; include_index < include_ranges.size();
             ++include_index) {
          const auto &range = include_ranges[include_index];
          if (range.first <= offset && offset < range.second) {
            matching_include_index = static_cast<int>(include_index);
            ++matching_include_count;
          }
        }
        if (include_owned && matching_include_count != 1) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                  "variable=%s cross-file element=%u does not project to one "
                  "recorded include directive range\n",
                  name.getString().c_str(), index);
          ROSE_ABORT();
        }
        if (!include_owned && matching_include_count != 0) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                  "variable=%s owner-file element=%u projects inside an "
                  "include directive range\n",
                  name.getString().c_str(), index);
          ROSE_ABORT();
        }
        unsigned source_begin = offset;
        unsigned source_end = 0;
        if (include_owned) {
          const auto &include_range =
              include_ranges.at(static_cast<size_t>(matching_include_index));
          source_begin = include_range.first;
          source_end = include_range.second;
        } else {
          clang::SourceLocation projected_end =
              projectInitializerElementToPhysicalFile(
                  source_manager, clang_element->getEndLoc(), owner_file);
          clang::SourceLocation after_end =
              projected_end.isValid() ? clang::Lexer::getLocForEndOfToken(
                                            projected_end, 0, source_manager,
                                            p_compiler_instance->getLangOpts())
                                      : clang::SourceLocation();
          after_end = source_manager.getFileLoc(after_end);
          if (after_end.isInvalid() ||
              source_manager.getFileID(after_end) != owner_file) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                    "variable=%s owner-file element=%u has no exact source "
                    "end\n",
                    name.getString().c_str(), index);
            ROSE_ABORT();
          }
          source_end = source_manager.getFileOffset(after_end);
        }
        if (source_end < source_begin) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                  "variable=%s element=%u has a retrograde physical source "
                  "interval\n",
                  name.getString().c_str(), index);
          ROSE_ABORT();
        }
        element_source_begins.push_back(source_begin);
        element_source_ends.push_back(source_end);
        element_include_range_indices.push_back(matching_include_index);
        source_element_roles.push_back(static_cast<unsigned char>(
            include_owned
                ? SgAggregateInitializer::e_source_element_include_expansion
                : SgAggregateInitializer::e_source_element_ast));
      }

      for (unsigned index = 1; index < clang_element_count; ++index) {
        const int previous_include = element_include_range_indices[index - 1];
        const int current_include = element_include_range_indices[index];
        if ((previous_include < 0 && current_include < 0) ||
            (previous_include >= 0 && previous_include == current_include)) {
          continue;
        }
        const unsigned separator_begin = element_source_ends[index - 1];
        const unsigned separator_end = element_source_begins[index];
        if (separator_begin > separator_end) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[initializer-owner-separator]: "
                  "variable=%s element=%u has a retrograde separator "
                  "interval\n",
                  name.getString().c_str(), index);
          ROSE_ABORT();
        }
        const size_t owner_separator_count =
            countInitializerOwnerSeparatorTokens(
                source_manager, p_compiler_instance->getLangOpts(), owner_file,
                separator_begin, separator_end);
        if (owner_separator_count > 1) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[initializer-owner-separator]: "
                  "variable=%s element=%u has %zu owner-file comma tokens "
                  "between adjacent initializer source regions\n",
                  name.getString().c_str(), index, owner_separator_count);
          ROSE_ABORT();
        }
        if (owner_separator_count == 1) {
          source_element_roles[index] = static_cast<unsigned char>(
              current_include >= 0
                  ? SgAggregateInitializer::
                        e_source_element_include_expansion_after_owner_separator
                  : SgAggregateInitializer::
                        e_source_element_ast_after_owner_separator);
        }
      }
      aggregate_initializer->set_source_element_roles(source_element_roles);

      for (clang::SourceLocation include_location : initializer_includes) {
        clang::SourceLocation physical_include =
            source_manager.getFileLoc(include_location);
        if (physical_include.isInvalid() ||
            source_manager.getFileID(physical_include) != owner_file) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                  "variable=%s include does not belong to the aggregate's "
                  "physical source file\n",
                  name.getString().c_str());
          ROSE_ABORT();
        }
        const unsigned include_offset =
            source_manager.getFileOffset(physical_include);
        const auto following = std::lower_bound(
            element_offsets.begin(), element_offsets.end(), include_offset);
        SgExpression *following_element = nullptr;
        if (following != element_offsets.end()) {
          const size_t index =
              static_cast<size_t>(following - element_offsets.begin());
          following_element =
              sage_initializer_list->get_expressions().at(index);
          if (following_element == nullptr) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[initializer-include-owner]: "
                    "variable=%s exact following initializer is null\n",
                    name.getString().c_str());
            ROSE_ABORT();
          }
        }
        p_sage_preprocessor_recorder
            ->transferIncludeDirectiveToInitializerBoundary(
                include_location, aggregate_initializer, following_element);
      }
    }
  }

  type = stripSageDeclaratorBaseType(type);

  if (isSgClassType(type) && isDefinitionRequired) {
    SgClassDeclaration *class_definition =
        isSgClassDeclaration(embedded_variable_definition);
    if (class_definition == nullptr ||
        sg_var_decl->get_baseTypeDefiningDeclaration() != class_definition ||
        class_definition->get_parent() != sg_var_decl) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[embedded-variable-class-owner]: "
              "variable=%s did not preserve its construction-time embedded "
              "class definition\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    SgClassType *tracked_class_type =
        canonicalClassTypeForFirstSeenTracking(type);
    ROSE_ASSERT(tracked_class_type != nullptr);
    std::map<SgClassType *, bool>::iterator bool_it =
        p_class_type_decl_first_see_in_type.find(tracked_class_type);
    ROSE_ASSERT(bool_it != p_class_type_decl_first_see_in_type.end());
    bool_it->second = false;
  } else if (isSgEnumType(type) && isDefinitionRequired) {
    SgEnumDeclaration *enum_definition =
        isSgEnumDeclaration(embedded_variable_definition);
    if (enum_definition == nullptr ||
        sg_var_decl->get_baseTypeDefiningDeclaration() != enum_definition ||
        enum_definition->get_parent() != sg_var_decl) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[embedded-variable-enum-owner]: "
              "variable=%s did not preserve its construction-time embedded "
              "enum definition\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    SgEnumType *tracked_enum_type = canonicalEnumTypeForFirstSeenTracking(type);
    ROSE_ASSERT(tracked_enum_type != nullptr);
    std::map<SgEnumType *, bool>::iterator bool_it =
        p_enum_type_decl_first_see_in_type.find(tracked_enum_type);
    ROSE_ASSERT(bool_it != p_enum_type_decl_first_see_in_type.end());
    bool_it->second = false;
  }

  sg_var_decl->set_firstNondefiningDeclaration(sg_var_decl);
  auto require_exact_pending_for_init =
      [&](SgScopeStatement *candidate_scope) -> bool {
    return require_exact_pending_typed_declaration_scope(candidate_scope);
  };
  if (SgAuxiliaryDeclarationList *container =
          isSgAuxiliaryDeclarationList(sg_var_decl->get_parent())) {
    SgScopeStatement *owner = isSgScopeStatement(container->get_parent());
    if (owner == nullptr || owner->get_auxiliary_declarations() != container ||
        sg_var_decl->get_scope() != owner ||
        std::count(container->get_declarations().begin(),
                   container->get_declarations().end(), sg_var_decl) != 1) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-auxiliary-owner]: variable=%s "
              "has malformed recursive semantic ownership\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
  } else {
    SgDeclarationGroupStatement *group_parent =
        isSgDeclarationGroupStatement(sg_var_decl->get_parent());
    SgScopeStatement *decl_parent =
        isSgScopeStatement(sg_var_decl->get_parent());
    if (group_parent != nullptr) {
      SgScopeStatement *group_scope = group_parent->get_scope();
      const bool pending_for_init_group =
          require_exact_pending_for_init(group_scope);
      if (group_parent != source_group_owner || group_scope == nullptr ||
          group_parent->get_parent() != nullptr ||
          std::count(group_parent->get_declarations().begin(),
                     group_parent->get_declarations().end(),
                     sg_var_decl) != 1 ||
          (!pending_for_init_group &&
           exact_lexical_declaration_group_reference_count(group_scope,
                                                           sg_var_decl) != 0)) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-source-group-owner]: "
                "variable=%s has malformed detached group ownership\n",
                name.getString().c_str());
        ROSE_ABORT();
      }
    } else {
      const bool pending_for_init_owner =
          source_group_owner == nullptr &&
          require_exact_pending_for_init(pending_for_init_scope);
      const bool exact_lexical_owner =
          pending_for_init_owner
              ? sg_var_decl->get_parent() == nullptr
              : decl_parent != nullptr && source_group_owner == nullptr &&
                    is_decl_attached_to_scope_child_list(
                        p_decl_attachment_session, decl_parent, sg_var_decl);
      if (!exact_lexical_owner) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-lexical-owner]: variable=%s "
                "has no exact construction-time lexical ownership contract\n",
                name.getString().c_str());
        ROSE_ABORT();
      }
    }
  }

  publishExactEffectiveDeclarationAccess(var_decl, sg_var_decl, "VisitVarDecl");

  ROSE_ASSERT(sg_var_decl->get_variables().size() == 1);

  SgInitializedName *init_name = sg_var_decl->get_variables()[0];
  ROSE_ASSERT(init_name != nullptr);
  init_name->set_cxx_source_type(cxx_source_type);
  const bool exact_source_semantic_match =
      cxx_source_type == nullptr ||
      SageInterface::cxxSourceTypeMatchesSemanticType(cxx_source_type,
                                                      init_name->get_type());
  if (cxx_source_type != nullptr && (cxx_source_type == init_name->get_type() ||
                                     !exact_source_semantic_match)) {
    SgNonrealDecl *source_type_declaration = isSgNonrealDecl(
        isSgNonrealType(cxx_source_type) != nullptr
            ? isSgNonrealType(cxx_source_type)->get_declaration()
            : nullptr);
    SgClassDeclaration *semantic_type_declaration = isSgClassDeclaration(
        isSgClassType(init_name->get_type()) != nullptr
            ? isSgClassType(init_name->get_type())->get_declaration()
            : nullptr);
    SgClassDeclaration *semantic_first = isSgClassDeclaration(
        semantic_type_declaration != nullptr
            ? semantic_type_declaration->get_firstNondefiningDeclaration()
            : nullptr);
    SgClassDeclaration *semantic_defining = isSgClassDeclaration(
        semantic_type_declaration != nullptr
            ? semantic_type_declaration->get_definingDeclaration()
            : nullptr);
    SgTemplateInstantiationDecl *semantic_instantiation =
        isSgTemplateInstantiationDecl(semantic_type_declaration);
    if (semantic_instantiation == nullptr) {
      semantic_instantiation = isSgTemplateInstantiationDecl(semantic_first);
    }
    if (semantic_instantiation == nullptr) {
      semantic_instantiation = isSgTemplateInstantiationDecl(semantic_defining);
    }
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[variable-template-type-surface]: "
            "variable=%s did not publish distinct exact source and semantic "
            "type identities source=%p/%s semantic=%p/%s translated=%p/%s "
            "match=%d source-declaration=%p template=%p arguments=%zu "
            "semantic-declaration=%p/%s first=%p/%s defining=%p/%s "
            "instantiation=%p template=%p arguments=%zu\n",
            var_decl->getQualifiedNameAsString().c_str(),
            static_cast<void *>(cxx_source_type),
            cxx_source_type->class_name().c_str(),
            static_cast<void *>(init_name->get_type()),
            init_name->get_type() != nullptr
                ? init_name->get_type()->class_name().c_str()
                : "<null>",
            static_cast<void *>(sg_varType),
            sg_varType != nullptr ? sg_varType->class_name().c_str() : "<null>",
            exact_source_semantic_match ? 1 : 0,
            static_cast<void *>(source_type_declaration),
            static_cast<void *>(
                source_type_declaration != nullptr
                    ? source_type_declaration->get_templateDeclaration()
                    : nullptr),
            source_type_declaration != nullptr
                ? source_type_declaration->get_tpl_args().size()
                : 0,
            static_cast<void *>(semantic_type_declaration),
            semantic_type_declaration != nullptr
                ? semantic_type_declaration->class_name().c_str()
                : "<null>",
            static_cast<void *>(semantic_first),
            semantic_first != nullptr ? semantic_first->class_name().c_str()
                                      : "<null>",
            static_cast<void *>(semantic_defining),
            semantic_defining != nullptr
                ? semantic_defining->class_name().c_str()
                : "<null>",
            static_cast<void *>(semantic_instantiation),
            static_cast<void *>(
                semantic_instantiation != nullptr
                    ? semantic_instantiation->get_templateDeclaration()
                    : nullptr),
            semantic_instantiation != nullptr
                ? semantic_instantiation->get_templateArguments().size()
                : 0);
    ROSE_ABORT();
  }
  const clang::AsmLabelAttr *local_asm_label =
      readClangApiValueDefined([&]() -> const clang::AsmLabelAttr * {
        const clang::AsmLabelAttr *result = nullptr;
        for (const clang::AsmLabelAttr *attr :
             var_decl->specific_attrs<clang::AsmLabelAttr>()) {
          if (attr == nullptr || attr->isInherited()) {
            continue;
          }
          if (result != nullptr) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[variable-asm-label]: variable=%s "
                    "has multiple local asm labels\n",
                    var_decl->getQualifiedNameAsString().c_str());
            ROSE_ABORT();
          }
          result = attr;
        }
        return result;
      });
  if (local_asm_label != nullptr) {
    const std::string asm_label = readClangApiValueDefined(
        [&]() { return local_asm_label->getLabel().str(); });
    if (asm_label.empty()) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-asm-label]: variable=%s has "
              "an empty asm label\n",
              var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }
    init_name->set_register_name_string(asm_label);
  }
  if (written_type_spells_elaborated_keyword) {
    init_name->set_type_elaboration_required(true);
    init_name->set_type_elaboration_required_for_type(true);
  }
  preserveExplicitInitializedNameTypeQualifier(
      init_name, written_type_qualifier_loc, p_compiler_instance,
      variable_owns_lexical_source_surface);
  publishUnqualifiedElaboratedTagQualification(
      init_name, written_type_spells_elaborated_tag_keyword,
      written_type_qualifier_loc, written_variable_tag_decl, "VisitVarDecl");
  if (implicit_anonymous_aggregate_var) {
    init_name->set_prev_decl_item(nullptr);
  }
  SgDeclarationGroupStatement *exact_source_group =
      isSgDeclarationGroupStatement(sg_var_decl->get_parent());
  const bool pending_for_init_group =
      exact_source_group != nullptr &&
      require_exact_pending_for_init(exact_source_group->get_scope());
  const bool pending_for_init_owner =
      exact_source_group == nullptr &&
      require_exact_pending_for_init(pending_for_init_scope);
  SgScopeStatement *exact_semantic_scope = init_name->get_scope();
  SgScopeStatement *exact_lexical_scope =
      semantic_static_member_instantiation ? exact_semantic_scope
      : exact_source_group != nullptr      ? exact_source_group->get_scope()
      : pending_for_init_owner             ? pending_for_init_scope
                               : isSgScopeStatement(sg_var_decl->get_parent());
  const bool pending_for_init_declaration =
      pending_for_init_owner || pending_for_init_group;
  SgScopeStatement *exact_pending_for_init_scope =
      pending_for_init_owner   ? pending_for_init_scope
      : pending_for_init_group ? exact_source_group->get_scope()
                               : nullptr;
  const auto has_exact_init_capture_auxiliary_owner = [&]() -> bool {
    SgAuxiliaryDeclarationList *current_owner =
        isSgAuxiliaryDeclarationList(sg_var_decl->get_parent());
    return var_is_init_capture && exact_source_group == nullptr &&
           !pending_for_init_declaration && source_group_owner == nullptr &&
           current_owner != nullptr && exact_semantic_scope != nullptr &&
           current_owner->get_parent() == exact_semantic_scope &&
           exact_semantic_scope->get_auxiliary_declarations() ==
               current_owner &&
           std::count(current_owner->get_declarations().begin(),
                      current_owner->get_declarations().end(),
                      sg_var_decl) == 1 &&
           sg_var_decl->get_scope() == exact_semantic_scope &&
           !exact_semantic_scope->statementExistsInScope(sg_var_decl);
  };
  const auto has_exact_static_instantiation_auxiliary_owner = [&]() -> bool {
    SgAuxiliaryDeclarationList *current_owner =
        isSgAuxiliaryDeclarationList(sg_var_decl->get_parent());
    return semantic_static_member_instantiation &&
           exact_source_group == nullptr && !pending_for_init_declaration &&
           source_group_owner == nullptr && current_owner != nullptr &&
           exact_semantic_scope != nullptr &&
           current_owner->get_parent() == exact_semantic_scope &&
           exact_semantic_scope->get_auxiliary_declarations() ==
               current_owner &&
           std::count(current_owner->get_declarations().begin(),
                      current_owner->get_declarations().end(),
                      sg_var_decl) == 1 &&
           sg_var_decl->get_scope() == exact_semantic_scope &&
           !exact_semantic_scope->statementExistsInScope(sg_var_decl);
  };
  const bool exact_structural_owner =
      var_is_init_capture ? has_exact_init_capture_auxiliary_owner()
      : semantic_static_member_instantiation
          ? has_exact_static_instantiation_auxiliary_owner()
      : pending_for_init_owner ? sg_var_decl->get_parent() == nullptr
      : exact_source_group == nullptr
          ? is_decl_attached_to_scope_child_list(
                p_decl_attachment_session, exact_lexical_scope, sg_var_decl)
          : exact_source_group == source_group_owner &&
                exact_source_group->get_parent() == nullptr &&
                std::count(exact_source_group->get_declarations().begin(),
                           exact_source_group->get_declarations().end(),
                           sg_var_decl) == 1 &&
                (pending_for_init_group ||
                 exact_lexical_declaration_group_reference_count(
                     exact_lexical_scope, sg_var_decl) == 0);
  if (exact_semantic_scope == nullptr ||
      (!var_is_init_capture && exact_lexical_scope == nullptr) ||
      (!var_is_init_capture && !pending_for_init_declaration &&
       sg_var_decl->get_scope() != exact_lexical_scope) ||
      !exact_structural_owner) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[variable-owner]: variable=%s did not "
            "preserve its respective exact structural and semantic owners\n",
            name.getString().c_str());
    ROSE_ABORT();
  }
  if (isStaticDataMember && exact_semantic_scope != static_member_owner_scope) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[semantic-static-member-owner]: "
            "variable=%s was not constructed in its exact class-definition "
            "scope\n",
            name.getString().c_str());
    ROSE_ABORT();
  }
  if (!isStaticDataMember && var_is_file_var_decl &&
      normalizeNamespaceScope(exact_semantic_scope) !=
          normalizeNamespaceScope(
              resolveScopeFromDeclContext(defined_var_decl_context()))) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[variable-semantic-owner]: file variable=%s "
            "was not constructed in its exact Clang declaration context\n",
            name.getString().c_str());
    ROSE_ABORT();
  }
  if (previous_variable_decl == nullptr) {
    if (!implicit_anonymous_aggregate_var &&
        init_name->get_prev_decl_item() != nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-redeclaration]: first Clang "
              "declaration of variable=%s acquired a predecessor=%p outside "
              "its exact Clang redeclaration chain\n",
              name.getString().c_str(),
              static_cast<void *>(init_name->get_prev_decl_item()));
      ROSE_ABORT();
    }
  } else if (init_name->get_prev_decl_item() != exact_previous_init) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[variable-redeclaration]: variable=%s "
            "does not reference its exact Clang predecessor\n",
            name.getString().c_str());
    ROSE_ABORT();
  }
  SgVariableSymbol *exact_variable_family_symbol = nullptr;
  std::set<SgInitializedName *> exact_variable_family;
  for (SgInitializedName *candidate = init_name; candidate != nullptr;
       candidate = candidate->get_prev_decl_item()) {
    if (!exact_variable_family.insert(candidate).second) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-declaration-symbol]: "
              "variable=%s has a cyclic exact redeclaration family\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    SgSymbol *candidate_symbol =
        exact_semantic_scope->find_symbol_from_declaration(candidate);
    if (candidate_symbol == nullptr) {
      continue;
    }
    SgVariableSymbol *candidate_variable_symbol =
        isSgVariableSymbol(candidate_symbol);
    if (candidate_variable_symbol == nullptr ||
        (exact_variable_family_symbol != nullptr &&
         exact_variable_family_symbol != candidate_variable_symbol)) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-declaration-symbol]: "
              "variable=%s has conflicting exact redeclaration symbols\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    exact_variable_family_symbol = candidate_variable_symbol;
  }
  if (var_decl->getIdentifier() != nullptr &&
      exact_variable_family_symbol == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[variable-declaration-symbol]: variable=%s "
            "has no exact symbol in its semantic scope\n",
            name.getString().c_str());
    ROSE_ABORT();
  }
  if (var_init_style == clang::VarDecl::ListInit) {
    init_name->set_is_braced_initialized(true);
    if (!var_is_direct_init) {
      init_name->set_using_assignment_copy_constructor_syntax(true);
    }
  }
  // CLANG FRONTEND FIX: Set initializer parent to SgInitializedName
  // The initializer is a child of the SgInitializedName, not the
  // SgVariableDeclaration
  if (init != nullptr) {
    init->set_parent(init_name);
    if (init_name->get_initializer() != init ||
        init->get_parent() != init_name) {
      std::cerr
          << "REX_FRONTEND_INVARIANT[variable-initializer-owner]: variable="
          << name << " initializer is not exactly owned by its initialized name"
          << std::endl;
      ROSE_ABORT();
    }
    if (SgAssignInitializer *assign_initializer = isSgAssignInitializer(init)) {
      SgExpression *operand = assign_initializer->get_operand_i();
      if (operand == nullptr || operand->get_parent() != assign_initializer) {
        std::cerr
            << "REX_FRONTEND_INVARIANT[assignment-initializer-operand]: "
               "variable="
            << name
            << " has no exact directly owned assignment-initializer operand"
            << std::endl;
        ROSE_ABORT();
      }
    }
  }

  if (instantiated_static_member_pattern) {
    setSynthesizedFileInfo(init_name);
  } else {
    ASSERT_not_null(p_compiler_instance);
    clang::SourceRange variable_lexical_range = preferredDeclSourceRange(
        var_decl, sg_var_decl, &p_compiler_instance->getSourceManager());
    if (exact_source_group != nullptr) {
      clang::SourceLocation declarator_begin =
          readClangApiValueDefined([&]() { return var_decl->getLocation(); });
      clang::SourceLocation declarator_end = variable_lexical_range.getEnd();
      clang::SourceManager &source_manager =
          p_compiler_instance->getSourceManager();
      clang::SourceLocation physical_begin = source_manager.getFileLoc(
          source_manager.getExpansionLoc(declarator_begin));
      clang::SourceLocation physical_end = source_manager.getFileLoc(
          source_manager.getExpansionLoc(declarator_end));
      if (declarator_begin.isInvalid() || declarator_end.isInvalid() ||
          physical_begin.isInvalid() || physical_end.isInvalid() ||
          source_manager.getFileID(physical_begin) !=
              source_manager.getFileID(physical_end) ||
          source_manager.isBeforeInTranslationUnit(physical_end,
                                                   physical_begin)) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[declaration-group-declarator-range]: "
                "variable=%s has no exact single-file initialized-name "
                "occurrence\n",
                name.getString().c_str());
        ROSE_ABORT();
      }
      variable_lexical_range =
          clang::SourceRange(declarator_begin, declarator_end);
    }
    applySourceRange(init_name, variable_lexical_range);
  }

  SgVariableDefinition *var_def = init_name->get_definition();
  if (var_def == nullptr || init_name->get_declptr() != sg_var_decl ||
      var_def->get_parent() != init_name ||
      var_def->get_vardefn() != init_name) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[variable-definition-owner]: variable=%s "
            "was constructed without an exact SgVariableDefinition owner\n",
            init_name->get_name().str());
    ROSE_ABORT();
  }
  if (instantiated_static_member_pattern) {
    setSynthesizedFileInfo(var_def);
  } else {
    const clang::SourceRange variable_lexical_range = preferredDeclSourceRange(
        var_decl, sg_var_decl, &p_compiler_instance->getSourceManager());
    applySourceRange(var_def, variable_lexical_range);
  }

  // Pei-Hung (06/16/22) added "extern" modifier
  bool hasExternalStorage = var_decl->hasExternalStorage();
  if (hasExternalStorage) {
    sg_var_decl->get_declarationModifier().get_storageModifier().setExtern();
  }

  // Pei-Hung (06/16/22) added "static" modifier
  bool shouldSetStatic = (var_decl->getStorageClass() == clang::SC_Static) &&
                         !isOutOfLineStaticMember;
  if (shouldSetStatic) {
    sg_var_decl->get_declarationModifier().get_storageModifier().setStatic();
  }
  // Pei-Hung (03/14/23) added "static" modifier for data member
  if (isStaticDataMember) {
    // Pei-Hung (09/29/23) Only set for the first static data member
    // declaration (the in-class declaration).
    if (var_decl->getPreviousDecl() == nullptr) {
      sg_var_decl->get_declarationModifier().get_storageModifier().setStatic();
    }
  }

  switch (var_decl->getTSCSpec()) {
  case clang::TSCS_unspecified:
    break;
  case clang::TSCS___thread:
    sg_var_decl->get_declarationModifier()
        .get_storageModifier()
        .set_thread_local_storage(true);
    break;
  case clang::TSCS_thread_local:
  case clang::TSCS__Thread_local:
    sg_var_decl->set_is_thread_local(true);
    break;
  }

  if (!isembedded &&
      sg_var_decl->get_baseTypeDefiningDeclaration() != nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[embedded-base-owner]: non-embedded "
            "variable=%s acquired a base-type definition child\n",
            name.getString().c_str());
    ROSE_ABORT();
  }

  *node = sg_var_decl;

  bool visit_res = false;
  if (semantic_range_for_declaration) {
    if (p_synthesized_source_nodes.count(sg_var_decl) != 0 ||
        p_lexical_source_nodes.count(sg_var_decl) != 0) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[range-for-semantic-declaration]: "
              "variable=%s declaration shell already has lexical/semantic "
              "producer roles=%zu/%zu\n",
              name.getString().c_str(),
              p_lexical_source_nodes.count(sg_var_decl),
              p_synthesized_source_nodes.count(sg_var_decl));
      ROSE_ABORT();
    }
    for (SgNode *semantic_shell :
         {static_cast<SgNode *>(sg_var_decl), static_cast<SgNode *>(init_name),
          static_cast<SgNode *>(var_def)}) {
      if (semantic_shell == nullptr) {
        continue;
      }
      const size_t synthesized_roles =
          p_synthesized_source_nodes.count(semantic_shell);
      if (synthesized_roles == 0) {
        setSynthesizedFileInfo(semantic_shell);
      } else if (synthesized_roles != 1) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[range-for-semantic-declaration]: "
                "variable=%s shell=%p/%s has %zu synthesized producers\n",
                name.getString().c_str(), static_cast<void *>(semantic_shell),
                semantic_shell->class_name().c_str(), synthesized_roles);
        ROSE_ABORT();
      }
      mark_compiler_generated_frontend_specific(semantic_shell);
      validate_exact_semantic_function_provenance(
          semantic_shell,
          "VisitVarDecl:range-for-semantic-declaration-structure");
    }
    validate_semantic_provenance(
        sg_var_decl, false,
        "VisitVarDecl:range-for-semantic-declaration-shell");
    validate_semantic_provenance(
        init_name, false, "VisitVarDecl:range-for-semantic-initialized-name");
    validate_semantic_provenance(
        var_def, false, "VisitVarDecl:range-for-semantic-variable-definition");
    FinalizedDeclarationProvenanceGuard finalized_provenance_guard(
        p_declaration_with_finalized_provenance, sg_var_decl);
    visit_res = VisitDeclaratorDecl(var_decl, node) && res;
  } else {
    visit_res = VisitDeclaratorDecl(var_decl, node) && res;
  }
  if (visit_res && source_group_owner == nullptr) {
    // Capture the exact written/Sage type pair after the generic declaration
    // visitor has assigned its source range.  Translation-unit completion
    // validates the declaration's final structural output owner.  An active
    // declaration-group member is queued when its full group transaction
    // completes.
    if (clang::TypeSourceInfo *type_info =
            markClangTypeSourceInfoDefined(readClangApiValueDefined(
                [&]() { return var_decl->getTypeSourceInfo(); }))) {
      const std::string surface_name =
          name.getString().empty() ? "<anonymous-variable>" : name.getString();
      queueWrittenTypedefDependenciesForOutputSurface(
          readClangApiValueDefined([&]() { return type_info->getTypeLoc(); }),
          init_name->get_type(), sg_var_decl, "variable", surface_name);
    }
  }
  if (visit_res && p_compiler_instance != nullptr) {
    require_complete_file_info_provenance(sg_var_decl,
                                          "VisitVarDecl:declaration-file-info");
    require_complete_file_info_provenance(
        init_name, "VisitVarDecl:initialized-name-file-info");
    require_complete_file_info_provenance(var_def,
                                          "VisitVarDecl:definition-file-info");

    clang::SourceManager &sm = p_compiler_instance->getSourceManager();
    clang::SourceLocation loc = var_decl->getLocation();
    auto preserve_implicit_anonymous_aggregate =
        [&](clang::VarDecl *candidate) -> bool {
      if (candidate == nullptr || !candidate->isImplicit()) {
        return false;
      }

      clang::SourceLocation candidate_loc = candidate->getLocation();
      if (candidate_loc.isMacroID()) {
        candidate_loc = sm.getSpellingLoc(candidate_loc);
      }
      if (!candidate_loc.isValid()) {
        return false;
      }
      if (!sm.isWrittenInMainFile(candidate_loc) ||
          sm.isInSystemHeader(candidate_loc) ||
          sm.isWrittenInBuiltinFile(candidate_loc)) {
        return false;
      }

      clang::QualType candidate_type = candidate->getType();
      const clang::Type *type_ptr = candidate_type.getTypePtrOrNull();
      while (type_ptr != nullptr &&
             (typeHasElaboratedSpelling(type_ptr) ||
              llvm::isa<clang::AttributedType>(type_ptr) ||
              llvm::isa<clang::SubstTemplateTypeParmType>(type_ptr))) {
        if (typeHasElaboratedSpelling(type_ptr)) {
          candidate_type = candidate_type.getCanonicalType();
        } else if (const clang::AttributedType *attributed =
                       llvm::dyn_cast<clang::AttributedType>(type_ptr)) {
          candidate_type = attributed->getModifiedType();
        } else {
          candidate_type =
              llvm::cast<clang::SubstTemplateTypeParmType>(type_ptr)
                  ->getReplacementType();
        }
        type_ptr = candidate_type.getTypePtrOrNull();
      }

      const clang::RecordType *record_type =
          llvm::dyn_cast_or_null<clang::RecordType>(type_ptr);
      if (record_type == nullptr) {
        return false;
      }

      const clang::RecordDecl *record_decl = record_type->getDecl();
      return record_decl != nullptr && record_decl->isAnonymousStructOrUnion();
    };

    bool suppress_var =
        var_decl->isImplicit() || semantic_static_member_instantiation;
    if (suppress_var && preserve_implicit_anonymous_aggregate(var_decl)) {
      suppress_var = false;
    }
    if (suppress_var && name.getString().empty()) {
      suppress_var = false;
    }

    // Keep implicit variables only when they model source-level range-for
    // declarations. Other implicit VarDecls are compiler artifacts and should
    // remain suppressed to avoid injecting ghost members/declarations.
    if (suppress_var && !semantic_static_member_instantiation &&
        (var_decl->isCXXForRangeDecl() ||
         isSgRangeBasedForStatement(exact_pending_for_init_scope) != nullptr)) {
      suppress_var = false;
    }

    bool suppress_var_due_to_non_main_file = false;
    if (!suppress_var && !shouldKeepTextualHeaderDeclForUnparse(
                             var_decl, p_compiler_instance, p_sage_source_file,
                             p_sage_preprocessor_recorder)) {
      suppress_var_due_to_non_main_file =
          shouldSuppressDeclNotWrittenInMainFile(loc, sm);
      suppress_var = suppress_var_due_to_non_main_file;
    }
    auto static_member_parent_chain_is_hidden = [&]() -> bool {
      if (!isStaticDataMember) {
        return false;
      }

      // A source tag embedded in a declarator is deliberately detached until
      // that declarator atomically adopts it.  While its typed-owner
      // transaction is active, the record definition is nevertheless the
      // exact physical-output owner for every written member.  Treating the
      // temporary detached state as hidden moves those members into the
      // auxiliary semantic list and leaves an irreparably empty class by the
      // time the declarator publishes it.
      if (exact_typed_owner_static_member_source) {
        return false;
      }

      if (class_like_scope_is_visible_for_unparse(static_member_owner_scope)) {
        return false;
      }

      const clang::CXXRecordDecl *record_ctx =
          find_enclosing_cxx_record_decl(defined_var_decl_context());
      record_ctx = markClangSpecificDeclDefined(record_ctx);
      if (record_ctx == nullptr) {
        return false;
      }

      if (SgClassDefinition *class_def =
              isSgClassDefinition(static_member_owner_scope)) {
        if (class_definition_is_hidden_for_unparse(class_def)) {
          return true;
        }
      }

      auto check_record = [&](const clang::CXXRecordDecl *candidate) -> bool {
        if (candidate == nullptr) {
          return false;
        }
        SgClassDeclaration *mapped_decl =
            isSgClassDeclaration(lookupSgDeclarationForClangDecl(
                const_cast<clang::CXXRecordDecl *>(candidate),
                /*allow_on_demand=*/false));
        return class_declaration_chain_is_hidden_for_unparse(mapped_decl);
      };

      if (check_record(record_ctx)) {
        return true;
      }
      if (check_record(markClangSpecificDeclDefined(readClangApiValueDefined(
              [&]() { return record_ctx->getDefinition(); })))) {
        return true;
      }
      if (check_record(markClangSpecificDeclDefined(readClangApiValueDefined(
              [&]() { return record_ctx->getCanonicalDecl(); })))) {
        return true;
      }
      if (check_record(clangCXXRecordTemplateInstantiationPatternDefined(
              const_cast<clang::CXXRecordDecl *>(record_ctx)))) {
        return true;
      }
      if (clang::ClassTemplateDecl *templ =
              markClangSpecificDeclDefined(readClangApiValueDefined(
                  [&]() { return record_ctx->getDescribedClassTemplate(); }))) {
        if (check_record(markClangSpecificDeclDefined(readClangApiValueDefined(
                [&]() { return templ->getTemplatedDecl(); })))) {
          return true;
        }
      }

      for (const clang::DeclContext *ctx =
               markClangDeclContextObjectDefined(readClangApiValueDefined(
                   [&]() { return record_ctx->getParent(); }));
           ctx != nullptr;
           ctx = markClangDeclContextObjectDefined(
               readClangApiValueDefined([&]() { return ctx->getParent(); }))) {
        const clang::Decl *decl = llvm::dyn_cast_or_null<clang::Decl>(
            const_cast<clang::DeclContext *>(ctx));
        const auto *parent_record =
            llvm::dyn_cast_or_null<clang::CXXRecordDecl>(
                markClangDeclObjectDefinedByKind(
                    const_cast<clang::Decl *>(decl)));
        if (parent_record == nullptr) {
          continue;
        }

        if (check_record(parent_record) ||
            check_record(markClangSpecificDeclDefined(readClangApiValueDefined(
                [&]() { return parent_record->getDefinition(); }))) ||
            check_record(markClangSpecificDeclDefined(readClangApiValueDefined(
                [&]() { return parent_record->getCanonicalDecl(); }))) ||
            check_record(clangCXXRecordTemplateInstantiationPatternDefined(
                const_cast<clang::CXXRecordDecl *>(parent_record)))) {
          return true;
        }
        if (clang::ClassTemplateDecl *templ =
                markClangSpecificDeclDefined(readClangApiValueDefined([&]() {
                  return parent_record->getDescribedClassTemplate();
                }))) {
          if (check_record(
                  markClangSpecificDeclDefined(readClangApiValueDefined(
                      [&]() { return templ->getTemplatedDecl(); })))) {
            return true;
          }
        }
      }

      return false;
    };
    auto is_source_visible_static_member_specialization = [&]() -> bool {
      if (!isStaticDataMember || !isOutOfLineStaticMember ||
          var_specialization_kind != clang::TSK_ExplicitSpecialization) {
        return false;
      }

      clang::SourceLocation member_loc =
          readClangApiValueDefined([&]() { return var_decl->getLocation(); });
      if (member_loc.isMacroID()) {
        member_loc = sm.getSpellingLoc(member_loc);
      }
      if (!member_loc.isValid()) {
        return false;
      }

      if (shouldKeepTextualHeaderDeclForUnparse(var_decl, p_compiler_instance,
                                                p_sage_source_file,
                                                p_sage_preprocessor_recorder)) {
        return true;
      }

      return !shouldSuppressDeclNotWrittenInMainFile(member_loc, sm);
    };

    if (suppress_var && !semantic_static_member_instantiation &&
        !readClangApiValueDefined([&]() { return var_decl->isImplicit(); }) &&
        isStaticDataMember && !static_member_parent_chain_is_hidden()) {
      if (static_member_owner_scope == SageBuilder::topScopeStack()) {
        suppress_var = false;
      } else if (class_like_scope_is_visible_for_unparse(
                     static_member_owner_scope)) {
        suppress_var = false;
      }
    }

    SgDeclarationGroupStatement *suppressed_source_group =
        isSgDeclarationGroupStatement(sg_var_decl->get_parent());
    if (var_is_init_capture && !has_exact_init_capture_auxiliary_owner()) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[lambda-capture-suppression]: "
              "init-capture '%s' lost its exact typed auxiliary owner before "
              "suppression policy\n",
              name.str());
      ROSE_ABORT();
    }
    // Suppression policy needs the scope that owns the declaration's current
    // structural mode.  An init-capture's direct parent is the typed auxiliary
    // container, so consume the already-proven semantic scope behind that
    // container instead of pretending the declaration has a lexical edge.
    SgScopeStatement *suppression_structural_scope =
        var_is_init_capture || semantic_static_member_instantiation
            ? exact_semantic_scope
        : suppressed_source_group != nullptr
            ? suppressed_source_group->get_scope()
        : exact_pending_for_init_scope != nullptr
            ? exact_pending_for_init_scope
            : isSgScopeStatement(sg_var_decl->get_parent());
    if (suppressed_source_group != nullptr &&
        (suppressed_source_group != source_group_owner ||
         suppressed_source_group->get_parent() != nullptr ||
         std::count(suppressed_source_group->get_declarations().begin(),
                    suppressed_source_group->get_declarations().end(),
                    sg_var_decl) != 1 ||
         suppression_structural_scope == nullptr ||
         (!pending_for_init_group &&
          suppression_structural_scope->statementExistsInScope(sg_var_decl)))) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-source-group-owner]: "
              "variable=%s lost its exact construction-time declaration "
              "group before suppression policy\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    if (suppression_structural_scope == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-structural-owner]: variable=%s "
              "has no exact structural scope before suppression\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    const clang::SourceRange variable_source_range =
        clangVarDeclSourceRangeDefined(var_decl);
    const bool preserve_suppressed_header_lexical_surface =
        suppress_var && suppress_var_due_to_non_main_file &&
        !readClangApiValueDefined([&]() { return var_decl->isImplicit(); }) &&
        !isStaticDataMember && !var_is_init_capture &&
        variable_source_range.isValid() &&
        declaration_has_real_source(sg_var_decl) &&
        variable_preserves_eager_non_main_leaf_surface &&
        (isSgGlobal(suppression_structural_scope) != nullptr ||
         isSgNamespaceDefinitionStatement(suppression_structural_scope) !=
             nullptr);
    const auto has_exact_suppressed_local_lexical_owner = [&]() {
      if (exact_pending_for_init_scope != nullptr) {
        if (!require_exact_pending_for_init(exact_pending_for_init_scope) ||
            suppression_structural_scope != exact_pending_for_init_scope ||
            init_name->get_scope() != exact_pending_for_init_scope) {
          return false;
        }
        if (suppressed_source_group != nullptr) {
          return suppressed_source_group == source_group_owner &&
                 suppressed_source_group->get_parent() == nullptr &&
                 sg_var_decl->get_parent() == suppressed_source_group &&
                 std::count(suppressed_source_group->get_declarations().begin(),
                            suppressed_source_group->get_declarations().end(),
                            sg_var_decl) == 1;
        }
        return sg_var_decl->get_parent() == nullptr;
      }
      if (!scope_supports_statement_list(suppression_structural_scope) ||
          sg_var_decl->get_scope() != suppression_structural_scope) {
        return false;
      }
      if (suppressed_source_group != nullptr) {
        return suppressed_source_group == source_group_owner &&
               sg_var_decl->get_parent() == suppressed_source_group &&
               suppressed_source_group->get_scope() ==
                   suppression_structural_scope &&
               suppressed_source_group->get_parent() == nullptr &&
               !suppression_structural_scope->statementExistsInScope(
                   suppressed_source_group) &&
               std::count(suppressed_source_group->get_declarations().begin(),
                          suppressed_source_group->get_declarations().end(),
                          sg_var_decl) == 1;
      }
      return sg_var_decl->get_parent() == suppression_structural_scope &&
             is_decl_attached_to_scope_child_list(p_decl_attachment_session,
                                                  suppression_structural_scope,
                                                  sg_var_decl);
    };
    const bool semantic_function_body_declaration =
        p_semantic_function_body_traversal_depth != 0;
    const bool exact_semantic_function_body_provenance =
        semantic_function_body_declaration &&
        p_synthesized_source_nodes.count(sg_var_decl) == 1 &&
        p_lexical_source_nodes.count(sg_var_decl) == 0;
    if (semantic_function_body_declaration &&
        !exact_semantic_function_body_provenance) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[semantic-function-local-owner]: "
              "variable=%s entered suppression without one exact semantic "
              "provenance role\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    const bool preserve_suppressed_local_lexical_surface =
        suppress_var && suppress_var_due_to_non_main_file &&
        !readClangApiValueDefined([&]() { return var_decl->isImplicit(); }) &&
        !isStaticDataMember && !var_is_init_capture &&
        variable_source_range.isValid() &&
        (declaration_has_real_source(sg_var_decl) ||
         exact_semantic_function_body_provenance) &&
        has_exact_suppressed_local_lexical_owner();
    const bool preserve_suppressed_lexical_surface =
        preserve_suppressed_header_lexical_surface ||
        preserve_suppressed_local_lexical_surface;

    auto apply_variable_semantic_provenance = [&](bool compiler_generated,
                                                  const char *context) {
      auto classify = [&](SgNode *semantic_node) {
        if (semantic_node == nullptr) {
          return;
        }
        if (compiler_generated) {
          const size_t lexical_roles =
              p_lexical_source_nodes.count(semantic_node);
          const size_t synthesized_roles =
              p_synthesized_source_nodes.count(semantic_node);
          if (lexical_roles > 1 || synthesized_roles > 1 ||
              (lexical_roles != 0 && synthesized_roles != 0)) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[variable-semantic-provenance]: "
                    "context=%s node=%p/%s has ambiguous lexical/semantic "
                    "producer roles=%zu/%zu\n",
                    context, static_cast<void *>(semantic_node),
                    semantic_node->class_name().c_str(), lexical_roles,
                    synthesized_roles);
            ROSE_ABORT();
          }
          if (synthesized_roles == 0) {
            // Suppression has now selected the auxiliary semantic
            // declaration as a non-source product.  Replace the provisional
            // lexical coordinates installed by the generic declarator
            // visitor with one exact synthesized producer before publishing
            // that structural role.
            if (lexical_roles == 1) {
              p_lexical_source_nodes.erase(semantic_node);
            }
            mark_compiler_generated_frontend_specific(semantic_node);
            setSynthesizedFileInfo(semantic_node);
          } else {
            mark_compiler_generated_frontend_specific(semantic_node);
          }
        }
      };

      classify(sg_var_decl);
      classify(sg_var_decl->get_definition());
      for (SgInitializedName *initialized_name : sg_var_decl->get_variables()) {
        classify(initialized_name);
        // The hidden `auto &&__range` declaration, initialized name, and
        // variable definition are semantic range-for scaffolding.  Its
        // initializer is the user's one written range expression and is
        // subsequently owned by the typed SgRangeBasedForStatement surface.
        // Classifying that initializer as part of the suppressed declaration
        // shell creates contradictory lexical/compiler-generated provenance.
        if (!semantic_range_for_declaration) {
          classify(initialized_name != nullptr
                       ? initialized_name->get_initializer()
                       : nullptr);
        }
      }
      validate_semantic_provenance(sg_var_decl, compiler_generated, context);
    };

    if (suppress_var) {
      apply_variable_semantic_provenance(
          !preserve_suppressed_lexical_surface,
          "VisitVarDecl:source-provenance-policy");
    }

    if (semantic_static_member_instantiation && !suppress_var) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[semantic-static-member-owner]: "
              "instantiation=%s escaped construction-time semantic "
              "suppression\n",
              var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }

    if (!suppress_var && static_member_parent_chain_is_hidden() &&
        !is_source_visible_static_member_specialization()) {
      suppress_var = true;
      apply_variable_semantic_provenance(
          true, "VisitVarDecl:hidden-static-member-owner");
    }

    if (suppress_var && isStaticDataMember) {
      if (static_member_owner_scope == nullptr ||
          !is_class_like_scope(static_member_owner_scope)) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[semantic-static-member-owner]: "
                "variable=%s clang-decl=%p has no exact class-definition "
                "scope\n",
                name.getString().c_str(), static_cast<void *>(var_decl));
        ROSE_ABORT();
      }

      if (isSgAuxiliaryDeclarationList(sg_var_decl->get_parent()) != nullptr) {
        set_declaration_scope_preserving_auxiliary_ownership(
            sg_var_decl, static_member_owner_scope,
            "VisitVarDecl:semantic-static-member");
      } else {
        if (SgScopeStatement *current_parent =
                isSgScopeStatement(sg_var_decl->get_parent())) {
          detach_decl_from_scope_child_list(p_decl_attachment_session,
                                            sg_var_decl, current_parent);
          sg_var_decl->set_parent(nullptr);
        } else if (sg_var_decl->get_parent() != nullptr) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[semantic-static-member-owner]: "
                  "variable=%s declaration=%p has non-scope structural "
                  "owner=%s\n",
                  name.getString().c_str(), static_cast<void *>(sg_var_decl),
                  sg_var_decl->get_parent()->class_name().c_str());
          ROSE_ABORT();
        }
        for (SgInitializedName *semantic_name : sg_var_decl->get_variables()) {
          if (semantic_name == nullptr ||
              semantic_name->get_scope() != static_member_owner_scope) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[semantic-static-member-owner]: "
                    "variable=%s lost its exact initialized-name scope before "
                    "auxiliary publication\n",
                    name.getString().c_str());
            ROSE_ABORT();
          }
        }
        SageBuilder::attachAuxiliaryDeclaration(static_member_owner_scope,
                                                sg_var_decl);
      }
    }

    if (suppress_var && !isStaticDataMember && !var_is_init_capture &&
        !preserve_suppressed_lexical_surface) {
      detach_decl_from_known_scope_child_lists(p_decl_attachment_session,
                                               sg_var_decl);
      publish_semantic_variable_owner(p_decl_attachment_session, sg_var_decl,
                                      "VisitVarDecl:suppressed-variable");
    }

    if (var_is_init_capture &&
        (!has_exact_init_capture_auxiliary_owner() ||
         suppression_structural_scope != exact_semantic_scope ||
         isSgBasicBlock(suppression_structural_scope) == nullptr)) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[lambda-capture-publication]: "
              "init-capture '%s' lost its exact typed auxiliary owner before "
              "source-publication policy\n",
              name.str());
      ROSE_ABORT();
    }

    // Routing an init-capture through this transaction would replace its typed
    // auxiliary edge with a contradictory statement-list edge.
    if ((!suppress_var || preserve_suppressed_lexical_surface) &&
        !var_is_init_capture) {
      SgScopeStatement *decl_scope = preserve_suppressed_lexical_surface
                                         ? suppression_structural_scope
                                     : exact_pending_for_init_scope != nullptr
                                         ? exact_pending_for_init_scope
                                         : sg_var_decl->get_scope();
      if (decl_scope == nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-lexical-owner]: variable=%s "
                "has no exact lexical scope before publication\n",
                name.getString().c_str());
        ROSE_ABORT();
      }
      const bool has_source_group_owner = source_group_owner != nullptr;
      if (has_source_group_owner) {
        if (sg_var_decl->get_parent() != source_group_owner ||
            source_group_owner->get_parent() != nullptr ||
            source_group_owner->get_scope() != suppression_structural_scope ||
            std::count(source_group_owner->get_declarations().begin(),
                       source_group_owner->get_declarations().end(),
                       sg_var_decl) != 1 ||
            (!pending_for_init_group &&
             (suppression_structural_scope->statementExistsInScope(
                  source_group_owner) ||
              suppression_structural_scope->statementExistsInScope(
                  sg_var_decl)))) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[variable-source-group-owner]: "
                  "variable=%s cannot publish before its exact atomic "
                  "declaration group is complete\n",
                  name.getString().c_str());
          ROSE_ABORT();
        }
      } else {
        if (exact_pending_for_init_scope != nullptr) {
          if (!require_exact_pending_for_init(exact_pending_for_init_scope) ||
              sg_var_decl->get_parent() != nullptr ||
              init_name->get_scope() != exact_pending_for_init_scope) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[typed-declaration-transaction]: "
                    "variable=%s lost its detached typed statement ownership "
                    "before attachment\n",
                    name.getString().c_str());
            ROSE_ABORT();
          }
        } else {
          ensureDeclInScopeChildList(sg_var_decl, decl_scope, "VisitVarDecl");
        }
      }
      if (preserve_suppressed_header_lexical_surface) {
        SgDeclarationStatementPtrList *declarations =
            get_scope_declaration_list(decl_scope);
        const bool exact_lexical_ownership =
            has_source_group_owner
                ? source_group_owner->get_scope() == decl_scope &&
                      source_group_owner->get_parent() == nullptr &&
                      sg_var_decl->get_parent() == source_group_owner &&
                      std::count(source_group_owner->get_declarations().begin(),
                                 source_group_owner->get_declarations().end(),
                                 sg_var_decl) == 1
                : declarations != nullptr &&
                      sg_var_decl->get_parent() == decl_scope &&
                      sg_var_decl->get_scope() == decl_scope &&
                      std::count(declarations->begin(), declarations->end(),
                                 sg_var_decl) == 1;
        auto valid_suppressed_source_info =
            [](const Sg_File_Info *file_info) -> bool {
          return has_real_source_file_info(file_info);
        };
        if (!exact_lexical_ownership ||
            !valid_suppressed_source_info(sg_var_decl->get_file_info()) ||
            !valid_suppressed_source_info(
                sg_var_decl->get_startOfConstruct()) ||
            !valid_suppressed_source_info(sg_var_decl->get_endOfConstruct())) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[suppressed-header-variable-"
                  "owner]: variable=%s declaration=%p did not retain one "
                  "direct lexical owner with real suppressed source "
                  "classification\n",
                  name.getString().c_str(), static_cast<void *>(sg_var_decl));
          ROSE_ABORT();
        }
      }
      if (preserve_suppressed_local_lexical_surface) {
        const bool exact_lexical_ownership =
            has_exact_suppressed_local_lexical_owner();
        const bool exact_source_provenance =
            exact_semantic_function_body_provenance ||
            (has_real_source_file_info(sg_var_decl->get_file_info()) &&
             has_real_source_file_info(sg_var_decl->get_startOfConstruct()) &&
             has_real_source_file_info(sg_var_decl->get_endOfConstruct()));
        if (!exact_lexical_ownership || !exact_source_provenance) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[suppressed-local-variable-owner]: "
                  "variable=%s declaration=%p did not retain one exact "
                  "lexical owner with its exact source or semantic "
                  "classification\n",
                  name.getString().c_str(), static_cast<void *>(sg_var_decl));
          ROSE_ABORT();
        }
      }
    }
  }
  if (var_is_init_capture &&
      (!has_exact_init_capture_auxiliary_owner() ||
       isSgBasicBlock(exact_semantic_scope) == nullptr)) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[lambda-capture-owner]: init-capture "
            "'%s' lacks one exact typed auxiliary owner\n",
            name.str());
    ROSE_ABORT();
  }
  return visit_res;
}

bool ClangToSageTranslator::VisitDecompositionDecl(
    clang::DecompositionDecl *decomposition_decl, SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitDecompositionDecl" << std::endl;
#endif
  bool res = true;

  bool visit_res = VisitVarDecl(decomposition_decl, node);

  std::vector<StructuredBindingComponent> components;
  for (clang::BindingDecl *binding_decl : decomposition_decl->bindings()) {
    StructuredBindingComponent component;
    component.binding_decl = binding_decl;

    if (binding_decl != nullptr) {
      SgVariableDeclaration *binding_var_decl =
          isSgVariableDeclaration(Traverse(binding_decl));
      ROSE_ASSERT(binding_var_decl != nullptr);
      ROSE_ASSERT(!binding_var_decl->get_variables().empty());

      if (!binding_decl->getNameAsString().empty()) {
        component.initialized_name = binding_var_decl->get_variables().front();
      }
    }

    components.push_back(component);
  }

  if (SgVariableDeclaration *sg_var_decl = isSgVariableDeclaration(*node)) {
    if (!sg_var_decl->get_variables().empty()) {
      SgInitializedName *init_name = sg_var_decl->get_variables().front();
      SgExprListExp *pattern = buildStructuredBindingPattern(
          decomposition_decl, components, init_name->get_scope(),
          p_semantic_function_body_traversal_depth != 0);
      ASSERT_not_null(pattern);
      ASSERT_require(pattern->get_parent() == nullptr);

      const clang::SourceLocation left_square = readClangApiValueDefined(
          [&]() { return decomposition_decl->getLocation(); });
      const size_t left_square_index = static_cast<size_t>(
          requireExpandedTokenSourceOrder(
              left_square, "VisitDecompositionDecl:left-square") -
          1);
      if (left_square_index >= p_expanded_tokens.size() ||
          p_expanded_tokens[left_square_index].kind != clang::tok::l_square) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[structured-binding-source]: "
                "decomposition=%p location does not identify one exact "
                "expanded left-square token\n",
                static_cast<void *>(decomposition_decl));
        ROSE_ABORT();
      }

      size_t right_square_index = p_expanded_tokens.size();
      unsigned int square_depth = 0;
      for (size_t index = left_square_index; index < p_expanded_tokens.size();
           ++index) {
        const clang::tok::TokenKind kind = p_expanded_tokens[index].kind;
        if (kind == clang::tok::l_square) {
          ++square_depth;
        } else if (kind == clang::tok::r_square) {
          if (square_depth == 0) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[structured-binding-source]: "
                    "decomposition=%p has an unmatched expanded "
                    "right-square token\n",
                    static_cast<void *>(decomposition_decl));
            ROSE_ABORT();
          }
          --square_depth;
          if (square_depth == 0) {
            right_square_index = index;
            break;
          }
        }
      }
      if (right_square_index == p_expanded_tokens.size() ||
          !p_expanded_tokens[right_square_index].location.isValid()) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[structured-binding-source]: "
                "decomposition=%p has no exact expanded right-square token\n",
                static_cast<void *>(decomposition_decl));
        ROSE_ABORT();
      }

      SgExpressionPtrList &pattern_elements = pattern->get_expressions();
      if (pattern_elements.size() != components.size()) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[structured-binding-source]: "
                "decomposition=%p owns %zu Clang bindings but %zu Sage "
                "pattern elements\n",
                static_cast<void *>(decomposition_decl), components.size(),
                pattern_elements.size());
        ROSE_ABORT();
      }
      for (size_t index = 0; index < components.size(); ++index) {
        const clang::BindingDecl *binding = components[index].binding_decl;
        SgExpression *element = pattern_elements[index];
        if (binding == nullptr || element == nullptr) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[structured-binding-source]: "
                  "decomposition=%p has no exact binding/element pair at "
                  "index=%zu\n",
                  static_cast<void *>(decomposition_decl), index);
          ROSE_ABORT();
        }
        applySourceRange(element, binding->getSourceRange());
      }
      applySourceRange(
          pattern,
          clang::SourceRange(p_expanded_tokens[left_square_index].location,
                             p_expanded_tokens[right_square_index].location));
      init_name->set_structured_binding_pattern(pattern);
      pattern->set_parent(init_name);
    }
  }

  return visit_res && res;
}

bool ClangToSageTranslator::VisitImplicitParamDecl(
    clang::ImplicitParamDecl *implicit_param_decl, SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitImplicitParamDecl" << std::endl;
#endif
  bool res = true;

  // ROOT CAUSE FIX: Allow delegation to work - disabled FAIL_TODO
  // ROSE_ASSERT(FAIL_TODO == 0); // TODO

  return VisitVarDecl(implicit_param_decl, node) && res;
}

bool ClangToSageTranslator::VisitParmVarDecl(clang::ParmVarDecl *param_var_decl,
                                             SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitParmVarDecl" << std::endl;
#endif
  bool res = true;

  param_var_decl = llvm::cast<clang::ParmVarDecl>(
      markClangDeclObjectDefinedByKind(param_var_decl));
  markClangParmVarDeclDefaultArgSourceRangeStorageDefined(param_var_decl);
  SgName name(param_var_decl->getNameAsString());
  clang::DeclContext *owning_context =
      markClangDeclContextObjectDefined(param_var_decl->getDeclContext());
  clang::FunctionDecl *owning_function =
      owning_context != nullptr
          ? llvm::dyn_cast_or_null<clang::FunctionDecl>(
                markClangDeclObjectDefinedByKind(
                    clang::Decl::castFromDeclContext(owning_context)))
          : nullptr;
  const std::size_t construction_frame_index =
      p_function_parameter_construction_stack.empty()
          ? std::numeric_limits<std::size_t>::max()
          : p_function_parameter_construction_stack.size() - 1;
  const FunctionParameterConstructionFrame *construction_frame =
      construction_frame_index != std::numeric_limits<std::size_t>::max()
          ? &p_function_parameter_construction_stack[construction_frame_index]
          : nullptr;
  const clang::FunctionDecl *active_signature_declaration =
      construction_frame != nullptr ? construction_frame->declaration : nullptr;
  const clang::FunctionDecl *active_parameter_owner =
      construction_frame != nullptr ? construction_frame->parameter_owner
                                    : nullptr;
  const bool active_signature_is_semantic =
      construction_frame != nullptr && construction_frame->semantic;
  const bool active_signature_is_explicit_template_id_type_use =
      construction_frame != nullptr &&
      construction_frame->explicit_template_id_type_use;
  SgDeclarationScope *active_signature_scope =
      construction_frame != nullptr ? construction_frame->declaration_scope
                                    : nullptr;
  const bool exact_active_function_parameter =
      construction_frame != nullptr && owning_function != nullptr &&
      (owning_function == active_signature_declaration ||
       owning_function == active_parameter_owner);
  const std::size_t requires_frame_index =
      p_requires_parameter_construction_stack.empty()
          ? std::numeric_limits<std::size_t>::max()
          : p_requires_parameter_construction_stack.size() - 1;
  const RequiresParameterConstructionFrame *requires_frame =
      requires_frame_index != std::numeric_limits<std::size_t>::max()
          ? &p_requires_parameter_construction_stack[requires_frame_index]
          : nullptr;
  const clang::RequiresExpr *active_requires_expression =
      requires_frame != nullptr ? requires_frame->expression : nullptr;
  SgFunctionParameterScope *active_requires_scope =
      requires_frame != nullptr ? requires_frame->scope : nullptr;
  clang::RequiresExprBodyDecl *active_requires_body =
      active_requires_expression != nullptr ? readClangApiValueDefined([&]() {
        return active_requires_expression->getBody();
      })
                                            : nullptr;
  const bool exact_active_requires_parameter =
      requires_frame != nullptr && owning_function == nullptr &&
      owning_context != nullptr && active_requires_body != nullptr &&
      owning_context == clang::RequiresExprBodyDecl::castToDeclContext(
                            active_requires_body) &&
      requires_frame->parameters.count(param_var_decl) == 1;
  const bool exact_active_parameter =
      exact_active_function_parameter || exact_active_requires_parameter;
  SgScopeStatement *active_parameter_scope =
      exact_active_function_parameter
          ? static_cast<SgScopeStatement *>(active_signature_scope)
          : static_cast<SgScopeStatement *>(active_requires_scope);
  if (!exact_active_parameter || active_parameter_scope == nullptr ||
      SageBuilder::topScopeStack() != active_parameter_scope) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[parameter-producer]: "
            "parameter=%p name=%s owner=%p active-declaration=%p "
            "active-parameter-owner=%p signature-scope=%p "
            "requires-expression=%p requires-scope=%p top-scope=%p cannot "
            "be translated outside its exact typed owner transaction\n",
            static_cast<void *>(param_var_decl),
            param_var_decl->getQualifiedNameAsString().c_str(),
            static_cast<void *>(owning_function),
            static_cast<const void *>(active_signature_declaration),
            static_cast<const void *>(active_parameter_owner),
            static_cast<void *>(active_signature_scope),
            static_cast<const void *>(active_requires_expression),
            static_cast<void *>(active_requires_scope),
            static_cast<void *>(SageBuilder::topScopeStack()));
    ROSE_ABORT();
  }
  const bool build_semantic_parameter =
      exact_active_function_parameter && active_signature_is_semantic;
  const bool build_explicit_template_id_type_use =
      exact_active_function_parameter &&
      active_signature_is_explicit_template_id_type_use;
  SgType *type = nullptr;
  clang::TagDecl *written_parameter_tag_decl = nullptr;
  SgDeclarationStatement *pretranslated_written_parameter_tag = nullptr;
  bool written_parameter_declares_tag = false;
  bool written_type_spells_elaborated_keyword = false;
  bool written_type_spells_elaborated_tag_keyword = false;
  clang::NestedNameSpecifierLoc written_parameter_type_qualifier_loc;
  bool written_parameter_type_qualifier_is_semantic_macro_fragment = false;
  int written_type_qualification_length = 0;
  bool written_type_has_explicit_global_qualifier = false;
  clang::TypeSourceInfo *parameter_type_info =
      markClangTypeSourceInfoDefined(readClangApiValueDefined(
          [&]() { return param_var_decl->getTypeSourceInfo(); }));
  const bool semantic_parameter_has_exact_source_spelling =
      build_semantic_parameter && !build_explicit_template_id_type_use &&
      parameter_type_info != nullptr && !param_var_decl->isImplicit() &&
      !param_var_decl->isFromASTFile() &&
      sourceRangeOwnsPhysicalSource(
          clangVarDeclSourceRangeDefined(param_var_decl));
  if (semantic_parameter_has_exact_source_spelling) {
    clang::TypeLoc type_loc = readClangApiValueDefined(
        [&]() { return parameter_type_info->getTypeLoc(); });
    markClangTypeLocDataDefined(type_loc);
    written_type_spells_elaborated_keyword =
        typeLocSpellsDirectElaboratedKeyword(type_loc);
    written_type_spells_elaborated_tag_keyword =
        typeLocSpellsDirectElaboratedTagKeyword(type_loc);
    written_parameter_tag_decl = typeLocSpellsDirectTagDecl(type_loc);
    written_parameter_type_qualifier_loc = typeLocQualifierLoc(type_loc);
    if (written_parameter_type_qualifier_loc) {
      const SourceQualification source_qualification =
          sourceQualificationFromNestedNameSpecifierLoc(
              written_parameter_type_qualifier_loc, p_compiler_instance,
              "semantic-parameter-type-classification");
      written_parameter_type_qualifier_is_semantic_macro_fragment =
          sourceQualificationIsSemanticMacroFragment(source_qualification);
      written_type_qualification_length = nestedNameSpecifierLocComponentCount(
          written_parameter_type_qualifier_loc);
      written_type_has_explicit_global_qualifier =
          nestedNameSpecifierLocHasExplicitGlobal(
              written_parameter_type_qualifier_loc);
    }
  }
  if (build_semantic_parameter) {
    // A semantic auxiliary function owns a canonical signature, not the
    // type tree of whichever declaration Clang used to materialize it.
    // Translating TypeLoc here would construct source-spelled alias/template
    // nodes in the function's SgDeclarationScope (for example
    // __bool_constant<true>), giving the semantic function a physical source
    // descendant.  The exact written qualifier above is declaration-local
    // syntax metadata and is safe to retain independently; build the semantic
    // type itself from QualType.
    type = build_explicit_template_id_type_use
               ? buildExplicitTemplateIdTypeUseFromQualifiedType(
                     param_var_decl->getType(),
                     "VisitParmVarDecl:explicit-instantiation-parameter")
               : buildSemanticTypeFromQualifiedType(
                     param_var_decl->getType(),
                     "VisitParmVarDecl:semantic-parameter");
  } else if (clang::TypeSourceInfo *type_info = parameter_type_info) {
    clang::TypeLoc type_loc =
        readClangApiValueDefined([&]() { return type_info->getTypeLoc(); });
    markClangTypeLocDataDefined(type_loc);
    std::vector<clang::TagDecl *> written_parameter_tags;
    std::set<const clang::TagDecl *> seen_written_parameter_tags;
    collectElaboratedTagDeclsFromTypeLoc(type_loc, written_parameter_tags,
                                         seen_written_parameter_tags);
    if (!written_parameter_tags.empty()) {
      SgDeclarationScope *signature_scope = active_signature_scope;
      if (!exact_active_parameter || active_signature_is_semantic ||
          signature_scope == nullptr ||
          SageBuilder::topScopeStack() != signature_scope ||
          p_compiler_instance == nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[parameter-tag-owner]: parameter=%s "
                "has no exact active source signature scope while its "
                "written type is being classified\n",
                param_var_decl->getQualifiedNameAsString().c_str());
        ROSE_ABORT();
      }
      clang::SourceManager &source_manager =
          p_compiler_instance->getSourceManager();
      for (clang::TagDecl *tag_decl : written_parameter_tags) {
        tag_decl = markClangSpecificDeclDefined(tag_decl);
        if (tag_decl == nullptr ||
            !sourceRangeContainsLocation(
                clangVarDeclSourceRangeDefined(param_var_decl),
                tag_decl->getBeginLoc(), &source_manager)) {
          continue;
        }
        clang::TagDecl *canonical_tag =
            markClangSpecificDeclDefined(readClangApiValueDefined(
                [&]() { return tag_decl->getCanonicalDecl(); }));
        if (canonical_tag == nullptr) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[parameter-tag-owner]: parameter=%s "
                  "contains a written tag without canonical identity\n",
                  param_var_decl->getQualifiedNameAsString().c_str());
          ROSE_ABORT();
        }
        p_function_parameter_construction_stack[construction_frame_index]
            .source_declarator_tags.insert(canonical_tag);
      }
    }
    written_type_spells_elaborated_keyword =
        typeLocSpellsDirectElaboratedKeyword(type_loc);
    written_type_spells_elaborated_tag_keyword =
        typeLocSpellsDirectElaboratedTagKeyword(type_loc);
    written_parameter_tag_decl = typeLocSpellsDirectTagDecl(type_loc);
    if (written_parameter_tag_decl != nullptr) {
      if (p_compiler_instance == nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[parameter-tag-owner]: parameter=%s "
                "cannot classify a written tag without a compiler source "
                "manager\n",
                param_var_decl->getQualifiedNameAsString().c_str());
        ROSE_ABORT();
      }
      clang::SourceManager &source_manager =
          p_compiler_instance->getSourceManager();
      written_parameter_declares_tag = sourceRangeContainsLocation(
          clangVarDeclSourceRangeDefined(param_var_decl),
          written_parameter_tag_decl->getBeginLoc(), &source_manager);
      if (written_parameter_declares_tag) {
        SgDeclarationScope *signature_scope = active_signature_scope;
        if (!exact_active_parameter || active_signature_is_semantic ||
            signature_scope == nullptr ||
            SageBuilder::topScopeStack() != signature_scope) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[parameter-tag-owner]: parameter=%s "
                  "has no exact active source signature scope while its tag "
                  "declaration is being constructed\n",
                  param_var_decl->getQualifiedNameAsString().c_str());
          ROSE_ABORT();
        }
        p_function_parameter_construction_stack[construction_frame_index]
            .source_declarator_tags.insert(
                written_parameter_tag_decl->getCanonicalDecl());
        pretranslated_written_parameter_tag =
            lookupExactSgDeclarationForClangDecl(written_parameter_tag_decl,
                                                 /*allow_on_demand=*/false);
      }
    }
    written_parameter_type_qualifier_loc = typeLocQualifierLoc(type_loc);
    if (clang::NestedNameSpecifierLoc qualifier_loc =
            written_parameter_type_qualifier_loc) {
      auto next_qualifier_loc = [](clang::NestedNameSpecifierLoc current)
          -> clang::NestedNameSpecifierLoc {
        current = markClangNestedNameSpecifierLocDefined(current);
        switch (current.getNestedNameSpecifier().getKind()) {
        case clang::NestedNameSpecifier::Kind::Namespace:
          return markClangNestedNameSpecifierLocDefined(
              current.getAsNamespaceAndPrefix().Prefix);
        case clang::NestedNameSpecifier::Kind::Type:
          return markClangNestedNameSpecifierLocDefined(
              current.getAsTypeLoc().getPrefix());
        case clang::NestedNameSpecifier::Kind::Global:
        case clang::NestedNameSpecifier::Kind::MicrosoftSuper:
        case clang::NestedNameSpecifier::Kind::Null:
          return clang::NestedNameSpecifierLoc();
        }
        return clang::NestedNameSpecifierLoc();
      };

      for (clang::NestedNameSpecifierLoc current = qualifier_loc; current;
           current = next_qualifier_loc(current)) {
        current = markClangNestedNameSpecifierLocDefined(current);
        switch (current.getNestedNameSpecifier().getKind()) {
        case clang::NestedNameSpecifier::Kind::Namespace:
        case clang::NestedNameSpecifier::Kind::Type:
          ++written_type_qualification_length;
          break;
        case clang::NestedNameSpecifier::Kind::Global:
          if (current.getLocalBeginLoc().isValid()) {
            written_type_has_explicit_global_qualifier = true;
          }
          break;
        case clang::NestedNameSpecifier::Kind::MicrosoftSuper:
        case clang::NestedNameSpecifier::Kind::Null:
          break;
        }
      }
    }
    auto materialize_inline_tag_definition_for_qual_type =
        [&](clang::TypeLoc written_type_loc, clang::QualType qual_type,
            clang::SourceRange owner_range) -> bool {
      if (qual_type.isNull() || p_compiler_instance == nullptr ||
          !owner_range.isValid() ||
          !typeLocSpellsDirectInlineTag(written_type_loc)) {
        return false;
      }

      clang::QualType stripped_type = qual_type;
      clang::TagDecl *owned_tag_decl = nullptr;
      stripped_type = stripQualifiedPointerArrayType(stripped_type, nullptr,
                                                     &owned_tag_decl);

      clang::TagDecl *tag_decl = owned_tag_decl;
      if (tag_decl == nullptr && !stripped_type.isNull()) {
        stripped_type = markClangQualTypeDefined(stripped_type);
        tag_decl = markClangSpecificDeclDefined(
            const_cast<clang::TagDecl *>(readClangApiValueDefined(
                [&]() { return stripped_type->getAsTagDecl(); })));
      }
      tag_decl = markClangSpecificDeclDefined(tag_decl);
      if (tag_decl == nullptr) {
        return false;
      }

      clang::SourceManager &sm = p_compiler_instance->getSourceManager();
      if (!tagDefinitionWrittenInRange(tag_decl, owner_range, &sm)) {
        return false;
      }

      clang::TagDecl *canonical_tag =
          markClangSpecificDeclDefined(readClangApiValueDefined(
              [&]() { return tag_decl->getCanonicalDecl(); }));
      if (!p_inline_tag_decls.insert(canonical_tag).second) {
        return true;
      }
      (void)lookupSgDeclarationForClangDecl(tag_decl,
                                            /*allow_on_demand=*/true);
      return true;
    };
    auto translated_inline_tag_type_for_qual_type =
        [&](clang::QualType qual_type) -> SgType * {
      if (qual_type.isNull()) {
        return nullptr;
      }

      // Preserve the full written type shape. The inline-tag materialization
      // above ensures the referenced tag declaration exists; rebuilding the
      // type from the whole QualType keeps pointer/array layers intact
      // instead of collapsing `struct T *` to `struct T`.
      return buildTypeFromQualifiedType(qual_type);
    };

    const bool inline_tag_definition =
        materialize_inline_tag_definition_for_qual_type(
            type_info->getTypeLoc(), param_var_decl->getType(),
            clangVarDeclSourceRangeDefined(param_var_decl));
    const bool preserve_written_nonreal_type =
        written_type_qualification_length > 0 ||
        written_type_has_explicit_global_qualifier;
    // K&R-style C parameter declarations are semantically typed after the
    // declarator list, so preserve that path. Ordinary parameters should keep
    // the written TypeLoc whenever possible so inline/anonymous tag spellings
    // remain attached to the declaration site instead of collapsing to a bare
    // semantic tag reference.
    const bool direct_injected_class_name_parameter =
        static_cast<bool>(peelDirectInlineTagTypeLoc(type_info->getTypeLoc())
                              .getAs<clang::InjectedClassNameTypeLoc>());
    if (direct_injected_class_name_parameter) {
      ++p_preserve_omitted_injected_class_template_id_depth;
    }
    type = buildTypeFromTypeLoc(type_info->getTypeLoc());
    if (direct_injected_class_name_parameter) {
      ROSE_ASSERT(p_preserve_omitted_injected_class_template_id_depth > 0);
      --p_preserve_omitted_injected_class_template_id_depth;
    }
    if ((type == nullptr || isSgNonrealType(type) != nullptr) &&
        inline_tag_definition) {
      type =
          translated_inline_tag_type_for_qual_type(param_var_decl->getType());
    }
    if ((type == nullptr || (isSgNonrealType(type) != nullptr &&
                             !preserve_written_nonreal_type)) &&
        !param_var_decl->getType().isNull() &&
        !param_var_decl->getType()->isDependentType()) {
      type = buildTypeFromQualifiedType(param_var_decl->getType());
    }
  }
  if (type == nullptr) {
    type = buildTypeFromQualifiedType(param_var_decl->getType());
  }
  if (type == nullptr) {
    type = buildTypeFromQualifiedType(param_var_decl->getOriginalType());
  }
  if (build_semantic_parameter && type == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[semantic-parameter-type]: "
            "parameter=%s has no exact semantic type\n",
            param_var_decl->getQualifiedNameAsString().c_str());
    ROSE_ABORT();
  }
  if (!build_semantic_parameter && param_var_decl->isParameterPack() &&
      typeHasPackSyntax(type)) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[function-parameter-pack-owner]: "
            "parameter=%s acquired declaration-owned pack syntax during exact "
            "type construction\n",
            name.getString().c_str());
    ROSE_ABORT();
  }

  auto validate_declarator_owned_parameter_tag = [&](clang::TagDecl *tag_decl) {
    tag_decl = markClangSpecificDeclDefined(tag_decl);
    if (tag_decl == nullptr) {
      return;
    }
    if (p_compiler_instance == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[parameter-tag-owner]: parameter=%s "
              "first tag declaration has no compiler source manager\n",
              param_var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }

    clang::SourceManager &source_manager =
        p_compiler_instance->getSourceManager();
    if (!sourceRangeContainsLocation(
            clangVarDeclSourceRangeDefined(param_var_decl),
            tag_decl->getBeginLoc(), &source_manager)) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[parameter-tag-owner]: parameter=%s "
              "first tag='%s' is not in the exact parameter source range\n",
              param_var_decl->getQualifiedNameAsString().c_str(),
              tag_decl->getNameAsString().c_str());
      ROSE_ABORT();
    }

    SgDeclarationScope *signature_scope = active_signature_scope;
    if (!exact_active_parameter || active_signature_is_semantic ||
        signature_scope == nullptr ||
        SageBuilder::topScopeStack() != signature_scope) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[parameter-tag-owner]: parameter=%s "
              "has no exact function declaration scope\n",
              param_var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }

    SgDeclarationStatement *translated =
        lookupExactSgDeclarationForClangDecl(tag_decl,
                                             /*allow_on_demand=*/true);
    if (translated == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[parameter-tag-owner]: parameter=%s "
              "tag='%s' has no exact Sage declaration\n",
              param_var_decl->getQualifiedNameAsString().c_str(),
              tag_decl->getNameAsString().c_str());
      ROSE_ABORT();
    }

    const bool source_has_definition = readClangApiValueDefined(
        [&]() { return tag_decl->isThisDeclarationADefinition(); });
    SgDeclarationStatement *source_surface =
        source_has_definition ? translated->get_definingDeclaration()
                              : translated;
    if (source_surface == nullptr) {
      source_surface = translated;
    }
    SgClassDeclaration *class_surface = isSgClassDeclaration(source_surface);
    SgEnumDeclaration *enum_surface = isSgEnumDeclaration(source_surface);
    const bool sage_surface_is_definition =
        (class_surface != nullptr &&
         class_surface->get_definition() != nullptr &&
         class_surface->get_definingDeclaration() == class_surface) ||
        (enum_surface != nullptr && !enum_surface->isForward() &&
         enum_surface->get_definingDeclaration() == enum_surface);
    if (pretranslated_written_parameter_tag != nullptr) {
      const bool exactPretranslatedChain =
          translated == pretranslated_written_parameter_tag ||
          translated->get_firstNondefiningDeclaration() ==
              pretranslated_written_parameter_tag ||
          pretranslated_written_parameter_tag->get_definingDeclaration() ==
              source_surface;
      Sg_File_Info *sourceInfo = source_surface->get_file_info();
      const std::size_t sourceSurfaceOccurrences =
          std::count(signature_scope->get_declarations().begin(),
                     signature_scope->get_declarations().end(), source_surface);
      const bool detachedSourceSurface =
          source_surface->get_parent() == nullptr &&
          sourceSurfaceOccurrences == 0;
      const bool attachedSourceSurface =
          source_surface->get_parent() == signature_scope &&
          sourceSurfaceOccurrences == 1;
      SgScopeStatement *sourceSemanticScope = source_surface->get_scope();
      const bool semanticScopeHasNoCompetingOwnership =
          sourceSemanticScope != nullptr &&
          (sourceSemanticScope == signature_scope ||
           !sourceSemanticScope->statementExistsInScope(source_surface));
      if (!exactPretranslatedChain ||
          source_has_definition != sage_surface_is_definition ||
          !semanticScopeHasNoCompetingOwnership ||
          (!detachedSourceSurface && !attachedSourceSurface) ||
          (class_surface != nullptr &&
           class_surface->get_isAutonomousDeclaration()) ||
          (enum_surface != nullptr &&
           enum_surface->get_isAutonomousDeclaration()) ||
          sourceInfo == nullptr || sourceInfo->get_line() <= 0 ||
          sourceInfo->get_file_id() < 0 || sourceInfo->isCompilerGenerated() ||
          sourceInfo->isFrontendSpecific()) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[parameter-tag-handoff]: parameter=%s "
                "tag='%s' pretranslated=%p translated=%p source=%p parent=%p "
                "scope=%p signature-scope=%p occurrences=%zu lacks one exact "
                "typed ownership handoff state\n",
                param_var_decl->getQualifiedNameAsString().c_str(),
                tag_decl->getNameAsString().c_str(),
                static_cast<void *>(pretranslated_written_parameter_tag),
                static_cast<void *>(translated),
                static_cast<void *>(source_surface),
                static_cast<void *>(source_surface->get_parent()),
                static_cast<void *>(source_surface->get_scope()),
                static_cast<void *>(signature_scope), sourceSurfaceOccurrences);
        ROSE_ABORT();
      }
      // The exact tag translation can complete the typed ownership transfer
      // while materializing the parameter's written type.  Otherwise this is
      // the single construction point that completes it.  Both states are
      // explicit; any partial or duplicate transfer is rejected above.
      if (detachedSourceSurface) {
        SageBuilder::attachSourceDeclaratorTag(signature_scope, source_surface);
      }
    }
    if ((class_surface == nullptr && enum_surface == nullptr) ||
        source_has_definition != sage_surface_is_definition ||
        source_surface->get_parent() != signature_scope ||
        std::count(signature_scope->get_declarations().begin(),
                   signature_scope->get_declarations().end(),
                   source_surface) != 1 ||
        (class_surface != nullptr &&
         class_surface->get_isAutonomousDeclaration()) ||
        (enum_surface != nullptr &&
         enum_surface->get_isAutonomousDeclaration())) {
      fprintf(
          stderr,
          "REX_FRONTEND_INVARIANT[parameter-tag-owner]: parameter=%s "
          "tag='%s' translated=%p source-surface=%p class=%p enum=%p "
          "source-definition=%d Sage-definition=%d parent=%p signature-scope="
          "%p scope=%p occurrences=%zu autonomous=%d did not retain one "
          "exact construction-time source surface; file=(line=%d,file=%d,"
          "compiler=%d,frontend=%d)\n",
          param_var_decl->getQualifiedNameAsString().c_str(),
          tag_decl->getNameAsString().c_str(), static_cast<void *>(translated),
          static_cast<void *>(source_surface),
          static_cast<void *>(class_surface), static_cast<void *>(enum_surface),
          source_has_definition ? 1 : 0, sage_surface_is_definition ? 1 : 0,
          static_cast<void *>(source_surface->get_parent()),
          static_cast<void *>(signature_scope),
          static_cast<void *>(source_surface->get_scope()),
          std::count(signature_scope->get_declarations().begin(),
                     signature_scope->get_declarations().end(), source_surface),
          class_surface != nullptr
              ? class_surface->get_isAutonomousDeclaration()
          : enum_surface != nullptr
              ? enum_surface->get_isAutonomousDeclaration()
              : true,
          source_surface->get_file_info() != nullptr
              ? source_surface->get_file_info()->get_line()
              : 0,
          source_surface->get_file_info() != nullptr
              ? source_surface->get_file_info()->get_file_id()
              : -1,
          source_surface->get_file_info() != nullptr &&
                  source_surface->get_file_info()->isCompilerGenerated()
              ? 1
              : 0,
          source_surface->get_file_info() != nullptr &&
                  source_surface->get_file_info()->isFrontendSpecific()
              ? 1
              : 0);
      ROSE_ABORT();
    }
    require_exact_source_provenance(
        source_surface, "VisitParmVarDecl:source-declarator-surface");
  };

  if (written_parameter_declares_tag) {
    validate_declarator_owned_parameter_tag(written_parameter_tag_decl);
  }

  SgInitializer *init = nullptr;

  if (p_defer_parameter_default_argument_depth == 0) {
    if (const clang::Expr *default_arg_expr =
            markClangExprObjectDefinedByClass(const_cast<clang::Expr *>(
                getParmVarDeclDefaultArgExpr(param_var_decl)))) {
      SgNode *tmp_expr =
          build_semantic_parameter
              ? translateSemanticExpressionSubtree(
                    default_arg_expr,
                    "VisitParmVarDecl:semantic-parameter-default")
              : Traverse(const_cast<clang::Expr *>(default_arg_expr));
      SgExpression *expr = isSgExpression(tmp_expr);
      if (expr == nullptr) {
        std::cerr << "REX_FRONTEND_INVARIANT[parameter-default]: Clang default "
                     "argument translated to "
                  << (tmp_expr != nullptr ? tmp_expr->class_name()
                                          : std::string("<null>"))
                  << " instead of SgExpression" << std::endl;
        ROSE_ABORT();
      } else {
        // The same Clang default-argument subtree can be referenced by multiple
        // redeclarations. Reusing a single SgExpression would create multiple
        // parents and break CFG invariants. Let the first initializer adopt the
        // detached translation, then deep-copy only after the cached expression
        // already has a real AST owner.
        SgExpression *expr_copy = prepareExpressionForAttachment(expr);
        ROSE_ASSERT(expr_copy != nullptr);
        // Preserve the expression producer's source/generated split. The new
        // initializer below is the only owner of the written default range.
        requireDetachedSourceExpressionProvenance(
            expr_copy, "VisitParmVarDecl:parameter-default");
        if (SgExprListExp *expr_list_expr = isSgExprListExp(expr_copy)) {
          init = SageBuilder::buildAggregateInitializer_nfi(
              expr_list_expr, type,
              SgAggregateInitializer::e_aggregate_initializer_source_braced);
        } else if (SgConstructorInitializer *ctor_init =
                       isSgConstructorInitializer(expr_copy)) {
          init = SageBuilder::buildAssignInitializer_nfi(ctor_init, type);
        } else {
          init = SageBuilder::buildAssignInitializer_nfi(expr_copy, type);
        }
        applySourceRange(init, param_var_decl->getDefaultArgRange());
      }
    }
  }

  SgInitializedName *param_init_name =
      build_semantic_parameter
          ? SageBuilder::buildSemanticInitializedName(name, type, init)
          : SageBuilder::buildInitializedName(name, type, init);
  if (!build_semantic_parameter && param_var_decl->isParameterPack() &&
      typeHasPackSyntax(type)) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[function-parameter-pack-owner]: "
            "parameter=%s type was mutated while constructing its initialized "
            "name\n",
            name.getString().c_str());
    ROSE_ABORT();
  }
  if (build_semantic_parameter) {
    validate_exact_semantic_function_provenance(
        param_init_name, "VisitParmVarDecl:semantic-parameter-producer");
  }
  if (init != nullptr) {
    ROSE_ASSERT(param_init_name->get_initializer() == init);
    ROSE_ASSERT(init->get_parent() == nullptr ||
                init->get_parent() == param_init_name);
    init->set_parent(param_init_name);
  }
  if (!build_semantic_parameter) {
    applySourceRange(param_init_name,
                     clangVarDeclSourceRangeDefined(param_var_decl));
  }
  clear_anonymous_name_qualification(param_init_name);
  if (param_var_decl->isParameterPack()) {
    if (!build_semantic_parameter && typeHasPackSyntax(type)) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[function-parameter-pack-owner]: "
              "parameter=%s Sage-type=%s retains ellipsis syntax in its type "
              "instead of the parameter declarator; Clang type chain:",
              name.getString().c_str(), type->class_name().c_str());
      clang::TypeSourceInfo *pack_type_info =
          param_var_decl->getTypeSourceInfo();
      if (pack_type_info == nullptr) {
        fprintf(stderr, " <missing TypeSourceInfo>");
      } else {
        for (clang::TypeLoc current = pack_type_info->getTypeLoc();
             !current.isNull(); current = current.getNextTypeLoc()) {
          const clang::Type *current_type = current.getTypePtr();
          fprintf(stderr, " %s",
                  current_type != nullptr ? current_type->getTypeClassName()
                                          : "<null>");
        }
      }
      fprintf(stderr, "\n");
      ROSE_ABORT();
    }
    param_init_name->set_is_parameter_pack(true);
    param_init_name->set_is_pack_element(false);
  }
  auto mark_parameter_type_elaboration = [](SgInitializedName *init_name) {
    if (init_name == nullptr) {
      return;
    }
    init_name->set_type_elaboration_required(true);
    init_name->set_type_elaboration_required_for_type(true);
  };
  const bool preserve_parameter_type_elaboration =
      written_type_spells_elaborated_keyword;
  if (preserve_parameter_type_elaboration) {
    mark_parameter_type_elaboration(param_init_name);
  }
  preserveExplicitInitializedNameTypeQualifier(
      param_init_name, written_parameter_type_qualifier_loc,
      p_compiler_instance,
      /*preserve_unqualified_source_spelling=*/
      !build_semantic_parameter ||
          semantic_parameter_has_exact_source_spelling);
  const bool semantic_parameter_requires_source_type_qualification =
      semantic_parameter_has_exact_source_spelling &&
      !written_parameter_type_qualifier_is_semantic_macro_fragment;
  if (semantic_parameter_has_exact_source_spelling &&
      param_init_name->get_source_type_qualification_present() !=
          semantic_parameter_requires_source_type_qualification) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[semantic-parameter-source]: "
            "parameter=%p/%s source-backed=%d semantic-macro-fragment=%d "
            "source-qualification-present=%d has a contradictory "
            "declaration-local type qualification after construction\n",
            static_cast<void *>(param_var_decl),
            param_var_decl->getQualifiedNameAsString().c_str(),
            semantic_parameter_has_exact_source_spelling ? 1 : 0,
            written_parameter_type_qualifier_is_semantic_macro_fragment ? 1 : 0,
            param_init_name->get_source_type_qualification_present() ? 1 : 0);
    ROSE_ABORT();
  }
  publishUnqualifiedElaboratedTagQualification(
      param_init_name, written_type_spells_elaborated_tag_keyword,
      written_parameter_type_qualifier_loc, written_parameter_tag_decl,
      "VisitParmVarDecl");
  if (written_type_qualification_length > 0) {
    param_init_name->set_name_qualification_length_for_type(
        written_type_qualification_length);
  }
  if (written_type_has_explicit_global_qualifier) {
    param_init_name->set_global_qualification_required_for_type(true);
  }
  // Publish only into the exact active signature transaction.  The function
  // producer consumes this temporary parent when it adopts the parameter into
  // the final SgFunctionParameterList.
  if (exact_active_function_parameter) {
    if (construction_frame_index >=
            p_function_parameter_construction_stack.size() ||
        construction_frame_index + 1 !=
            p_function_parameter_construction_stack.size()) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[function-parameter-producer]: "
              "parameter=%p/%s lost its active signature transaction during "
              "recursive type translation\n",
              static_cast<void *>(param_var_decl),
              param_var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }
    const FunctionParameterConstructionFrame &completed_frame =
        p_function_parameter_construction_stack[construction_frame_index];
    if (completed_frame.declaration != active_signature_declaration ||
        completed_frame.parameter_owner != active_parameter_owner ||
        completed_frame.semantic != active_signature_is_semantic ||
        completed_frame.explicit_template_id_type_use !=
            active_signature_is_explicit_template_id_type_use ||
        completed_frame.declaration_scope != active_signature_scope ||
        SageBuilder::topScopeStack() != active_signature_scope) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[function-parameter-producer]: "
              "parameter=%p/%s returned from recursive type translation into "
              "a different signature transaction\n",
              static_cast<void *>(param_var_decl),
              param_var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }
  } else {
    if (requires_frame_index >=
            p_requires_parameter_construction_stack.size() ||
        requires_frame_index + 1 !=
            p_requires_parameter_construction_stack.size()) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[requires-local-parameter-producer]: "
              "parameter=%p/%s lost its requires-expression transaction "
              "during recursive type translation\n",
              static_cast<void *>(param_var_decl),
              param_var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }
    const RequiresParameterConstructionFrame &completed_frame =
        p_requires_parameter_construction_stack[requires_frame_index];
    if (completed_frame.expression != active_requires_expression ||
        completed_frame.scope != active_requires_scope ||
        completed_frame.parameters.count(param_var_decl) != 1 ||
        SageBuilder::topScopeStack() != active_requires_scope) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[requires-local-parameter-producer]: "
              "parameter=%p/%s returned from recursive type translation into "
              "a different requires-expression transaction\n",
              static_cast<void *>(param_var_decl),
              param_var_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }
  }
  SgScopeStatement *scope = active_parameter_scope;
  param_init_name->set_scope(scope);
  param_init_name->set_parent(scope);

  if (!name.getString().empty() &&
      scope->find_symbol_from_declaration(param_init_name) == nullptr) {
    // Parameter construction publishes one freshly allocated symbol after the
    // initialized name has its exact signature scope.
    attachSymbolToExactScope(new SgVariableSymbol(param_init_name), scope);
  }
  if (!name.getString().empty() &&
      scope->find_symbol_from_declaration(param_init_name) == nullptr) {
    std::cerr << "REX_FRONTEND_INVARIANT[parameter-publication]: Clang "
              << param_var_decl->getQualifiedNameAsString()
              << " did not publish an exact parameter symbol" << std::endl;
    ROSE_ABORT();
  }

  if (clang::FunctionDecl *owning_function =
          llvm::dyn_cast_or_null<clang::FunctionDecl>(
              param_var_decl->getDeclContext())) {
    (void)owning_function;
  }

  *node = param_init_name;
  bool visit_res = false;
  if (build_semantic_parameter) {
    FinalizedDeclarationProvenanceGuard finalized_provenance_guard(
        p_declaration_with_finalized_provenance, param_init_name);
    visit_res = VisitDeclaratorDecl(param_var_decl, node) && res;
  } else {
    visit_res = VisitDeclaratorDecl(param_var_decl, node) && res;
  }
  if (preserve_parameter_type_elaboration) {
    mark_parameter_type_elaboration(isSgInitializedName(*node));
  }
  clear_anonymous_name_qualification(isSgInitializedName(*node));

  return visit_res;
}

bool ClangToSageTranslator::VisitVarTemplateSpecializationDecl(
    clang::VarTemplateSpecializationDecl *var_template_specialization_decl,
    SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitVarTemplateSpecializationDecl"
            << std::endl;
#endif
  bool res = true;

  var_template_specialization_decl =
      markClangVarTemplateSpecializationStateDefined(
          var_template_specialization_decl);
  if (var_template_specialization_decl == nullptr ||
      var_template_specialization_decl->isInvalidDecl()) {
    *node = nullptr;
    return false;
  }

  // ROOT CAUSE FIX: Variable template specializations should be represented
  // as SgTemplateVariableDeclaration with specialization arguments so name
  // qualification and symbol table logic can distinguish instantiations.

  // Get variable name and type
  SgName name(var_template_specialization_decl->getNameAsString());
  clang::QualType qual_type = var_template_specialization_decl->getType();
  markClangValueDefined(qual_type);
  markClangTypeObjectDefinedByClass(qual_type.getTypePtrOrNull());
  SgType *type = buildTypeFromQualifiedType(qual_type);

  const clang::TemplateSpecializationKind specialization_kind =
      var_template_specialization_decl->getTemplateSpecializationKind();
  const bool explicit_instantiation_kind =
      specialization_kind == clang::TSK_ExplicitInstantiationDeclaration ||
      specialization_kind == clang::TSK_ExplicitInstantiationDefinition;
  const bool source_written_specialization =
      variableTemplateSpecializationHasSourceWrittenShell(
          var_template_specialization_decl);
  const bool explicit_instantiation =
      explicit_instantiation_kind && source_written_specialization;
  const bool source_written_initializer =
      variableTemplateSpecializationHasSourceWrittenInitializer(
          var_template_specialization_decl);

  // Get initializer if present
  SgInitializer *init = nullptr;
  clang::Expr *source_init_expr = nullptr;
  var_template_specialization_decl =
      llvm::cast<clang::VarTemplateSpecializationDecl>(
          markClangVarDeclInitStorageDefined(var_template_specialization_decl));
  if (var_template_specialization_decl->hasInit()) {
    clang::Expr *init_expr = markClangExprObjectDefinedByClass(
        var_template_specialization_decl->getInit());
    if (init_expr != nullptr) {
      source_init_expr = init_expr;
      SgNode *tmp_node =
          source_written_initializer
              ? Traverse(init_expr)
              : translateSemanticExpressionSubtree(
                    init_expr, "VisitVarTemplateSpecializationDecl:semantic-"
                               "initializer-expression");
      SgExpression *sg_init_expr = isSgExpression(tmp_node);
      if (sg_init_expr != nullptr) {
        sg_init_expr = prepareExpressionForAttachment(sg_init_expr);
        if (sg_init_expr == nullptr) {
          std::cerr << "REX_FRONTEND_INVARIANT[variable-template-"
                       "specialization-initializer-owner]: initializer could "
                       "not produce an exact owned expression tree"
                    << std::endl;
          ROSE_ABORT();
        }
        if (SgInitializer *translated_initializer =
                isSgInitializer(sg_init_expr)) {
          init = translated_initializer;
        } else {
          init = SageBuilder::buildAssignInitializer_nfi(sg_init_expr, type);
        }
      } else {
        std::cerr << "REX_FRONTEND_INVARIANT[variable-template-specialization-"
                     "initializer]: Clang initializer translated to "
                  << (tmp_node != nullptr ? tmp_node->class_name()
                                          : std::string("<null>"))
                  << " instead of SgExpression" << std::endl;
        ROSE_ABORT();
      }
    }
  }

  auto normalize_template_variable_scope =
      [&](clang::DeclContext *decl_context,
          SgScopeStatement *candidate_scope) -> SgScopeStatement * {
    SgScopeStatement *normalized_scope = candidate_scope;
    if (decl_context != nullptr) {
      if (SgScopeStatement *resolved =
              resolveScopeFromDeclContext(decl_context)) {
        normalized_scope = resolved;
      }
    }
    if (!scopeReachableFromCurrentFile(normalized_scope) &&
        decl_context != nullptr) {
      bool namespace_context_only = true;
      for (clang::DeclContext *ctx = decl_context; ctx != nullptr;
           ctx = ctx->getParent()) {
        if (ctx->isTranslationUnit() || ctx->isNamespace() ||
            llvm::isa<clang::LinkageSpecDecl>(ctx)) {
          continue;
        }
        namespace_context_only = false;
        break;
      }
      if (namespace_context_only) {
        if (SgScopeStatement *reachable_scope =
                resolveReachableNamespaceScope(decl_context)) {
          normalized_scope = reachable_scope;
        }
      }
    }
    if (!scopeReachableFromCurrentFile(normalized_scope)) {
      if (SgGlobal *global_scope = getGlobalScope()) {
        normalized_scope = global_scope;
      }
    }
    return normalized_scope;
  };

  SgScopeStatement *scope = normalize_template_variable_scope(
      var_template_specialization_decl->getDeclContext(),
      SageBuilder::topScopeStack());
  if (scope == nullptr) {
    scope = getGlobalScope();
  }

  SgInitializedName *previous_specialization_name = nullptr;
  clang::VarTemplateSpecializationDecl *previous_specialization =
      llvm::dyn_cast_or_null<clang::VarTemplateSpecializationDecl>(
          markClangDeclObjectDefinedByKind(readClangApiValueDefined([&]() {
            return var_template_specialization_decl->getPreviousDecl();
          })));
  if (previous_specialization != nullptr) {
    auto previous_translation =
        p_decl_translation_map.find(previous_specialization);
    if (previous_translation != p_decl_translation_map.end()) {
      previous_specialization_name =
          exactInitializedNameFromTranslatedVariableNode(
              previous_translation->second);
    }
    if (previous_specialization_name == nullptr) {
      if (p_decl_translation_in_progress.count(previous_specialization) != 0 ||
          p_decl_translation_on_demand.count(previous_specialization) != 0) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-template-redeclaration-"
                "order]: specialization=%s predecessor=%p is unpublished "
                "while its exact translation is already in progress\n",
                var_template_specialization_decl->getQualifiedNameAsString()
                    .c_str(),
                static_cast<void *>(previous_specialization));
        ROSE_ABORT();
      }
      SgNode *translated_previous = TraverseOnDemand(previous_specialization);
      previous_translation =
          p_decl_translation_map.find(previous_specialization);
      if (previous_translation != p_decl_translation_map.end()) {
        previous_specialization_name =
            exactInitializedNameFromTranslatedVariableNode(
                previous_translation->second);
      }
      if (previous_specialization_name == nullptr) {
        previous_specialization_name =
            exactInitializedNameFromTranslatedVariableNode(translated_previous);
      }
    }
    SgTemplateVariableDeclaration *previous_sage_specialization =
        isSgTemplateVariableDeclaration(
            previous_specialization_name != nullptr
                ? previous_specialization_name->get_parent()
                : nullptr);
    if (previous_sage_specialization == nullptr ||
        previous_specialization_name->get_name() != name ||
        previous_specialization_name->get_scope() != scope) {
      fprintf(
          stderr,
          "REX_FRONTEND_INVARIANT[variable-template-redeclaration]: "
          "specialization=%s predecessor=%p did not resolve to the "
          "exact same Sage template-variable entity\n",
          var_template_specialization_decl->getQualifiedNameAsString().c_str(),
          static_cast<void *>(previous_specialization));
      ROSE_ABORT();
    }
  }

  SgTemplateVariableDeclaration *var_decl =
      SageBuilder::buildTemplateVariableDeclaration_nfi(
          name, type, init, scope,
          SageBuilder::template_variable_entity_kind::specialization,
          previous_specialization_name);
  normalize_standalone_template_variable_declaration(var_decl);
  if (var_decl == nullptr || var_decl->get_variables().size() != 1 ||
      var_decl->get_variables().front() == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[variable-template-specialization-"
            "component-owner]: specialization=%s has no exact initialized "
            "name\n",
            name.getString().c_str());
    ROSE_ABORT();
  }
  SgInitializedName *specialization_name = var_decl->get_variables().front();
  SgVariableDefinition *specialization_definition =
      specialization_name->get_definition();
  if (specialization_name->get_parent() != var_decl ||
      specialization_name->get_scope() != scope ||
      specialization_name->get_declptr() != var_decl ||
      specialization_definition == nullptr ||
      specialization_definition->get_vardefn() != specialization_name ||
      specialization_definition->get_parent() != specialization_name ||
      (init != nullptr && init->get_parent() != specialization_name)) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[variable-template-specialization-"
            "component-owner]: specialization=%s has malformed initialized "
            "name, definition, or initializer ownership\n",
            name.getString().c_str());
    ROSE_ABORT();
  }
  var_decl->set_unparse_template_ast(shouldForceTemplateAstUnparse(
      p_compiler_instance, var_template_specialization_decl, p_sage_source_file,
      /*on_demand_translation=*/false,
      var_template_specialization_decl->getTemplateSpecializationKind()));
  if (var_template_specialization_decl->isConstexpr() &&
      !explicit_instantiation) {
    var_decl->set_is_constexpr(true);
  }

  const bool specialization_is_partial =
      readClangApiValueDefined([&]() {
        return var_template_specialization_decl
            ->getSpecializedTemplateOrPartial();
      }).dyn_cast<clang::VarTemplatePartialSpecializationDecl *>() != nullptr;

  const clang::TemplateArgumentList *args_ptr =
      markClangTemplateArgumentListDefined(
          &var_template_specialization_decl->getTemplateArgs());
  const clang::TemplateArgumentList *instantiation_args_ptr =
      markClangTemplateArgumentListDefined(
          &var_template_specialization_decl->getTemplateInstantiationArgs());
  const clang::ASTTemplateArgumentListInfo *args_as_written =
      markClangASTTemplateArgumentListInfoDefined(
          var_template_specialization_decl->getTemplateArgsAsWritten());
  ROSE_ASSERT(args_ptr != nullptr);
  ROSE_ASSERT(instantiation_args_ptr != nullptr);
  llvm::ArrayRef<clang::TemplateArgument> args =
      markClangTemplateArgumentArrayDefined(args_ptr->asArray());
  llvm::ArrayRef<clang::TemplateArgument> instantiation_args =
      markClangTemplateArgumentArrayDefined(instantiation_args_ptr->asArray());

  if (source_written_specialization && args_as_written == nullptr) {
    std::cerr
        << "REX_FRONTEND_INVARIANT[variable-template-specialization-args]: "
           "source-written specialization '"
        << var_template_specialization_decl->getQualifiedNameAsString()
        << "' has no exact written template-argument list" << std::endl;
    ROSE_ABORT();
  }

  clang::SourceRange var_template_specialization_range;
  clang::SourceRange explicit_instantiation_directive_range;
  clang::SourceLocation explicit_instantiation_point;
  size_t explicit_instantiation_declaration_begin_index =
      p_expanded_tokens.size();
  size_t explicit_instantiation_name_index = p_expanded_tokens.size();
  if (explicit_instantiation) {
    const clang::SourceLocation point_of_instantiation =
        readClangApiValueDefined([&]() {
          return var_template_specialization_decl->getPointOfInstantiation();
        });
    explicit_instantiation_point = point_of_instantiation;
    const clang::SourceLocation left_angle = readClangApiValueDefined(
        [&]() { return args_as_written->getLAngleLoc(); });
    const clang::SourceLocation right_angle = readClangApiValueDefined(
        [&]() { return args_as_written->getRAngleLoc(); });
    if (!point_of_instantiation.isValid() || !left_angle.isValid() ||
        !right_angle.isValid()) {
      std::cerr << "REX_FRONTEND_INVARIANT[variable-template-explicit-"
                   "instantiation-source]: explicit instantiation '"
                << var_template_specialization_decl->getQualifiedNameAsString()
                << "' has no exact point and written template-id source "
                   "anchors"
                << std::endl;
      ROSE_ABORT();
    }

    const unsigned int point_order = requireExpandedTokenSourceOrder(
        point_of_instantiation,
        "VisitVarTemplateSpecializationDecl:explicit-instantiation-point");
    const unsigned int left_order = requireExpandedTokenSourceOrder(
        left_angle,
        "VisitVarTemplateSpecializationDecl:explicit-instantiation-left-"
        "angle");
    const unsigned int right_order = requireExpandedTokenSourceOrder(
        right_angle,
        "VisitVarTemplateSpecializationDecl:explicit-instantiation-right-"
        "angle");
    if (point_order == 0 || point_order >= left_order ||
        left_order >= right_order || right_order > p_expanded_tokens.size() ||
        p_expanded_tokens[left_order - 1].kind != clang::tok::less ||
        (p_expanded_tokens[right_order - 1].kind != clang::tok::greater &&
         p_expanded_tokens[right_order - 1].kind !=
             clang::tok::greatergreater &&
         p_expanded_tokens[right_order - 1].kind !=
             clang::tok::greatergreatergreater)) {
      std::cerr << "REX_FRONTEND_INVARIANT[variable-template-explicit-"
                   "instantiation-source]: explicit instantiation '"
                << var_template_specialization_decl->getQualifiedNameAsString()
                << "' has malformed ordered expanded source anchors point="
                << point_order << " left=" << left_order
                << " right=" << right_order << std::endl;
      ROSE_ABORT();
    }

    const size_t point_index = static_cast<size_t>(point_order - 1);
    size_t introducer_index = p_expanded_tokens.size();
    unsigned int paren_depth = 0;
    unsigned int square_depth = 0;
    unsigned int brace_depth = 0;
    for (size_t index = point_index; index-- > 0;) {
      const clang::tok::TokenKind kind = p_expanded_tokens[index].kind;
      if (kind == clang::tok::r_paren) {
        ++paren_depth;
      } else if (kind == clang::tok::r_square) {
        ++square_depth;
      } else if (kind == clang::tok::r_brace) {
        ++brace_depth;
      } else if (kind == clang::tok::l_paren && paren_depth != 0) {
        --paren_depth;
      } else if (kind == clang::tok::l_square && square_depth != 0) {
        --square_depth;
      } else if (kind == clang::tok::l_brace) {
        if (brace_depth != 0) {
          --brace_depth;
        } else if (paren_depth == 0 && square_depth == 0) {
          break;
        }
      }

      const bool at_declaration_level =
          paren_depth == 0 && square_depth == 0 && brace_depth == 0;
      if (at_declaration_level && kind == clang::tok::semi) {
        break;
      }
      if (!at_declaration_level || kind != clang::tok::kw_template) {
        continue;
      }
      const clang::tok::TokenKind predecessor =
          index != 0 ? p_expanded_tokens[index - 1].kind : clang::tok::unknown;
      if (predecessor == clang::tok::coloncolon ||
          predecessor == clang::tok::period ||
          predecessor == clang::tok::arrow) {
        continue;
      }
      introducer_index = index;
      break;
    }
    if (introducer_index == p_expanded_tokens.size()) {
      std::cerr << "REX_FRONTEND_INVARIANT[variable-template-explicit-"
                   "instantiation-source]: explicit instantiation '"
                << var_template_specialization_decl->getQualifiedNameAsString()
                << "' has no exact expanded template introducer" << std::endl;
      ROSE_ABORT();
    }
    const size_t directive_begin_index =
        introducer_index != 0 && p_expanded_tokens[introducer_index - 1].kind ==
                                     clang::tok::kw_extern
            ? introducer_index - 1
            : introducer_index;
    const size_t declaration_begin_index = introducer_index + 1;
    if (declaration_begin_index >= point_index ||
        p_expanded_tokens[declaration_begin_index].kind == clang::tok::semi) {
      std::cerr << "REX_FRONTEND_INVARIANT[variable-template-explicit-"
                   "instantiation-source]: explicit instantiation '"
                << var_template_specialization_decl->getQualifiedNameAsString()
                << "' has no exact nested declaration transaction" << std::endl;
      ROSE_ABORT();
    }
    explicit_instantiation_declaration_begin_index = declaration_begin_index;
    explicit_instantiation_name_index = point_index;
    const clang::SourceLocation source_begin =
        p_expanded_tokens[directive_begin_index].location;
    const clang::SourceLocation declaration_begin =
        p_expanded_tokens[declaration_begin_index].location;
    if (!source_begin.isValid() || !declaration_begin.isValid()) {
      std::cerr << "REX_FRONTEND_INVARIANT[variable-template-explicit-"
                   "instantiation-source]: explicit instantiation '"
                << var_template_specialization_decl->getQualifiedNameAsString()
                << "' has an expanded source transaction without exact "
                   "locations"
                << std::endl;
      ROSE_ABORT();
    }
    var_template_specialization_range =
        clang::SourceRange(declaration_begin, right_angle);
    explicit_instantiation_directive_range =
        extendDeclSourceRangeWithTrailingSemicolon(
            clang::SourceRange(source_begin, right_angle),
            p_compiler_instance->getSourceManager(),
            p_compiler_instance->getLangOpts(),
            p_compiler_instance->getPreprocessor(),
            var_template_specialization_decl);
  } else {
    var_template_specialization_range =
        var_template_specialization_decl->getSourceRange();
  }
  markClangValueDefined(var_template_specialization_range);

  ConstraintSatisfactionResult constraint_result;
  if (specialization_kind == clang::TSK_ImplicitInstantiation ||
      specialization_kind == clang::TSK_ExplicitInstantiationDeclaration ||
      specialization_kind == clang::TSK_ExplicitInstantiationDefinition) {
    llvm::SmallVector<clang::AssociatedConstraint, 4> constraints;
    const clang::NamedDecl *constraint_owner = nullptr;
    if (const clang::VarTemplatePartialSpecializationDecl *partial =
            llvm::dyn_cast<clang::VarTemplatePartialSpecializationDecl>(
                var_template_specialization_decl)) {
      partial->getAssociatedConstraints(constraints);
      constraint_owner = partial;
    } else if (clang::VarTemplateDecl *primary =
                   var_template_specialization_decl->getSpecializedTemplate()) {
      if (clang::TemplateParameterList *params =
              primary->getTemplateParameters()) {
        params->getAssociatedConstraints(constraints);
      }
      constraint_owner = primary;
    }

    if (constraint_owner != nullptr && !constraints.empty()) {
      const clang::TemplateArgumentList &constraint_args =
          specialization_is_partial ? *instantiation_args_ptr : *args_ptr;
      constraint_result = evaluateConstraintSatisfaction(
          constraint_owner, constraints, constraint_args,
          var_template_specialization_range);
    }
  }

  // This list is the declaration's source surface. Preserve written argument
  // locations and explicitness here; the complete semantic/instantiation list
  // is retained independently below in deducedTemplateArguments.
  SgTemplateArgumentPtrList tpl_args;
  if (args_as_written != nullptr) {
    for (const clang::TemplateArgumentLoc &arg_loc :
         args_as_written->arguments()) {
      appendTemplateArguments(tpl_args, arg_loc, true);
    }
  } else {
    for (const clang::TemplateArgument &arg : args) {
      appendTemplateArguments(tpl_args, arg, false);
    }
  }
  SageBuilder::setTemplateSpecializationArgumentsInDeclaration(var_decl,
                                                               &tpl_args);
  SgTemplateArgumentPtrList deduced_args;
  for (const clang::TemplateArgument &arg : instantiation_args) {
    appendTemplateArguments(deduced_args, arg, false);
  }
  var_decl->get_deducedTemplateArguments() = deduced_args;
  SageBuilder::setTemplateArgumentParents(var_decl);

  auto lookup_template_decl =
      [&](clang::Decl *key) -> SgTemplateVariableDeclaration * {
    if (key == nullptr) {
      return nullptr;
    }
    auto it = p_decl_translation_map.find(key);
    if (it != p_decl_translation_map.end()) {
      return isSgTemplateVariableDeclaration(it->second);
    }
    if (p_decl_translation_in_progress.find(key) !=
            p_decl_translation_in_progress.end() ||
        p_decl_translation_on_demand.find(key) !=
            p_decl_translation_on_demand.end()) {
      return nullptr;
    }
    SgNode *translated = TraverseOnDemand(key);
    return isSgTemplateVariableDeclaration(translated);
  };

  if (clang::VarTemplatePartialSpecializationDecl *partial =
          llvm::dyn_cast<clang::VarTemplatePartialSpecializationDecl>(
              var_template_specialization_decl)) {
    if (clang::TemplateParameterList *param_list =
            partial->getTemplateParameters()) {
      std::unique_ptr<SgTemplateParameterPtrList> params =
          translateTemplateParameterList(param_list, var_decl);
      if (params != nullptr) {
        var_decl->get_templateParameters() = *params;
        finalize_attached_template_parameters(var_decl);
      }
    }
  }

  // Record the specialized template declaration chosen by Clang.
  SgDeclarationStatement *specialized_template_decl = nullptr;
  clang::Decl *specialized_key = nullptr;
  auto specialized = readClangApiValueDefined([&]() {
    return var_template_specialization_decl->getSpecializedTemplateOrPartial();
  });
  if (auto *partial =
          specialized
              .dyn_cast<clang::VarTemplatePartialSpecializationDecl *>()) {
    specialized_key = partial;
  } else if (auto *primary = specialized.dyn_cast<clang::VarTemplateDecl *>()) {
    specialized_key = primary;
  }
  if (specialized_key != nullptr) {
    specialized_template_decl =
        lookupSgDeclarationForClangDecl(specialized_key,
                                        /*allow_on_demand=*/true);
  }
  if (specialized_template_decl != nullptr) {
    var_decl->set_specializedTemplateDeclaration(specialized_template_decl);
  } else if (specialized_key != nullptr) {
    linkSpecializedTemplateDeclaration(var_decl, specialized_key);
  }

  if (source_written_specialization) {
    applySourceRange(var_decl, var_template_specialization_range);
    applySourceRange(specialization_name, var_template_specialization_range);
    applySourceRange(specialization_definition,
                     var_template_specialization_range);
    if (init != nullptr && source_written_initializer) {
      if (source_init_expr == nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-template-specialization-"
                "initializer-source]: specialization=%s has an initializer "
                "without one exact Clang source expression\n",
                name.getString().c_str());
        ROSE_ABORT();
      }
      const clang::SourceRange initializer_range =
          computeInitializerLexicalRange(
              p_compiler_instance->getSourceManager(),
              var_template_specialization_range,
              source_init_expr->getSourceRange());
      applySourceRange(init, initializer_range);
    } else if (init != nullptr) {
      setSynthesizedFileInfo(init);
      mark_compiler_generated_frontend_specific(init);
      validate_semantic_provenance(
          init, true,
          "VisitVarTemplateSpecializationDecl:semantic-initializer");
    }
    require_complete_file_info_provenance(
        specialization_name,
        "VisitVarTemplateSpecializationDecl:initialized-name");
    require_complete_file_info_provenance(
        specialization_definition,
        "VisitVarTemplateSpecializationDecl:variable-definition");
    if (init != nullptr && source_written_initializer) {
      require_complete_file_info_provenance(
          init, "VisitVarTemplateSpecializationDecl:initializer");
    }
  } else {
    // An implicit instantiation owns semantic identity only.  Publish the
    // declaration shell and both variable components atomically here;
    // VisitDecl must never repair child provenance after the producer returns.
    setSynthesizedFileInfo(var_decl);
    setSynthesizedFileInfo(specialization_name);
    setSynthesizedFileInfo(specialization_definition);
    mark_compiler_generated_frontend_specific(var_decl);
    mark_compiler_generated_frontend_specific(specialization_name);
    mark_compiler_generated_frontend_specific(specialization_definition);
    if (init != nullptr) {
      setSynthesizedFileInfo(init);
      mark_compiler_generated_frontend_specific(init);
    }
    validate_semantic_provenance(
        var_decl, true,
        "VisitVarTemplateSpecializationDecl:semantic-declaration");
    validate_semantic_provenance(
        specialization_name, true,
        "VisitVarTemplateSpecializationDecl:semantic-initialized-name");
    validate_semantic_provenance(
        specialization_definition, true,
        "VisitVarTemplateSpecializationDecl:semantic-variable-definition");
    if (init != nullptr) {
      validate_semantic_provenance(
          init, true,
          "VisitVarTemplateSpecializationDecl:semantic-initializer");
    }
  }

  if (constraint_result.evaluated) {
    attachConstraintSatisfaction(var_decl, constraint_result);
  }
  if (specialization_kind == clang::TSK_ExplicitSpecialization) {
    var_decl->set_specialization(SgDeclarationStatement::e_specialization);
    const unsigned header_count =
        countWrittenExplicitTemplateSpecializationHeaders(
            var_template_specialization_decl);
    if (header_count == 0) {
      fprintf(
          stderr,
          "REX_FRONTEND_INVARIANT[variable-specialization-header]: "
          "explicit variable-template specialization=%s has no exact "
          "source-written empty template header\n",
          var_template_specialization_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }
    var_decl->set_explicitTemplateSpecializationHeaderCount(header_count);
  }
  SgTemplateInstantiationDirectiveStatement *explicit_instantiation_directive =
      nullptr;
  if (source_written_specialization && explicit_instantiation) {
    SgScopeStatement *directive_scope = resolveExplicitInstantiationSourceScope(
        explicit_instantiation_point, "variable",
        var_template_specialization_decl->getQualifiedNameAsString());
    explicit_instantiation_directive =
        build_and_publish_explicit_instantiation_directive(
            p_decl_attachment_session, var_decl, directive_scope,
            specialization_kind == clang::TSK_ExplicitInstantiationDeclaration,
            "VisitVarTemplateSpecializationDecl:explicit-instantiation");
    applySourceRange(explicit_instantiation_directive,
                     explicit_instantiation_directive_range);
    explicit_instantiation_directive->set_firstNondefiningDeclaration(
        explicit_instantiation_directive);
    explicit_instantiation_directive->set_definingDeclaration(
        explicit_instantiation_directive);
    insert_decl_in_scope_child_list_by_source_position(
        p_decl_attachment_session, explicit_instantiation_directive,
        directive_scope,
        "VisitVarTemplateSpecializationDecl:explicit-instantiation-order");
    if (var_decl->get_scope() != directive_scope ||
        specialization_name->get_scope() != scope ||
        explicit_instantiation_directive->get_scope() != directive_scope ||
        explicit_instantiation_directive->get_parent() != directive_scope ||
        var_decl->get_parent() != explicit_instantiation_directive) {
      fprintf(
          stderr,
          "REX_FRONTEND_INVARIANT[variable-template-explicit-"
          "instantiation-owner]: variable=%s lost its distinct initialized-"
          "name semantic scope or exact lexical directive owner "
          "variable-scope=%p name-semantic=%p expected-semantic=%p directive-"
          "scope=%p expected-lexical=%p directive-parent=%p variable-parent=%p "
          "expected-directive=%p\n",
          var_template_specialization_decl->getQualifiedNameAsString().c_str(),
          static_cast<void *>(var_decl->get_scope()),
          static_cast<void *>(specialization_name->get_scope()),
          static_cast<void *>(scope),
          static_cast<void *>(explicit_instantiation_directive->get_scope()),
          static_cast<void *>(directive_scope),
          static_cast<void *>(explicit_instantiation_directive->get_parent()),
          static_cast<void *>(var_decl->get_parent()),
          static_cast<void *>(explicit_instantiation_directive));
      ROSE_ABORT();
    }
  } else if (source_written_specialization) {
    publish_fresh_decl_in_scope_child_list(
        p_decl_attachment_session, var_decl, scope,
        "VisitVarTemplateSpecializationDecl:construction");
    ensureDeclInScopeChildList(var_decl, scope,
                               "VisitVarTemplateSpecializationDecl:ordering");
  } else {
    SageBuilder::attachAuxiliaryDeclaration(scope, var_decl);
    SgAuxiliaryDeclarationList *container =
        isSgAuxiliaryDeclarationList(var_decl->get_parent());
    if (container == nullptr || container->get_parent() != scope ||
        scope->get_auxiliary_declarations() != container ||
        var_decl->get_scope() != scope ||
        scope->statementExistsInScope(var_decl) ||
        std::count(container->get_declarations().begin(),
                   container->get_declarations().end(), var_decl) != 1) {
      std::cerr
          << "REX_FRONTEND_INVARIANT[variable-template-specialization-owner]: "
             "semantic specialization has no exact auxiliary scope owner"
          << std::endl;
      ROSE_ABORT();
    }
  }
  registerDeclarationSymbol(var_decl);

  SgNode *visited_declaration = var_decl;
  bool visit_res = false;
  {
    FinalizedDeclarationProvenanceGuard finalized_provenance_guard(
        p_declaration_with_finalized_provenance, var_decl);
    visit_res = VisitDeclaratorDecl(var_template_specialization_decl,
                                    &visited_declaration) &&
                res;
  }
  if (visited_declaration != var_decl) {
    std::cerr
        << "REX_FRONTEND_INVARIANT[variable-template-specialization-result]: "
           "generic declaration traversal replaced its exact producer result"
        << std::endl;
    ROSE_ABORT();
  }
  if (source_written_specialization) {
    if (!specialization_name->get_source_name_qualification_present()) {
      fprintf(
          stderr,
          "REX_FRONTEND_INVARIANT[variable-template-specialization-"
          "qualification]: specialization=%s has no exact declarator-id "
          "qualification decision\n",
          var_template_specialization_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }
    SourceQualification source_qualification;
    if (explicit_instantiation) {
      source_qualification = exactExpandedDeclaratorQualifier(
          explicit_instantiation_declaration_begin_index,
          explicit_instantiation_name_index, "variable",
          var_template_specialization_decl->getQualifiedNameAsString());
      clang::NestedNameSpecifierLoc clang_qualifier =
          markClangNestedNameSpecifierLocDefined(
              readClangApiValueDefined([&]() {
                return var_template_specialization_decl->getQualifierLoc();
              }));
      if (clang_qualifier) {
        clang::NestedNameSpecifier semantic_qualifier =
            markClangNestedNameSpecifierDefined(readClangApiValueDefined(
                [&]() { return clang_qualifier.getNestedNameSpecifier(); }));
        const int semantic_component_count =
            nestedNameSpecifierComponentCount(semantic_qualifier);
        const bool semantic_global =
            nestedNameSpecifierHasGlobal(semantic_qualifier);
        if (!semantic_qualifier || semantic_component_count <= 0 ||
            source_qualification.tokens.size() !=
                static_cast<size_t>(semantic_component_count) ||
            source_qualification.global != semantic_global) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[variable-template-explicit-"
                  "instantiation-qualification]: specialization=%s exact "
                  "expanded qualifier shape=%zu/global=%d disagrees with "
                  "Clang semantic shape=%d/global=%d\n",
                  var_template_specialization_decl->getQualifiedNameAsString()
                      .c_str(),
                  source_qualification.tokens.size(),
                  source_qualification.global ? 1 : 0, semantic_component_count,
                  semantic_global ? 1 : 0);
          ROSE_ABORT();
        }
      }
      if (!clang_qualifier &&
          (specialization_name->get_source_name_global_qualification() ||
           !specialization_name->get_source_name_qualification_tokens()
                .empty())) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-template-explicit-"
                "instantiation-qualification]: specialization=%s has a "
                "qualifier payload without a Clang qualifier location\n",
                var_template_specialization_decl->getQualifiedNameAsString()
                    .c_str());
        ROSE_ABORT();
      }
      specialization_name->set_source_name_global_qualification(
          source_qualification.global);
      specialization_name->get_source_name_qualification_tokens() =
          source_qualification.tokens;
      specialization_name->set_name_qualification_length(
          static_cast<int>(source_qualification.tokens.size()));
      specialization_name->set_global_qualification_required(
          source_qualification.global);
    } else {
      source_qualification.global =
          specialization_name->get_source_name_global_qualification();
      source_qualification.tokens =
          specialization_name->get_source_name_qualification_tokens();
    }
    var_decl->set_name_qualification_length(
        specialization_name->get_name_qualification_length());
    var_decl->set_global_qualification_required(
        specialization_name->get_global_qualification_required());
    preserveSourceNameQualification(
        var_decl, source_qualification,
        "VisitVarTemplateSpecializationDecl:source-name-qualification");
  }
  *node = explicit_instantiation_directive != nullptr
              ? static_cast<SgNode *>(explicit_instantiation_directive)
              : static_cast<SgNode *>(var_decl);

  return visit_res;
}

bool ClangToSageTranslator::VisitVarTemplatePartialSpecializationDecl(
    clang::VarTemplatePartialSpecializationDecl
        *var_template_partial_specialization_decl,
    SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr
      << "ClangToSageTranslator::VisitVarTemplatePartialSpecializationDecl"
      << std::endl;
#endif
  bool res = true;

  if (var_template_partial_specialization_decl == nullptr ||
      var_template_partial_specialization_decl->isInvalidDecl()) {
    *node = nullptr;
    return false;
  }

  // ROOT CAUSE FIX: Model partial specializations with template parameters
  // and specialization arguments instead of treating them as instantiations.

  SgName name(var_template_partial_specialization_decl->getNameAsString());
  if (name.getString().empty()) {
    std::cerr << "REX_FRONTEND_INVARIANT[variable-template-partial-name]: "
                 "partial specialization has no name"
              << std::endl;
    ROSE_ABORT();
  }

  clang::DeclContext *decl_context =
      var_template_partial_specialization_decl->getDeclContext();
  if (decl_context == nullptr) {
    std::cerr << "REX_FRONTEND_INVARIANT[variable-template-partial-scope]: "
                 "null declaration context"
              << std::endl;
    ROSE_ABORT();
  }
  SgScopeStatement *scope = resolveScopeFromDeclContext(decl_context);
  if (scope == nullptr) {
    std::cerr << "REX_FRONTEND_INVARIANT[variable-template-partial-scope]: "
                 "declaration context has no exact translated scope"
              << std::endl;
    ROSE_ABORT();
  }

  SgType *construction_type = SageBuilder::buildUnknownType();
  ASSERT_not_null(construction_type);
  SgTemplateVariableDeclaration *var_decl =
      SageBuilder::buildTemplateVariableDeclaration_nfi(
          name, construction_type, nullptr, scope,
          SageBuilder::template_variable_entity_kind::specialization);
  ASSERT_not_null(var_decl);
  normalize_standalone_template_variable_declaration(var_decl);

  auto map_owner = [&](clang::Decl *key) {
    if (key == nullptr) {
      return;
    }
    auto [it, inserted] = p_decl_translation_map.emplace(key, var_decl);
    if (!inserted && it->second != var_decl) {
      std::cerr << "REX_FRONTEND_INVARIANT[variable-template-partial-owner]: "
                   "Clang declaration already maps to a different AST node"
                << std::endl;
      ROSE_ABORT();
    }
  };
  map_owner(var_template_partial_specialization_decl);
  map_owner(var_template_partial_specialization_decl->getCanonicalDecl());

  var_decl->set_specialization(
      SgDeclarationStatement::e_partial_specialization);
  var_decl->set_unparse_template_ast(shouldForceTemplateAstUnparse(
      p_compiler_instance, var_template_partial_specialization_decl,
      p_sage_source_file, /*on_demand_translation=*/false,
      var_template_partial_specialization_decl
          ->getTemplateSpecializationKind()));

  clang::TemplateParameterList *param_list =
      var_template_partial_specialization_decl->getTemplateParameters();
  if (param_list == nullptr) {
    std::cerr << "REX_FRONTEND_INVARIANT[variable-template-partial-params]: "
                 "partial specialization has no template parameter list"
              << std::endl;
    ROSE_ABORT();
  }
  std::unique_ptr<SgTemplateParameterPtrList> params =
      translateTemplateParameterList(param_list, var_decl);
  ASSERT_not_null(params);
  var_decl->get_templateParameters() = *params;
  finalize_attached_template_parameters(var_decl);

  param_list = markClangTemplateParameterListDefined(param_list);
  ClangTemplateParameterNameMap exact_partial_parameter_names =
      collectExactTemplateParameterNames(
          param_list, "variable template partial specialization");
  p_exact_template_parameter_name_stack.push_back(
      std::move(exact_partial_parameter_names));
  p_template_parameter_surface_stack.push_back(
      {param_list, &var_decl->get_templateParameters(), var_decl});
  struct VarTemplatePartialParameterSurfaceGuard {
    ClangTemplateParameterNameContextStack &name_stack;
    std::vector<TemplateParameterSurfaceFrame> &surface_stack;
    const clang::TemplateParameterList *clang_parameters;
    const SgTemplateParameterPtrList *sage_parameters;
    SgDeclarationStatement *owner;
    ~VarTemplatePartialParameterSurfaceGuard() {
      if (name_stack.empty() || surface_stack.empty() ||
          surface_stack.back().clang_parameters != clang_parameters ||
          surface_stack.back().sage_parameters != sage_parameters ||
          surface_stack.back().owner != owner) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[variable-template-partial-parameter-"
                "surface]: declaration body lost its exact active parameter "
                "surface\n");
        ROSE_ABORT();
      }
      surface_stack.pop_back();
      name_stack.pop_back();
    }
  } var_template_partial_parameter_surface_guard{
      p_exact_template_parameter_name_stack, p_template_parameter_surface_stack,
      param_list, &var_decl->get_templateParameters(), var_decl};

  SgType *type = buildTypeFromQualifiedType(
      var_template_partial_specialization_decl->getType());
  if (type == nullptr || isSgTypeUnknown(type) != nullptr) {
    std::cerr << "REX_FRONTEND_INVARIANT[variable-template-partial-type]: "
                 "partial specialization has no exact translated type"
              << std::endl;
    ROSE_ABORT();
  }
  ASSERT_require(var_decl->get_variables().size() == 1);
  SgInitializedName *initialized_name = var_decl->get_variables().front();
  ASSERT_not_null(initialized_name);
  initialized_name->set_type(type);

  SgInitializer *partial_initializer = nullptr;
  clang::Expr *partial_init_expr = nullptr;
  if (var_template_partial_specialization_decl->hasInit()) {
    clang::Expr *init_expr =
        var_template_partial_specialization_decl->getInit();
    if (init_expr == nullptr) {
      std::cerr << "REX_FRONTEND_INVARIANT[variable-template-partial-init]: "
                   "declaration reports an initializer but has no expression"
                << std::endl;
      ROSE_ABORT();
    }
    partial_init_expr = init_expr;
    SgNode *tmp_node = Traverse(init_expr);
    if (SgExpression *translated_expr = isSgExpression(tmp_node)) {
      tmp_node = prepareExpressionForAttachment(translated_expr);
      if (tmp_node == nullptr) {
        std::cerr << "REX_FRONTEND_INVARIANT[variable-template-partial-init-"
                     "owner]: initializer could not produce an exact owned "
                     "expression tree"
                  << std::endl;
        ROSE_ABORT();
      }
    }
    SgInitializer *init = isSgInitializer(tmp_node);
    if (init == nullptr) {
      if (SgExpression *expr = isSgExpression(tmp_node)) {
        init = SageBuilder::buildAssignInitializer_nfi(expr, type);
      }
    }
    if (init == nullptr) {
      std::cerr << "REX_FRONTEND_INVARIANT[variable-template-partial-init]: "
                   "initializer did not translate to an expression"
                << std::endl;
      ROSE_ABORT();
    }
    var_decl->reset_initializer(init);
    partial_initializer = init;
    if (init->get_parent() == nullptr) {
      init->set_parent(initialized_name);
    }
    ASSERT_require(init->get_parent() == initialized_name);
  }

  SgTemplateArgumentPtrList spec_args;
  if (const clang::ASTTemplateArgumentListInfo *args_written =
          var_template_partial_specialization_decl
              ->getTemplateArgsAsWritten()) {
    for (const clang::TemplateArgumentLoc &arg_loc :
         args_written->arguments()) {
      appendTemplateArguments(spec_args, arg_loc, true);
    }
  } else {
    const clang::TemplateArgumentList &args =
        var_template_partial_specialization_decl->getTemplateArgs();
    for (unsigned i = 0; i < args.size(); ++i) {
      appendTemplateArguments(spec_args, args.get(i), false);
    }
  }
  SageBuilder::setTemplateSpecializationArgumentsInDeclaration(var_decl,
                                                               &spec_args);

  if (clang::TemplateParameterList *params =
          var_template_partial_specialization_decl->getTemplateParameters()) {
    if (const clang::Expr *requires_expr = params->getRequiresClause()) {
      if (SgExpression *sg_requires =
              translateConstraintExpression(requires_expr)) {
        var_decl->set_requiresClause(sg_requires);
        sg_requires->set_parent(var_decl);
      }
    }
  }

  const clang::SourceRange partial_declaration_range =
      var_template_partial_specialization_decl->getSourceRange();
  SgVariableDefinition *partial_definition = initialized_name->get_definition();
  if (!partial_declaration_range.isValid() ||
      initialized_name->get_parent() != var_decl ||
      initialized_name->get_scope() != scope ||
      initialized_name->get_declptr() != var_decl ||
      partial_definition == nullptr ||
      partial_definition->get_vardefn() != initialized_name ||
      partial_definition->get_parent() != initialized_name ||
      (partial_initializer != nullptr &&
       partial_initializer->get_parent() != initialized_name)) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[variable-template-partial-component-"
            "owner]: partial specialization=%s has malformed source "
            "component ownership\n",
            name.getString().c_str());
    ROSE_ABORT();
  }
  applySourceRange(initialized_name, partial_declaration_range);
  applySourceRange(partial_definition, partial_declaration_range);
  if (partial_initializer != nullptr) {
    if (partial_init_expr == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[variable-template-partial-initializer-"
              "source]: partial specialization=%s has no exact initializer "
              "expression\n",
              name.getString().c_str());
      ROSE_ABORT();
    }
    const clang::SourceRange initializer_range = computeInitializerLexicalRange(
        p_compiler_instance->getSourceManager(), partial_declaration_range,
        partial_init_expr->getSourceRange());
    applySourceRange(partial_initializer, initializer_range);
  }
  require_complete_file_info_provenance(
      initialized_name,
      "VisitVarTemplatePartialSpecializationDecl:initialized-name");
  require_complete_file_info_provenance(
      partial_definition,
      "VisitVarTemplatePartialSpecializationDecl:variable-definition");
  if (partial_initializer != nullptr) {
    require_complete_file_info_provenance(
        partial_initializer,
        "VisitVarTemplatePartialSpecializationDecl:initializer");
  }

  // Complete the exact declaration and component provenance before exposing
  // the specialization through either the lexical scope or its symbol table.
  applySourceRange(var_decl, partial_declaration_range);
  publish_fresh_decl_in_scope_child_list(
      p_decl_attachment_session, var_decl, scope,
      "VisitVarTemplatePartialSpecializationDecl:construction");
  ensureDeclInScopeChildList(
      var_decl, scope, "VisitVarTemplatePartialSpecializationDecl:ordering");
  registerDeclarationSymbol(var_decl);

  *node = var_decl;
  FinalizedDeclarationProvenanceGuard finalized_provenance_guard(
      p_declaration_with_finalized_provenance, var_decl);
  return VisitDeclaratorDecl(var_template_partial_specialization_decl, node) &&
         res;
}

bool ClangToSageTranslator::VisitEnumConstantDecl(
    clang::EnumConstantDecl *enum_constant_decl, SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitEnumConstantDecl" << std::endl;
#endif
  bool res = true;

  enum_constant_decl = llvm::cast<clang::EnumConstantDecl>(
      markClangDeclObjectDefinedByKind(enum_constant_decl));

  if (enum_constant_decl == nullptr ||
      !enum_constant_decl->getDeclName().isIdentifier()) {
    std::cerr << "REX_FRONTEND_INVARIANT[enumerator-name]: enum constant has "
                 "no identifier"
              << std::endl;
    ROSE_ABORT();
  }
  SgName name(enum_constant_decl->getNameAsString());

  clang::DeclContext *scope_context = enum_constant_decl->getDeclContext();
  clang::EnumDecl *enum_context =
      llvm::dyn_cast<clang::EnumDecl>(scope_context);
  enum_context = markClangSpecificDeclDefined(enum_context);
  if (enum_context == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enumerator-owner]: '%s' has no exact "
            "Clang enum declaration context\n",
            enum_constant_decl->getNameAsString().c_str());
    ROSE_ABORT();
  }

  // Resolve the semantic enum identity before publishing the enumerator.
  // A DeclRefExpr can request a system-header enumerator before the normal
  // DeclContext walk reaches its enum.  Publishing an unowned placeholder in
  // that state lets the on-demand enum producer observe a cache entry with no
  // source role or semantic owner.  The enum declaration is the acyclic root
  // of this construction: VisitEnumDecl publishes its exact declaration shell
  // before traversing any constants, so resolving that shell first is safe.
  SgEnumDeclaration *owner_enum_decl = nullptr;
  auto find_translated_enum_decl =
      [&](clang::EnumDecl *key) -> SgEnumDeclaration * {
    if (key == nullptr) {
      return nullptr;
    }
    auto it = p_decl_translation_map.find(key);
    return it != p_decl_translation_map.end() ? isSgEnumDeclaration(it->second)
                                              : nullptr;
  };

  owner_enum_decl = find_translated_enum_decl(enum_context->getDefinition());
  if (owner_enum_decl == nullptr) {
    owner_enum_decl = find_translated_enum_decl(enum_context);
  }
  if (owner_enum_decl == nullptr) {
    owner_enum_decl =
        find_translated_enum_decl(enum_context->getCanonicalDecl());
  }
  if (owner_enum_decl == nullptr) {
    clang::EnumDecl *owner_key = enum_context->getDefinition();
    if (owner_key == nullptr) {
      owner_key = enum_context;
    }
    owner_enum_decl = isSgEnumDeclaration(
        lookupSgDeclarationForClangDecl(owner_key, /*allow_on_demand=*/true));
    if (owner_enum_decl == nullptr) {
      owner_enum_decl = find_translated_enum_decl(enum_context);
    }
    if (owner_enum_decl == nullptr) {
      owner_enum_decl =
          find_translated_enum_decl(enum_context->getCanonicalDecl());
    }
  }
  if (owner_enum_decl == nullptr) {
    std::cerr << "REX_FRONTEND_INVARIANT[enumerator-owner]: '"
              << enum_constant_decl->getNameAsString()
              << "' has no translated owning enum declaration" << std::endl;
    ROSE_ABORT();
  }
  if (SgEnumDeclaration *defining_decl =
          isSgEnumDeclaration(owner_enum_decl->get_definingDeclaration())) {
    owner_enum_decl = defining_decl;
  }

  SgScopeStatement *owner_semantic_scope = owner_enum_decl->get_scope();
  SgScopeStatement *scope = normalizeNamespaceScope(owner_semantic_scope);
  auto structural_global_owner = [](SgNode *node) -> SgGlobal * {
    std::unordered_set<SgNode *> visited;
    for (SgNode *current = node; current != nullptr;
         current = current->get_parent()) {
      if (!visited.insert(current).second) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[enumerator-owner]: cyclic structural "
                "owner chain\n");
        ROSE_ABORT();
      }
      if (SgGlobal *global = isSgGlobal(current)) {
        return global;
      }
    }
    return nullptr;
  };
  SgGlobal *owner_translation_unit =
      structural_global_owner(owner_semantic_scope);
  SgGlobal *symbol_translation_unit = structural_global_owner(scope);
  const bool exact_fragment_owner =
      owner_semantic_scope != nullptr && scope != nullptr &&
      owner_semantic_scope != scope &&
      SgScopeStatement::isEquivalentScope(owner_semantic_scope, scope) &&
      owner_enum_decl->get_parent() == owner_semantic_scope &&
      declaration_has_real_source(owner_enum_decl) &&
      owner_translation_unit != nullptr && symbol_translation_unit != nullptr &&
      owner_translation_unit != symbol_translation_unit;
  if (scope == nullptr ||
      (owner_semantic_scope != scope && !exact_fragment_owner)) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enumerator-owner]: '%s' owner=%p "
            "semantic-scope=%p symbol-scope=%p has neither one exact "
            "canonical scope nor one distinct translation-unit fragment\n",
            enum_constant_decl->getNameAsString().c_str(),
            static_cast<void *>(owner_enum_decl),
            static_cast<void *>(owner_semantic_scope),
            static_cast<void *>(scope));
    ROSE_ABORT();
  }

  // A typed owner is the physical source surface for the complete inline enum,
  // including its enumerators.  Header-suppression policy applies to the owner
  // declaration after it adopts the enum; it must not turn the enum's children
  // into semantic-only nodes while that exact construction transaction is
  // active.
  // Once a source enum has been adopted by its exact declarator owner, header
  // output policy must not retrospectively turn its already-published source
  // enumerators into semantic-only identities.  The declarator's typed edge
  // is the durable source-grammar ownership evidence after the construction
  // frame has closed.
  const bool declarator_owned_source_enum =
      is_hidden_declarator_owned_tag_decl(owner_enum_decl) ||
      (!owner_enum_decl->get_isAutonomousDeclaration() &&
       declaration_has_real_source(owner_enum_decl));
  const bool source_enum_constant_owner =
      activeTypedOwnerTagConstructionScope(enum_context) != nullptr ||
      declarator_owned_source_enum ||
      declaration_has_exact_source_surface_ownership(owner_enum_decl);
  const bool semantic_enum_constant =
      !source_enum_constant_owner &&
      enumHasSemanticOnlyOutputOwnership(enum_context, p_compiler_instance,
                                         p_sage_source_file,
                                         p_sage_preprocessor_recorder);
  if (!source_enum_constant_owner && !semantic_enum_constant) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enumerator-owner]: '%s' owner=%p/%s has "
            "neither one exact source surface nor one semantic-only enum "
            "role\n",
            enum_constant_decl->getNameAsString().c_str(),
            static_cast<void *>(owner_enum_decl),
            owner_enum_decl->class_name().c_str());
    ROSE_ABORT();
  }
  if (semantic_enum_constant &&
      !declaration_has_exact_auxiliary_ownership(owner_enum_decl) &&
      p_decl_translation_in_progress.find(enum_context) ==
          p_decl_translation_in_progress.end() &&
      p_decl_translation_in_progress.find(enum_context->getDefinition()) ==
          p_decl_translation_in_progress.end()) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enumerator-owner]: '%s' semantic-only "
            "enum owner is neither under exact construction nor published "
            "through an auxiliary owner\n",
            enum_constant_decl->getNameAsString().c_str());
    ROSE_ABORT();
  }
  const SgInitializedName::enum_constant_source_ownership_enum source_role =
      semantic_enum_constant
          ? SgInitializedName::e_enum_constant_semantic_only
          : exactEnumConstantSourceRole(
                enum_constant_decl,
                exactExpandedEnumBodyFile(enum_context, p_compiler_instance),
                p_compiler_instance);

  // Resolving an absent owner above can recursively complete the enum and this
  // exact constant.  Consume only that completed identity; never resume the
  // outer producer and manufacture a duplicate enumerator.
  auto completed = p_decl_translation_map.find(enum_constant_decl);
  if (completed != p_decl_translation_map.end()) {
    SgInitializedName *completed_name = isSgInitializedName(completed->second);
    if (completed_name == nullptr || completed_name->get_scope() != scope ||
        completed_name->get_parent() != owner_enum_decl ||
        completed_name->get_declptr() != owner_enum_decl ||
        completed_name->get_enum_constant_source_ownership() != source_role ||
        std::count(owner_enum_decl->get_enumerators().begin(),
                   owner_enum_decl->get_enumerators().end(),
                   completed_name) != 1) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[enum-constant-publication]: '%s' "
              "recursive owner construction published an incomplete or "
              "foreign enumerator identity\n",
              enum_constant_decl->getNameAsString().c_str());
      ROSE_ABORT();
    }
    *node = completed_name;
    return true;
  }

  // Preserve Clang's exact enumerator type. Unscoped enumerators can expose an
  // integer type while scoped enumerators expose their enum type, so semantic
  // ownership is recovered independently from that type above.
  clang::QualType enum_constant_type =
      markClangQualTypeDefined(readClangApiValueDefined(
          [&]() { return enum_constant_decl->getType(); }));
  SgType *type = buildTypeFromQualifiedType(enum_constant_type);
  if (type == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enumerator-type]: '%s' has no exact Sage "
            "type\n",
            enum_constant_decl->getNameAsString().c_str());
    ROSE_ABORT();
  }

  SgInitializedName *init_name =
      SageBuilder::buildInitializedName(name, type, nullptr);
  init_name->set_scope(scope);
  init_name->set_parent(owner_enum_decl);
  init_name->set_declptr(owner_enum_decl);
  init_name->set_enum_constant_source_ownership(source_role);
  if (semantic_enum_constant) {
    mark_compiler_generated_frontend_specific(init_name);
  }
  if (!p_decl_translation_map.emplace(enum_constant_decl, init_name).second) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enum-constant-publication]: '%s' acquired "
            "a competing translation before exact construction completed\n",
            enum_constant_decl->getNameAsString().c_str());
    ROSE_ABORT();
  }

  SgInitializer *init = nullptr;

  clang::Expr *init_expr =
      markClangExprObjectDefinedByClass(readClangApiValueDefined(
          [&]() { return enum_constant_decl->getInitExpr(); }));
  if (init_expr != nullptr) {
    clang::Expr *source_init_expr =
        markClangExprObjectDefinedByClass(readClangApiValueDefined(
            [&]() { return init_expr->IgnoreUnlessSpelledInSource(); }));
    if (!semantic_enum_constant &&
        (source_init_expr == nullptr ||
         !source_init_expr->getSourceRange().isValid())) {
      std::cerr << "REX_FRONTEND_INVARIANT[enumerator-initializer-source]: '"
                << enum_constant_decl->getNameAsString()
                << "' has a semantic initializer but no exact written "
                   "expression"
                << std::endl;
      ROSE_ABORT();
    }
    if (semantic_enum_constant) {
      if (source_init_expr == nullptr) {
        source_init_expr = init_expr;
      }
      ++p_semantic_expression_subtree_depth;
      ++p_canonical_generated_literal_depth;
    }
    SgNode *tmp_expr = Traverse(source_init_expr);
    if (semantic_enum_constant) {
      if (p_semantic_expression_subtree_depth == 0 ||
          p_canonical_generated_literal_depth == 0) {
        std::cerr
            << "REX_FRONTEND_INVARIANT[enumerator-initializer-semantic]: '"
            << enum_constant_decl->getNameAsString()
            << "' semantic expression translation depth underflowed"
            << std::endl;
        ROSE_ABORT();
      }
      --p_canonical_generated_literal_depth;
      --p_semantic_expression_subtree_depth;
    }
    SgExpression *expr = isSgExpression(tmp_expr);
    if (expr == nullptr) {
      std::cerr << "REX_FRONTEND_INVARIANT[enumerator-initializer]: '"
                << enum_constant_decl->getNameAsString()
                << "' did not translate to an expression" << std::endl;
      ROSE_ABORT();
    }

    // EnumConstantDecl keeps the written initializer separately from Clang's
    // evaluated ConstantExpr wrapper.  The Sage originalExpressionTree owns
    // the spelling, so record the wrapper's semantic role on that exact tree
    // instead of manufacturing a second expression surface.
    clang::Expr *semantic_init = init_expr;
    while (auto *implicit =
               llvm::dyn_cast<clang::ImplicitCastExpr>(semantic_init)) {
      semantic_init = markClangExprObjectDefinedByClass(
          readClangApiValueDefined([&]() { return implicit->getSubExpr(); }));
    }
    if (auto *constant =
            llvm::dyn_cast_or_null<clang::ConstantExpr>(semantic_init)) {
      clang::Expr *constant_source =
          markClangExprObjectDefinedByClass(readClangApiValueDefined([&]() {
            return constant->getSubExpr()->IgnoreUnlessSpelledInSource();
          }));
      if (constant_source != source_init_expr) {
        std::cerr << "REX_FRONTEND_INVARIANT[enumerator-constant-wrapper]: '"
                  << enum_constant_decl->getNameAsString()
                  << "' semantic ConstantExpr does not wrap its exact written "
                     "initializer"
                  << std::endl;
        ROSE_ABORT();
      }
      expr->add_semantic_wrapper(SgExpression::e_constant_evaluated_wrapper);
    }

    const llvm::APSInt &clang_semantic_value = enum_constant_decl->getInitVal();
    long long semantic_value = 0;
    if (clang_semantic_value.isSigned()) {
      if (!clang_semantic_value.isSignedIntN(64)) {
        std::cerr << "REX_FRONTEND_INVARIANT[enumerator-value-width]: '"
                  << enum_constant_decl->getNameAsString()
                  << "' signed value exceeds the SgEnumVal 64-bit domain"
                  << std::endl;
        ROSE_ABORT();
      }
      semantic_value = clang_semantic_value.getSExtValue();
    } else {
      if (!clang_semantic_value.isIntN(64)) {
        std::cerr << "REX_FRONTEND_INVARIANT[enumerator-value-width]: '"
                  << enum_constant_decl->getNameAsString()
                  << "' unsigned value exceeds the SgEnumVal 64-bit domain"
                  << std::endl;
        ROSE_ABORT();
      }
      semantic_value =
          static_cast<long long>(clang_semantic_value.getZExtValue());
    }
    SgEnumVal *enum_value =
        SageBuilder::buildEnumVal_nfi(semantic_value, owner_enum_decl, name);
    ROSE_ASSERT(enum_value != nullptr);
    enum_value->set_literal_spelling_form(
        SgValueExp::e_literal_canonical_generated);
    enum_value->set_originalExpressionTree(expr);
    expr->set_parent(enum_value);

    init = SageBuilder::buildAssignInitializer_nfi(enum_value, type);
    // SgEnumVal carries Clang's evaluated integer value; the exact written
    // spelling belongs exclusively to originalExpressionTree.  Publishing the
    // semantic wrapper as source-spelled creates two competing token owners
    // and makes non-literal enumerator initializers appear to have fabricated
    // literal spelling.
    SageBuilder::initializeSemanticExpressionSourceProvenance(enum_value);
    if (semantic_enum_constant) {
      setSynthesizedFileInfo(init);
    } else {
      clang::SourceRange enum_constant_range = readClangApiValueDefined(
          [&]() { return enum_constant_decl->getSourceRange(); });
      clang::SourceRange init_expr_range = readClangApiValueDefined(
          [&]() { return source_init_expr->getSourceRange(); });
      clang::SourceRange init_range = computeInitializerLexicalRange(
          p_compiler_instance->getSourceManager(), enum_constant_range,
          init_expr_range);
      applySourceRange(init, init_range);
    }
  }

  // Complete the already-owned enum constant with its optional initializer.
  ASSERT_require(init == nullptr || init->get_parent() == nullptr);
  init_name->set_initializer(init);
  if (init != nullptr) {
    init->set_parent(init_name);
  }

  if (scope != nullptr &&
      scope->find_symbol_from_declaration(init_name) == nullptr) {
    SgEnumFieldSymbol *symbol = new SgEnumFieldSymbol(init_name);
    // The enum constant is now fully constructed; publish its fresh symbol
    // exactly once in the enum's semantic scope.
    attachSymbolToExactScope(symbol, scope);
  }

  *node = init_name;
  preserveExplicitInitializedNameQualifier(
      init_name, clang::NestedNameSpecifierLoc(), p_compiler_instance,
      "VisitEnumConstantDecl:name");
  bool visit_res = false;
  if (semantic_enum_constant) {
    FinalizedDeclarationProvenanceGuard finalized_provenance_guard(
        p_declaration_with_finalized_provenance, init_name);
    visit_res = VisitValueDecl(enum_constant_decl, node) && res;
  } else {
    visit_res = VisitValueDecl(enum_constant_decl, node) && res;
  }
  if (visit_res &&
      (init_name->get_scope() != scope ||
       init_name->get_parent() != owner_enum_decl ||
       init_name->get_declptr() != owner_enum_decl ||
       init_name->get_enum_constant_source_ownership() != source_role)) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[enum-constant-publication]: '%s' changed "
            "its construction-time semantic owner or source role\n",
            enum_constant_decl->getNameAsString().c_str());
    ROSE_ABORT();
  }
  if (visit_res && semantic_enum_constant) {
    validate_semantic_provenance(init_name, true,
                                 "VisitEnumConstantDecl:semantic-owner");
  }
  return visit_res;
}

bool ClangToSageTranslator::VisitIndirectFieldDecl(
    clang::IndirectFieldDecl *indirect_field_decl, SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitIndirectFieldDecl" << std::endl;
#endif
  indirect_field_decl = llvm::cast<clang::IndirectFieldDecl>(
      markClangDeclObjectDefinedByKind(indirect_field_decl));
  if (indirect_field_decl == nullptr || node == nullptr ||
      !indirect_field_decl->getDeclName().isIdentifier()) {
    std::cerr << "REX_FRONTEND_INVARIANT[indirect-field-declaration]: "
                 "indirect field has no exact identifier"
              << std::endl;
    ROSE_ABORT();
  }

  if (auto existing = p_decl_translation_map.find(indirect_field_decl);
      existing != p_decl_translation_map.end()) {
    SgVariableDeclaration *injected_decl =
        isSgVariableDeclaration(existing->second);
    SgScopeStatement *expected_scope =
        resolveScopeFromDeclContext(indirect_field_decl->getDeclContext());
    SgScopeStatement *owner =
        injected_decl != nullptr
            ? validate_exact_auxiliary_owner(
                  injected_decl, "VisitIndirectFieldDecl:cached-owner")
            : nullptr;
    if (injected_decl == nullptr || expected_scope == nullptr ||
        owner != expected_scope || injected_decl->get_variables().size() != 1 ||
        injected_decl->get_variables().front() == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[indirect-field-declaration]: cached "
              "declaration=%p for '%s' lacks its exact semantic identity\n",
              static_cast<void *>(existing->second),
              indirect_field_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }
    SgInitializedName *injected_name = injected_decl->get_variables().front();
    SgSymbol *symbol = owner->find_symbol_from_declaration(injected_name);
    if (isSgVariableSymbol(symbol) == nullptr ||
        symbol->get_symbol_basis() != injected_name ||
        symbol->get_parent() != owner->get_symbol_table()) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[indirect-field-declaration]: cached "
              "declaration=%p for '%s' lacks its exact variable symbol\n",
              static_cast<void *>(injected_decl),
              indirect_field_decl->getQualifiedNameAsString().c_str());
      ROSE_ABORT();
    }
    validate_semantic_provenance(injected_decl, true,
                                 "VisitIndirectFieldDecl:cached-declaration");
    validate_semantic_provenance(injected_name, true,
                                 "VisitIndirectFieldDecl:cached-name");
    if (SgVariableDefinition *definition = injected_decl->get_definition()) {
      validate_semantic_provenance(definition, true,
                                   "VisitIndirectFieldDecl:cached-definition");
    }
    *node = injected_decl;
    FinalizedDeclarationProvenanceGuard finalized_provenance_guard(
        p_declaration_with_finalized_provenance, injected_decl);
    return VisitValueDecl(indirect_field_decl, node);
  }

  SgScopeStatement *owner_scope =
      resolveScopeFromDeclContext(indirect_field_decl->getDeclContext());
  if (owner_scope == nullptr) {
    std::cerr << "REX_FRONTEND_INVARIANT[indirect-field-declaration]: '"
              << indirect_field_decl->getQualifiedNameAsString()
              << "' has no exact injected declaration scope" << std::endl;
    ROSE_ABORT();
  }

  const SgName name(indirect_field_decl->getNameAsString());
  if (SgVariableSymbol *existing_symbol =
          owner_scope->lookup_variable_symbol(name)) {
    std::cerr << "REX_FRONTEND_INVARIANT[indirect-field-declaration]: '"
              << indirect_field_decl->getQualifiedNameAsString()
              << "' collides with an already-published Sage variable symbol="
              << existing_symbol << std::endl;
    ROSE_ABORT();
  }

  SgType *type = buildTypeFromQualifiedType(indirect_field_decl->getType());
  if (type == nullptr || SageInterface::containsUnknownType(type)) {
    std::cerr << "REX_FRONTEND_INVARIANT[indirect-field-declaration]: '"
              << indirect_field_decl->getQualifiedNameAsString()
              << "' has no exact translated type" << std::endl;
    ROSE_ABORT();
  }

  // Clang materializes an IndirectFieldDecl for the entity injected through
  // each anonymous struct/union layer.  It is a real lookup entity but has no
  // separate source declaration.  Its exact DeclContext can be a class,
  // namespace, or translation unit (namespace-scope anonymous unions inject
  // their members into that enclosing scope).  Publish a source-hidden Sage
  // declaration in that exact semantic owner so references bind there rather
  // than to the nested anonymous aggregate's physical FieldDecl.
  SgVariableDeclaration *injected_decl =
      SageBuilder::buildSemanticAuxiliaryVariableDeclaration(
          name, type, nullptr, owner_scope);
  if (injected_decl == nullptr || injected_decl->get_variables().size() != 1 ||
      injected_decl->get_variables().front() == nullptr) {
    std::cerr << "REX_FRONTEND_INVARIANT[indirect-field-declaration]: failed "
                 "to build an exact injected member owner for '"
              << indirect_field_decl->getQualifiedNameAsString() << "'"
              << std::endl;
    ROSE_ABORT();
  }
  SgInitializedName *injected_name = injected_decl->get_variables().front();
  if (injected_decl->get_scope() != owner_scope ||
      injected_decl->get_parent() !=
          owner_scope->get_auxiliary_declarations()) {
    std::cerr << "REX_FRONTEND_INVARIANT[indirect-field-declaration]: '"
              << indirect_field_decl->getQualifiedNameAsString()
              << "' did not acquire its exact auxiliary semantic owner"
              << std::endl;
    ROSE_ABORT();
  }
  preserveExplicitInitializedNameQualifier(
      injected_name, clang::NestedNameSpecifierLoc(), p_compiler_instance,
      "VisitIndirectFieldDecl:name");
  validate_semantic_provenance(injected_decl, true,
                               "VisitIndirectFieldDecl:semantic-declaration");
  validate_semantic_provenance(injected_name, true,
                               "VisitIndirectFieldDecl:semantic-name");
  if (SgVariableDefinition *definition = injected_decl->get_definition()) {
    validate_semantic_provenance(definition, true,
                                 "VisitIndirectFieldDecl:semantic-definition");
  }
  SgSymbol *symbol = owner_scope->find_symbol_from_declaration(injected_name);
  if (isSgVariableSymbol(symbol) == nullptr ||
      symbol->get_symbol_basis() != injected_name ||
      symbol->get_parent() != owner_scope->get_symbol_table()) {
    std::cerr << "REX_FRONTEND_INVARIANT[indirect-field-declaration]: '"
              << indirect_field_decl->getQualifiedNameAsString()
              << "' did not publish an exact Sage variable symbol" << std::endl;
    ROSE_ABORT();
  }

  p_decl_translation_map[indirect_field_decl] = injected_decl;
  *node = injected_decl;
  FinalizedDeclarationProvenanceGuard finalized_provenance_guard(
      p_declaration_with_finalized_provenance, injected_decl);
  return VisitValueDecl(indirect_field_decl, node);
}

bool ClangToSageTranslator::VisitUnresolvedUsingValueDecl(
    clang::UnresolvedUsingValueDecl *unresolved_using_value_decl,
    SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitUnresolvedUsingValueDecl"
            << std::endl;
#endif
  bool res = true;
  unresolved_using_value_decl =
      llvm::dyn_cast_or_null<clang::UnresolvedUsingValueDecl>(
          markClangDeclObjectDefinedByKind(unresolved_using_value_decl));
  if (unresolved_using_value_decl == nullptr || node == nullptr) {
    fprintf(stderr, "REX_FRONTEND_INVARIANT[using-terminal-name]: "
                    "UnresolvedUsingValueDecl translation requires exact Clang "
                    "input and Sage output\n");
    ROSE_ABORT();
  }

  clang::DeclContext *using_context =
      markClangDeclContextObjectDefined(readClangApiValueDefined(
          [&]() { return unresolved_using_value_decl->getDeclContext(); }));
  clang::CXXRecordDecl *using_parent_record =
      llvm::dyn_cast_or_null<clang::CXXRecordDecl>(using_context);
  if (using_parent_record == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[unresolved-using-value-owner]: "
            "declaration=%p name=%s has no exact class DeclContext\n",
            static_cast<void *>(unresolved_using_value_decl),
            unresolved_using_value_decl->getNameAsString().c_str());
    ROSE_ABORT();
  }
  SgScopeStatement *current_scope =
      resolveScopeFromDeclContext(using_parent_record);
  if (current_scope == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[unresolved-using-value-owner]: "
            "declaration=%p name=%s has no exact Sage class scope\n",
            static_cast<void *>(unresolved_using_value_decl),
            unresolved_using_value_decl->getNameAsString().c_str());
    ROSE_ABORT();
  }
  const bool semantic_only_using = !recordHasLexicalSourceSurface(
      using_parent_record, p_compiler_instance, p_sage_source_file,
      p_sage_preprocessor_recorder);

  std::string source_terminal_name;
  if (!semantic_only_using) {
    const clang::DeclarationNameInfo source_name_info =
        readClangApiValueDefined(
            [&]() { return unresolved_using_value_decl->getNameInfo(); });
    const clang::SourceRange source_name_range = readClangApiValueDefined(
        [&]() { return source_name_info.getSourceRange(); });
    source_terminal_name = trimWhitespace(getSourceText(source_name_range));
    if (source_terminal_name.empty()) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[using-terminal-name]: "
              "UnresolvedUsingValueDecl=%p name=%s has no exact terminal "
              "source token sequence\n",
              static_cast<void *>(unresolved_using_value_decl),
              unresolved_using_value_decl->getNameAsString().c_str());
      ROSE_ABORT();
    }
  }
  auto require_exact_source_terminal =
      [&](const SgUsingDeclarationStatement *statement) {
        if (statement == nullptr ||
            statement->get_source_terminal_name().getString() !=
                source_terminal_name) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[using-terminal-name]: "
                  "UnresolvedUsingValueDecl=%p name=%s does not own exact "
                  "terminal='%s'\n",
                  static_cast<void *>(unresolved_using_value_decl),
                  unresolved_using_value_decl->getNameAsString().c_str(),
                  source_terminal_name.c_str());
          ROSE_ABORT();
        }
      };
  auto require_exact_source_owner = [&](SgUsingDeclarationStatement *statement,
                                        const char *context) {
    SgScopeStatement *lexical_owner =
        statement != nullptr ? isSgScopeStatement(statement->get_parent())
                             : nullptr;
    requireExactUsingDeclarationSurfaceOwner(p_decl_attachment_session,
                                             statement, lexical_owner, context);
    require_exact_source_provenance(statement, context);
    require_exact_source_terminal(statement);
  };

  auto existing_it = p_decl_translation_map.find(unresolved_using_value_decl);
  if (existing_it != p_decl_translation_map.end()) {
    SgUsingDeclarationStatement *existing =
        isSgUsingDeclarationStatement(existing_it->second);
    if (existing == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[unresolved-using-value-translation]: "
              "declaration=%p is mapped to non-using Sage node=%p type=%s\n",
              static_cast<void *>(unresolved_using_value_decl),
              static_cast<void *>(existing_it->second),
              existing_it->second != nullptr
                  ? existing_it->second->class_name().c_str()
                  : "<null>");
      ROSE_ABORT();
    }
    if (semantic_only_using) {
      requireExactSemanticUsingDeclarationOwner(
          existing, current_scope,
          "VisitUnresolvedUsingValueDecl:cached-semantic-owner");
      validate_semantic_provenance(
          existing, true,
          "VisitUnresolvedUsingValueDecl:cached-semantic-provenance");
    } else {
      preserveExplicitUsingDeclarationQualifier(
          existing, unresolved_using_value_decl->getQualifierLoc(),
          p_compiler_instance);
      require_exact_source_owner(
          existing, "VisitUnresolvedUsingValueDecl:cached-source-owner");
    }
    *node = existing;
    FinalizedDeclarationProvenanceGuard finalized_provenance_guard(
        p_declaration_with_finalized_provenance, existing);
    return VisitValueDecl(unresolved_using_value_decl, node) && res;
  }

  std::string name_str = readClangApiValueDefined(
      [&]() { return unresolved_using_value_decl->getNameAsString(); });
  clang::DeclarationName decl_name = readClangApiValueDefined(
      [&]() { return unresolved_using_value_decl->getDeclName(); });
  bool is_inheriting_constructor =
      readClangApiValueDefined([&]() { return decl_name.getNameKind(); }) ==
      clang::DeclarationName::CXXConstructorName;
  SgScopeStatement *target_scope = current_scope;
  clang::NestedNameSpecifier qualifier =
      markClangNestedNameSpecifierDefined(readClangApiValueDefined(
          [&]() { return unresolved_using_value_decl->getQualifier(); }));
  if (!qualifier) {
    clang::NestedNameSpecifierLoc qualifier_loc =
        markClangNestedNameSpecifierLocDefined(readClangApiValueDefined(
            [&]() { return unresolved_using_value_decl->getQualifierLoc(); }));
    qualifier = markClangNestedNameSpecifierDefined(readClangApiValueDefined(
        [&]() { return qualifier_loc.getNestedNameSpecifier(); }));
  }
  if (qualifier) {
    target_scope = nullptr;
    if (SgScopeStatement *qualified_scope =
            buildNonrealScopeFromNestedNameSpecifier(qualifier,
                                                     current_scope)) {
      target_scope = qualified_scope;
    } else if (SgNonrealType *nrtype =
                   buildSemanticNonrealTypeFromNestedNameSpecifier(
                       qualifier, current_scope, SgName(name_str), nullptr,
                       nullptr)) {
      if (SgNonrealDecl *nrdecl = isSgNonrealDecl(nrtype->get_declaration())) {
        if (nrdecl->get_nonreal_decl_scope() != nullptr) {
          target_scope = nrdecl->get_nonreal_decl_scope();
        } else if (nrdecl->get_scope() != nullptr) {
          target_scope = nrdecl->get_scope();
        }
      }
    }
    if (target_scope == nullptr) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[unresolved-using-value-target]: "
              "declaration=%p name=%s has no exact qualified target scope\n",
              static_cast<void *>(unresolved_using_value_decl),
              unresolved_using_value_decl->getNameAsString().c_str());
      ROSE_ABORT();
    }
  }

  auto clang_decl_matches_using_source =
      [&](SgUsingDeclarationStatement *candidate) -> bool {
    if (candidate == nullptr || p_compiler_instance == nullptr) {
      return false;
    }

    Sg_File_Info *candidate_fi = get_decl_sort_file_info(candidate);
    if (candidate_fi == nullptr || candidate_fi->get_line() <= 0 ||
        candidate_fi->get_col() <= 0) {
      return false;
    }

    clang::SourceManager &source_manager =
        p_compiler_instance->getSourceManager();
    clang::SourceLocation clang_loc = readClangApiValueDefined(
        [&]() { return unresolved_using_value_decl->getBeginLoc(); });
    if (!clang_loc.isValid()) {
      clang_loc = readClangApiValueDefined(
          [&]() { return unresolved_using_value_decl->getLocation(); });
    }
    clang_loc = source_manager.getSpellingLoc(clang_loc);
    if (!clang_loc.isValid()) {
      return false;
    }

    unsigned clang_line = source_manager.getSpellingLineNumber(clang_loc);
    unsigned clang_col = source_manager.getSpellingColumnNumber(clang_loc);
    if (clang_line != static_cast<unsigned>(candidate_fi->get_line()) ||
        clang_col != static_cast<unsigned>(candidate_fi->get_col())) {
      return false;
    }

    llvm::StringRef clang_file_ref = source_manager.getFilename(clang_loc);
    if (clang_file_ref.empty() || candidate_fi->get_filenameString().empty()) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[unresolved-using-value-owner]: "
              "declaration=%p name=%s or candidate=%p lacks an exact "
              "physical source filename\n",
              static_cast<void *>(unresolved_using_value_decl),
              unresolved_using_value_decl->getNameAsString().c_str(),
              static_cast<void *>(candidate));
      ROSE_ABORT();
    }

    return clang_file_ref == candidate_fi->get_filenameString();
  };

  auto find_existing_unresolved_using = [&]() -> SgUsingDeclarationStatement * {
    if (current_scope == nullptr) {
      return nullptr;
    }

    SgDeclarationStatementPtrList *decls =
        get_scope_declaration_list(current_scope);
    if (decls == nullptr) {
      return nullptr;
    }

    for (SgDeclarationStatement *decl : *decls) {
      SgUsingDeclarationStatement *candidate =
          isSgUsingDeclarationStatement(decl);
      if (candidate == nullptr) {
        continue;
      }
      SgInitializedName *candidate_name = candidate->get_initializedName();
      if (candidate_name == nullptr ||
          candidate->get_source_terminal_name().getString() !=
              source_terminal_name) {
        continue;
      }
      if (!clang_decl_matches_using_source(candidate)) {
        continue;
      }
      return candidate;
    }

    return nullptr;
  };

  if (!semantic_only_using) {
    if (SgUsingDeclarationStatement *existing =
            find_existing_unresolved_using()) {
      preserveExplicitUsingDeclarationQualifier(
          existing, unresolved_using_value_decl->getQualifierLoc(),
          p_compiler_instance);
      requireExactUsingDeclarationSurfaceOwner(
          p_decl_attachment_session, existing, current_scope,
          "VisitUnresolvedUsingValueDecl:reused-source-owner");
      require_exact_source_provenance(
          existing, "VisitUnresolvedUsingValueDecl:reused-source-owner");
      require_exact_source_terminal(existing);
      p_decl_translation_map[unresolved_using_value_decl] = existing;
      *node = existing;
      FinalizedDeclarationProvenanceGuard finalized_provenance_guard(
          p_declaration_with_finalized_provenance, existing);
      return VisitValueDecl(unresolved_using_value_decl, node) && res;
    }
  }

  SgType *target_type =
      semantic_only_using
          ? buildSemanticTypeFromQualifiedType(
                unresolved_using_value_decl->getType(),
                "VisitUnresolvedUsingValueDecl:semantic-target-type")
          : buildTypeFromQualifiedType(unresolved_using_value_decl->getType());
  if (target_type == nullptr ||
      SageInterface::containsUnknownType(target_type)) {
    std::cerr << "REX_FRONTEND_INVARIANT[unresolved-using-value-type]: '"
              << name_str << "' has no exact translated type" << std::endl;
    ROSE_ABORT();
  }
  SgInitializedName *init_name =
      SageBuilder::buildInitializedName(SgName(name_str), target_type);
  init_name->set_scope(target_scope);

  SgUsingDeclarationStatement *using_stmt =
      new SgUsingDeclarationStatement(nullptr, init_name);
  init_name->set_parent(using_stmt);
  if (is_inheriting_constructor) {
    using_stmt->set_is_inheriting_constructor(true);
  }
  using_stmt->set_definingDeclaration(using_stmt);
  using_stmt->set_firstNondefiningDeclaration(using_stmt);

  if (semantic_only_using) {
    setSynthesizedFileInfo(init_name);
    mark_compiler_generated_frontend_specific(init_name);
    setSynthesizedFileInfo(using_stmt);
    mark_compiler_generated_frontend_specific(using_stmt);
    SageBuilder::attachAuxiliaryDeclaration(current_scope, using_stmt);
    publishExactEffectiveDeclarationAccess(
        unresolved_using_value_decl, using_stmt,
        "VisitUnresolvedUsingValueDecl:semantic-access");
    requireExactSemanticUsingDeclarationOwner(
        using_stmt, current_scope,
        "VisitUnresolvedUsingValueDecl:semantic-owner");
    validate_semantic_provenance(
        using_stmt, true, "VisitUnresolvedUsingValueDecl:semantic-provenance");
    validate_semantic_provenance(
        init_name, true,
        "VisitUnresolvedUsingValueDecl:semantic-target-provenance");
  } else {
    using_stmt->set_source_terminal_name(SgName(source_terminal_name));
    using_stmt->set_source_has_pack_expansion(
        unresolved_using_value_decl->isPackExpansion());
    applySourceRange(using_stmt, readClangApiValueDefined([&]() {
                       return unresolved_using_value_decl->getSourceRange();
                     }));
    preserveExplicitUsingDeclarationQualifier(
        using_stmt, unresolved_using_value_decl->getQualifierLoc(),
        p_compiler_instance);
    publishFreshUsingDeclarationSurface(
        p_decl_attachment_session, using_stmt, current_scope,
        "VisitUnresolvedUsingValueDecl:source-owner");
  }
  diagnose_null_scope(using_stmt, "UnresolvedUsingValueDecl");

  p_decl_translation_map[unresolved_using_value_decl] = using_stmt;
  *node = using_stmt;

  FinalizedDeclarationProvenanceGuard finalized_provenance_guard(
      p_declaration_with_finalized_provenance, using_stmt);
  return VisitValueDecl(unresolved_using_value_decl, node) && res;
}

bool ClangToSageTranslator::VisitPragmaCommentDecl(
    clang::PragmaCommentDecl *pragma_comment_decl, SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitPragmaCommentDecl" << std::endl;
#endif
  (void)node;
  rejectUnsupportedSourceDeclaration(pragma_comment_decl);
}

bool ClangToSageTranslator::VisitPragmaDetectMismatchDecl(
    clang::PragmaDetectMismatchDecl *pragma_detect_mismatch_decl,
    SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitPragmaDetectMismatchDecl"
            << std::endl;
#endif
  (void)node;
  rejectUnsupportedSourceDeclaration(pragma_detect_mismatch_decl);
}

bool ClangToSageTranslator::VisitStaticAssertDecl(
    clang::StaticAssertDecl *pragma_static_assert_decl, SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitStaticAssertDecl" << std::endl;
#endif
  bool res = true;

  pragma_static_assert_decl =
      markClangSpecificDeclDefined(pragma_static_assert_decl);
  ASSERT_not_null(pragma_static_assert_decl);
  clang::DeclContext *decl_context =
      markClangDeclContextObjectDefined(readClangApiValueDefined(
          [&]() { return pragma_static_assert_decl->getDeclContext(); }));
  clang::DeclContext *lexical_context =
      markClangDeclContextObjectDefined(readClangApiValueDefined([&]() {
        return pragma_static_assert_decl->getLexicalDeclContext();
      }));
  clang::RecordDecl *record_context = llvm::dyn_cast_or_null<clang::RecordDecl>(
      decl_context != nullptr ? clang::Decl::castFromDeclContext(decl_context)
                              : nullptr);
  record_context = markClangSpecificDeclDefined(record_context);
  const bool semantic_record_static_assert =
      record_context != nullptr && lexical_context == decl_context &&
      !recordHasLexicalSourceSurface(record_context, p_compiler_instance,
                                     p_sage_source_file,
                                     p_sage_preprocessor_recorder);
  SgScopeStatement *semantic_scope = resolveScopeFromDeclContext(decl_context);
  if (semantic_scope == nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[static-assert-owner]: declaration=%p "
            "context=%p has no exact Sage scope\n",
            static_cast<void *>(pragma_static_assert_decl),
            static_cast<void *>(decl_context));
    ROSE_ABORT();
  }
  SgScopeStatement *static_assert_scope = semantic_scope;
  const bool block_local_static_assert =
      decl_context != nullptr && decl_context->isFunctionOrMethod();
  const DeclStatementConstruction *decl_statement_construction =
      activeDeclStatementConstructionFor(pragma_static_assert_decl);
  if (decl_statement_construction != nullptr && block_local_static_assert) {
    // The DeclStmt transaction records the exact lexical owner before any of
    // its declarations are translated.  Translating the static-assert
    // condition can re-enter declaration translation and temporarily change
    // the ambient Sage scope stack, so that stack is not an ownership oracle
    // for the direct declaration.  Consume the producer-published owner from
    // the exact DeclStmt instead.
    SgScopeStatement *lexical_scope =
        decl_statement_construction->lexical_scope;
    SgFunctionDefinition *semantic_function =
        isSgFunctionDefinition(semantic_scope);
    SgFunctionDefinition *lexical_function =
        lexical_scope != nullptr
            ? SageInterface::getEnclosingFunctionDefinition(lexical_scope, true)
            : nullptr;
    if (semantic_function == nullptr || lexical_function == nullptr ||
        lexical_function != semantic_function) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[static-assert-lexical-owner]: "
              "declaration=%p context=%p semantic-function=%p lexical-scope=%p "
              "enclosing-function=%p active-scope=%p does not identify one "
              "exact block-local source owner\n",
              static_cast<void *>(pragma_static_assert_decl),
              static_cast<void *>(decl_context),
              static_cast<void *>(semantic_function),
              static_cast<void *>(lexical_scope),
              static_cast<void *>(lexical_function),
              static_cast<void *>(SageBuilder::topScopeStack()));
      ROSE_ABORT();
    }
    static_assert_scope = lexical_scope;
  } else if (block_local_static_assert) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[static-assert-lexical-owner]: "
            "declaration=%p has function semantic context outside its exact "
            "DeclStmt construction\n",
            static_cast<void *>(pragma_static_assert_decl));
    ROSE_ABORT();
  }

  clang::Expr *clang_condition =
      markClangExprObjectDefinedByClass(readClangApiValueDefined(
          [&]() { return pragma_static_assert_decl->getAssertExpr(); }));
  SgNode *tmp_condition =
      semantic_record_static_assert
          ? translateSemanticExpressionSubtree(
                clang_condition, "VisitStaticAssertDecl:semantic-condition")
          : Traverse(clang_condition);
  SgExpression *condition = isSgExpression(tmp_condition);
  if (condition == nullptr) {
    std::cerr << "REX_FRONTEND_INVARIANT[static-assert-condition]: Clang "
                 "condition translated to "
              << (tmp_condition != nullptr ? tmp_condition->class_name()
                                           : std::string("<null>"))
              << " instead of SgExpression" << std::endl;
    ROSE_ABORT();
  } else {
    clang::Expr *clang_message =
        markClangExprObjectDefinedByClass(readClangApiValueDefined(
            [&]() { return pragma_static_assert_decl->getMessage(); }));
    SgExpression *message = nullptr;
    if (clang_message != nullptr) {
      SgNode *tmp_message =
          semantic_record_static_assert
              ? translateSemanticExpressionSubtree(
                    clang_message, "VisitStaticAssertDecl:semantic-message")
              : Traverse(clang_message);
      message = isSgExpression(tmp_message);
      if (message == nullptr) {
        std::cerr << "REX_FRONTEND_INVARIANT[static-assert-message]: Clang "
                     "message translated to "
                  << (tmp_message != nullptr ? tmp_message->class_name()
                                             : std::string("<null>"))
                  << " instead of SgExpression" << std::endl;
        ROSE_ABORT();
      }
    }
    *node =
        SageBuilder::buildStaticAssertionDeclaration_nfi(condition, message);
    if (SgStaticAssertionDeclaration *sg_static_assert =
            isSgStaticAssertionDeclaration(*node)) {
      publishExactEffectiveDeclarationAccess(
          pragma_static_assert_decl, sg_static_assert, "VisitStaticAssertDecl");
      const bool typed_body_adoption_pending =
          decl_statement_construction != nullptr &&
          decl_statement_construction->typed_child_owner != nullptr;
      if (sg_static_assert->get_parent() != nullptr) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[static-assert-owner]: freshly built "
                "declaration=%p already has a structural owner\n",
                static_cast<void *>(sg_static_assert));
        ROSE_ABORT();
      }
      if (semantic_record_static_assert) {
        if (typed_body_adoption_pending || block_local_static_assert) {
          fprintf(
              stderr,
              "REX_FRONTEND_INVARIANT[static-assert-owner]: semantic record "
              "declaration=%p also entered a block-local source "
              "transaction\n",
              static_cast<void *>(pragma_static_assert_decl));
          ROSE_ABORT();
        }
        setSynthesizedFileInfo(sg_static_assert);
        mark_compiler_generated_frontend_specific(sg_static_assert);
        SageBuilder::attachAuxiliaryDeclaration(semantic_scope,
                                                sg_static_assert);
        validate_semantic_provenance(
            sg_static_assert, true,
            "VisitStaticAssertDecl:semantic-record-member");
      } else {
        applySourceRange(sg_static_assert,
                         pragma_static_assert_decl->getSourceRange());
      }
      if (!semantic_record_static_assert) {
        if (typed_body_adoption_pending) {
          // An unbraced controlled declaration is the direct true/false/body
          // child of its enclosing statement; SgIfStmt and similar typed owners
          // intentionally have no generic statement list. A statement's Sage
          // scope is derived from its structural parent, so leave it completely
          // detached for that enclosing producer to adopt after VisitDeclStmt
          // returns; querying get_scope() during this transaction is itself an
          // invariant violation.
          if (sg_static_assert->get_parent() != nullptr) {
            fprintf(
                stderr,
                "REX_FRONTEND_INVARIANT[static-assert-owner]: declaration=%p "
                "did not enter its exact detached typed-body transaction\n",
                static_cast<void *>(sg_static_assert));
            ROSE_ABORT();
          }
        } else {
          if (static_assert_scope->statementExistsInScope(sg_static_assert)) {
            fprintf(
                stderr,
                "REX_FRONTEND_INVARIANT[static-assert-owner]: freshly built "
                "declaration=%p already occurs in its lexical scope\n",
                static_cast<void *>(sg_static_assert));
            ROSE_ABORT();
          }
          publish_fresh_decl_in_scope_child_list(
              p_decl_attachment_session, sg_static_assert, static_assert_scope,
              "VisitStaticAssertDecl");
          if (sg_static_assert->get_parent() != static_assert_scope ||
              sg_static_assert->get_scope() != static_assert_scope) {
            fprintf(
                stderr,
                "REX_FRONTEND_INVARIANT[static-assert-owner]: declaration=%p "
                "did not acquire its exact construction-time scope owner\n",
                static_cast<void *>(sg_static_assert));
            ROSE_ABORT();
          }
        }
      }
    }
  }

  FinalizedDeclarationProvenanceGuard finalized_provenance_guard(
      p_declaration_with_finalized_provenance, *node);
  return VisitDecl(pragma_static_assert_decl, node) && res;
}

bool ClangToSageTranslator::VisitTranslationUnitDecl(
    clang::TranslationUnitDecl *translation_unit_decl, SgNode **node) {
#if DEBUG_VISIT_DECL
  std::cerr << "ClangToSageTranslator::VisitTranslationUnitDecl" << std::endl;
#endif
  if (*node != nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[translation-unit-identity]: Clang "
            "translation unit=%p is already associated with Sage node=%p\n",
            static_cast<void *>(translation_unit_decl),
            static_cast<void *>(*node));
    ROSE_ABORT();
  }

  // Create the SAGE node: SgGlobal

  if (p_global_scope != nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[global-scope-identity]: translator already "
            "owns global scope=%p before translation unit=%p\n",
            static_cast<void *>(p_global_scope),
            static_cast<void *>(translation_unit_decl));
    ROSE_ABORT();
  }

  // Create file info for global scope (following legacy pattern)
  // Use the source file's filename and line 0
  if (p_sage_source_file == nullptr || p_compiler_instance == nullptr ||
      p_sage_source_file->get_startOfConstruct() == nullptr ||
      p_sage_source_file->get_startOfConstruct()
          ->get_filenameString()
          .empty()) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[translation-unit-source]: translation "
            "unit=%p has no exact Sage source-file identity\n",
            static_cast<void *>(translation_unit_decl));
    ROSE_ABORT();
  }
  SgType *target_size_type = buildTypeFromQualifiedType(
      markClangQualTypeDefined(readClangApiValueDefined([&]() {
        return p_compiler_instance->getASTContext().getSizeType();
      })));
  if (target_size_type == nullptr ||
      isSgTypeUnknown(target_size_type) != nullptr ||
      isSgTypeDefault(target_size_type) != nullptr) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[target-size-type]: Clang translation "
            "unit=%p has no exact ASTContext size_t type\n",
            static_cast<void *>(translation_unit_decl));
    ROSE_ABORT();
  }
  p_sage_source_file->set_target_size_type(target_size_type);
  if (SageInterface::requireTargetSizeType(p_sage_source_file) !=
      target_size_type) {
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[target-size-type]: Sage source file did "
            "not retain Clang's exact ASTContext size_t type\n");
    ROSE_ABORT();
  }
  const std::string sourceFilename =
      p_sage_source_file->get_startOfConstruct()->get_filenameString();
  Sg_File_Info *globalScopeFileInfo = new Sg_File_Info(sourceFilename, 0, 0);

  // Pass file info to SgGlobal constructor (like the legacy frontend does)
  *node = p_global_scope = new SgGlobal(globalScopeFileInfo);

  // Set up parent relationship immediately so symbol insertion can access the
  // project
  p_global_scope->set_parent(p_sage_source_file);

  p_decl_translation_map.insert(std::pair<clang::Decl *, SgNode *>(
      translation_unit_decl, p_global_scope));

  // Traverse the children

  // DQ (4/5/2017): Fixed code to use updated SageBuilder API.
  // SageBuilder::pushScopeStack(*node);
  SgScopeStatement *global_scope = isSgGlobal(*node);
  ROSE_ASSERT(global_scope != nullptr);
  SageBuilder::pushScopeStack(global_scope);

  clang::DeclContext *decl_context =
      (clang::DeclContext *)translation_unit_decl; // useless but more clear

  bool res = false;
  {
    roseClangPhaseTrace(
        "clang_main.HandleTranslationUnit.tuDecl.traverseDeclContext.begin");
    TraceOnlyPerformance timer("Clang TU TraverseForDeclContext:");
    res = TraverseForDeclContext(decl_context);
    roseClangPhaseTrace(
        "clang_main.HandleTranslationUnit.tuDecl.traverseDeclContext.end");
  }

  // Phase C (Issue 115): Translate queued implicit class template
  // specializations after the TU decl pass so the primary template definition
  // is fully materialized before generic AST traversals can observe the
  // specialization. Do not structurally reattach these queued implicit
  // specializations to scope child lists here:
  // VisitClassTemplateSpecialization already decides whether a specialization
  // is source-visible. Reattaching semantic-only instantiations here bounces
  // them back into generated output as stray `template<> class ...;`
  // declarations and perturbs later symbol ownership.
  {
    roseClangPhaseTrace(
        "clang_main.HandleTranslationUnit.tuDecl.phaseCClassSpecs.begin");
    TraceOnlyPerformance timer("Clang TU Phase C implicit class specs:");
    while (!p_pending_implicit_class_template_specializations.empty()) {
      clang::ClassTemplateSpecializationDecl *pending =
          p_pending_implicit_class_template_specializations.back();
      p_pending_implicit_class_template_specializations.pop_back();

      if (pending == nullptr) {
        continue;
      }
      pending = markClangSpecificDeclDefined(pending);

      SgNode *inst_node = nullptr;
      auto existing = p_decl_translation_map.find(pending);
      if (existing != p_decl_translation_map.end()) {
        inst_node = existing->second;
        SgNode *semantic_node = inst_node;
        if (SgTemplateInstantiationDirectiveStatement *directive =
                isSgTemplateInstantiationDirectiveStatement(semantic_node)) {
          semantic_node = directive->get_declaration();
        }
        SgClassDeclaration *class_declaration =
            isSgClassDeclaration(semantic_node);
        SgClassDeclaration *defining_declaration =
            class_declaration != nullptr
                ? isSgClassDeclaration(
                      class_declaration->get_definingDeclaration())
                : nullptr;
        if (defining_declaration == nullptr && class_declaration != nullptr &&
            class_declaration->get_definition() != nullptr) {
          defining_declaration = class_declaration;
        }
        SgClassDefinition *definition =
            defining_declaration != nullptr
                ? defining_declaration->get_definition()
                : nullptr;
        const bool clang_has_definition =
            clangRecordDefinitionDefined(pending) != nullptr;
        if (clang_has_definition &&
            (definition == nullptr ||
             p_record_definitions_populated.count(definition) == 0)) {
          SgNode *completed = nullptr;
          if (!VisitClassTemplateSpecializationDecl(pending, &completed) ||
              completed == nullptr) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[class-instantiation-phase-c]: "
                    "specialization=%s did not complete its deferred exact "
                    "definition\n",
                    pending->getQualifiedNameAsString().c_str());
            ROSE_ABORT();
          }
          inst_node = completed;
        }
      } else {
        inst_node = Traverse(pending);
      }
      p_pending_implicit_class_template_specializations_set.erase(pending);
    }
    roseClangPhaseTrace(
        "clang_main.HandleTranslationUnit.tuDecl.phaseCClassSpecs.end");
  }
  // Phase C (Issue 115): Complete queued semantic function bodies after the
  // TU declaration pass.  Queue membership publishes declaration identities
  // only; this phase is the sole authorization to lower bodies after template
  // arguments, class owners, and symbol tables are complete.
  {
    roseClangPhaseTrace(
        "clang_main.HandleTranslationUnit.tuDecl.phaseCFunctionBodies.begin");
    TraceOnlyPerformance timer("Clang TU Phase C function bodies:");
    const bool trace_phase_c_functions =
        getenv("ROSE_PHASE_C_FUNCTION_TRACE") != nullptr;
    std::size_t phase_c_function_ordinal = 0;
    while (!p_pending_function_body_completions.empty()) {
      clang::FunctionDecl *pending = p_pending_function_body_completions.back();
      p_pending_function_body_completions.pop_back();

      if (pending == nullptr) {
        continue;
      }
      pending = markClangSpecificDeclDefined(pending);
      ++phase_c_function_ordinal;
      const auto phase_c_function_start =
          trace_phase_c_functions ? std::chrono::steady_clock::now()
                                  : std::chrono::steady_clock::time_point();
      if (trace_phase_c_functions) {
        fprintf(stderr,
                "ROSE_PHASE_C_FUNCTION begin ordinal=%zu remaining=%zu "
                "kind=%s name=%s\n",
                phase_c_function_ordinal,
                p_pending_function_body_completions.size(),
                static_cast<clang::Decl *>(pending)->getDeclKindName(),
                pending->getQualifiedNameAsString().c_str());
        fflush(stderr);
      }
      const clang::TemplateSpecializationKind pending_kind =
          readClangApiValueDefined(
              [&]() { return pending->getTemplateSpecializationKind(); });
      const bool pending_is_implicit =
          pending_kind == clang::TSK_ImplicitInstantiation;
      const bool pending_is_explicit =
          pending_kind == clang::TSK_ExplicitInstantiationDeclaration ||
          pending_kind == clang::TSK_ExplicitInstantiationDefinition;
      clang::CXXMethodDecl *pending_method =
          llvm::dyn_cast<clang::CXXMethodDecl>(pending);
      const bool pending_is_deferred_semantic_member =
          pending_kind == clang::TSK_Undeclared && pending_method != nullptr &&
          !clangCXXMethodIsLambdaCallOperatorDefined(pending_method);
      if (!pending_is_implicit && !pending_is_explicit &&
          !pending_is_deferred_semantic_member) {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[function-instantiation-phase-c]: "
                "queued function=%s has unsupported specialization kind=%d\n",
                pending->getQualifiedNameAsString().c_str(),
                static_cast<int>(pending_kind));
        ROSE_ABORT();
      }
      struct ActiveFunctionBodyCompletionGuard {
        std::set<clang::FunctionDecl *> &active;
        clang::FunctionDecl *declaration;
        ActiveFunctionBodyCompletionGuard(
            std::set<clang::FunctionDecl *> &active,
            clang::FunctionDecl *declaration)
            : active(active), declaration(declaration) {
          if (declaration == nullptr || !active.insert(declaration).second) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[function-instantiation-phase-c]: "
                    "function body completion is null or already active\n");
            ROSE_ABORT();
          }
        }
        ~ActiveFunctionBodyCompletionGuard() {
          if (active.erase(declaration) != 1) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[function-instantiation-phase-c]: "
                    "active function body completion was lost\n");
            ROSE_ABORT();
          }
        }
      } active_function_body_completion(p_active_function_body_completions,
                                        pending);

      SgNode *inst_node = nullptr;
      auto existing = p_decl_translation_map.find(pending);
      auto placeholder =
          p_suppressed_implicit_function_instantiation_placeholders.end();
      std::vector<clang::FunctionDecl *> pending_family;
      std::unordered_set<clang::FunctionDecl *> pending_family_seen;
      auto add_pending_family_member = [&](clang::FunctionDecl *candidate) {
        candidate = markClangSpecificDeclDefined(candidate);
        if (candidate != nullptr &&
            pending_family_seen.insert(candidate).second) {
          pending_family.push_back(candidate);
        }
      };
      add_pending_family_member(pending);
      add_pending_family_member(pending->getCanonicalDecl());
      add_pending_family_member(pending->getFirstDecl());
      for (clang::FunctionDecl *redecl : pending->redecls()) {
        add_pending_family_member(redecl);
      }
      for (clang::FunctionDecl *candidate : pending_family) {
        auto found =
            p_suppressed_implicit_function_instantiation_placeholders.find(
                candidate);
        if (found ==
            p_suppressed_implicit_function_instantiation_placeholders.end()) {
          continue;
        }
        if (placeholder !=
                p_suppressed_implicit_function_instantiation_placeholders
                    .end() &&
            placeholder->second != found->second) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[function-instantiation-"
                  "placeholder]: queued Clang specialization=%p/%s has "
                  "multiple suppressed placeholders in one redeclaration "
                  "family\n",
                  static_cast<void *>(pending),
                  pending->getQualifiedNameAsString().c_str());
          ROSE_ABORT();
        }
        placeholder = found;
      }
      if (placeholder !=
          p_suppressed_implicit_function_instantiation_placeholders.end()) {
        SgFunctionDeclaration *suppressed_declaration = placeholder->second;
        SgFunctionDeclaration *mapped_declaration =
            existing != p_decl_translation_map.end()
                ? isSgFunctionDeclaration(existing->second)
                : nullptr;
        const bool exact_incomplete_placeholder =
            mapped_declaration == suppressed_declaration &&
            suppressed_declaration != nullptr &&
            isSgTemplateInstantiationFunctionDecl(suppressed_declaration) ==
                nullptr &&
            isSgTemplateInstantiationMemberFunctionDecl(
                suppressed_declaration) == nullptr &&
            suppressed_declaration->get_firstNondefiningDeclaration() ==
                suppressed_declaration &&
            suppressed_declaration->get_definingDeclaration() == nullptr &&
            suppressed_declaration->get_definition() == nullptr;
        SgFunctionDeclaration *completed_placeholder_declaration = nullptr;
        const bool exact_completed_placeholder_family = [&]() {
          if (mapped_declaration == nullptr ||
              suppressed_declaration == nullptr ||
              isSgTemplateInstantiationFunctionDecl(suppressed_declaration) !=
                  nullptr ||
              isSgTemplateInstantiationMemberFunctionDecl(
                  suppressed_declaration) != nullptr) {
            return false;
          }
          SgFunctionDeclaration *suppressed_defining = isSgFunctionDeclaration(
              suppressed_declaration->get_definingDeclaration());
          SgFunctionDeclaration *completed =
              mapped_declaration != suppressed_declaration
                  ? mapped_declaration
                  : suppressed_defining;
          if (completed == nullptr || completed == suppressed_declaration ||
              completed->get_firstNondefiningDeclaration() !=
                  suppressed_declaration ||
              completed->get_definingDeclaration() != completed ||
              completed->get_definition() == nullptr ||
              suppressed_declaration->get_firstNondefiningDeclaration() !=
                  suppressed_declaration ||
              suppressed_declaration->get_definingDeclaration() != completed ||
              suppressed_declaration->get_definition() != nullptr) {
            return false;
          }
          SgScopeStatement *placeholder_owner = validate_exact_auxiliary_owner(
              suppressed_declaration,
              "Issue115 Phase C suppressed function placeholder");
          SgScopeStatement *definition_owner = validate_exact_auxiliary_owner(
              completed, "Issue115 Phase C completed suppressed function");
          const bool exact_owner =
              placeholder_owner != nullptr &&
              definition_owner == placeholder_owner &&
              suppressed_declaration->get_scope() == placeholder_owner &&
              completed->get_scope() == placeholder_owner;
          if (exact_owner) {
            completed_placeholder_declaration = completed;
          }
          return exact_owner;
        }();
        const bool exact_completed_placeholder_replacement = [&]() {
          if (mapped_declaration == nullptr ||
              mapped_declaration == suppressed_declaration ||
              suppressed_declaration == nullptr ||
              !is_hidden_frontend_placeholder(suppressed_declaration)) {
            return false;
          }
          const bool clang_method = llvm::isa<clang::CXXMethodDecl>(pending);
          auto has_exact_instantiation_kind =
              [&](SgFunctionDeclaration *candidate) {
                return candidate != nullptr &&
                       (clang_method
                            ? isSgTemplateInstantiationMemberFunctionDecl(
                                  candidate) != nullptr
                            : isSgTemplateInstantiationFunctionDecl(
                                  candidate) != nullptr);
              };
          SgFunctionDeclaration *canonical = isSgFunctionDeclaration(
              mapped_declaration->get_firstNondefiningDeclaration());
          if (canonical == nullptr) {
            canonical = mapped_declaration;
          }
          SgFunctionDeclaration *defining =
              isSgFunctionDeclaration(canonical->get_definingDeclaration());
          if (defining == nullptr &&
              mapped_declaration->get_definition() != nullptr) {
            defining = mapped_declaration;
          }
          SgScopeStatement *placeholder_owner = validate_exact_auxiliary_owner(
              suppressed_declaration,
              "Issue115 Phase C replaced suppressed function placeholder");
          SgScopeStatement *canonical_owner =
              canonical != nullptr
                  ? validate_exact_auxiliary_owner(
                        canonical,
                        "Issue115 Phase C replacement function canonical")
                  : nullptr;
          SgScopeStatement *defining_owner =
              defining != nullptr
                  ? validate_exact_auxiliary_owner(
                        defining,
                        "Issue115 Phase C replacement function definition")
                  : nullptr;
          const bool exact_replacement =
              placeholder_owner != nullptr &&
              canonical_owner == placeholder_owner &&
              defining_owner == placeholder_owner &&
              suppressed_declaration->get_scope() == placeholder_owner &&
              suppressed_declaration->get_firstNondefiningDeclaration() ==
                  suppressed_declaration &&
              suppressed_declaration->get_definingDeclaration() == nullptr &&
              suppressed_declaration->get_definition() == nullptr &&
              canonical->get_firstNondefiningDeclaration() == canonical &&
              canonical->get_definingDeclaration() == defining &&
              defining->get_firstNondefiningDeclaration() == canonical &&
              defining->get_definingDeclaration() == defining &&
              defining->get_definition() != nullptr &&
              has_exact_instantiation_kind(canonical) &&
              has_exact_instantiation_kind(defining) &&
              !declaration_has_exact_source_surface_ownership(canonical) &&
              !declaration_has_exact_source_surface_ownership(defining);
          if (exact_replacement) {
            completed_placeholder_declaration = defining;
          }
          return exact_replacement;
        }();
        if (!exact_incomplete_placeholder &&
            !exact_completed_placeholder_family &&
            !exact_completed_placeholder_replacement) {
          fprintf(
              stderr,
              "REX_FRONTEND_INVARIANT[function-instantiation-"
              "placeholder]: queued Clang specialization=%p/%s no "
              "longer owns one exact suppressed declaration family; "
              "placeholder=%p/%s mapped=%p/%s first=%p defining=%p "
              "definition=%p parameters=%p parameter-parent=%p hidden=%d "
              "owner=%p scope=%p inst-function=%d inst-member=%d\n",
              static_cast<void *>(pending),
              pending->getQualifiedNameAsString().c_str(),
              static_cast<void *>(suppressed_declaration),
              suppressed_declaration != nullptr
                  ? suppressed_declaration->class_name().c_str()
                  : "<null>",
              static_cast<void *>(mapped_declaration),
              mapped_declaration != nullptr
                  ? mapped_declaration->class_name().c_str()
                  : "<null>",
              suppressed_declaration != nullptr
                  ? static_cast<void *>(suppressed_declaration
                                            ->get_firstNondefiningDeclaration())
                  : nullptr,
              suppressed_declaration != nullptr
                  ? static_cast<void *>(
                        suppressed_declaration->get_definingDeclaration())
                  : nullptr,
              suppressed_declaration != nullptr
                  ? static_cast<void *>(
                        suppressed_declaration->get_definition())
                  : nullptr,
              suppressed_declaration != nullptr
                  ? static_cast<void *>(
                        suppressed_declaration->get_parameterList())
                  : nullptr,
              suppressed_declaration != nullptr &&
                      suppressed_declaration->get_parameterList() != nullptr
                  ? static_cast<void *>(
                        suppressed_declaration->get_parameterList()
                            ->get_parent())
                  : nullptr,
              suppressed_declaration != nullptr &&
                      is_hidden_frontend_placeholder(suppressed_declaration)
                  ? 1
                  : 0,
              suppressed_declaration != nullptr
                  ? static_cast<void *>(validate_exact_auxiliary_owner(
                        suppressed_declaration,
                        "Issue115 malformed suppressed placeholder"))
                  : nullptr,
              suppressed_declaration != nullptr
                  ? static_cast<void *>(suppressed_declaration->get_scope())
                  : nullptr,
              suppressed_declaration != nullptr &&
                      isSgTemplateInstantiationFunctionDecl(
                          suppressed_declaration) != nullptr
                  ? 1
                  : 0,
              suppressed_declaration != nullptr &&
                      isSgTemplateInstantiationMemberFunctionDecl(
                          suppressed_declaration) != nullptr
                  ? 1
                  : 0);
          ROSE_ABORT();
        }
        auto suppressed_aliases =
            p_suppressed_implicit_function_instantiation_placeholder_aliases
                .find(suppressed_declaration);
        if (suppressed_aliases ==
                p_suppressed_implicit_function_instantiation_placeholder_aliases
                    .end() ||
            suppressed_aliases->second.empty()) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[function-instantiation-"
                  "placeholder]: suppressed declaration=%p has no exact "
                  "reverse Clang aliases\n",
                  static_cast<void *>(suppressed_declaration));
          ROSE_ABORT();
        }
        for (clang::FunctionDecl *alias : suppressed_aliases->second) {
          auto suppressed =
              p_suppressed_implicit_function_instantiation_placeholders.find(
                  alias);
          if (suppressed ==
                  p_suppressed_implicit_function_instantiation_placeholders
                      .end() ||
              suppressed->second != suppressed_declaration) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[function-instantiation-"
                    "placeholder]: reverse alias=%p does not map to exact "
                    "suppressed declaration=%p\n",
                    static_cast<void *>(alias),
                    static_cast<void *>(suppressed_declaration));
            ROSE_ABORT();
          }
          p_suppressed_implicit_function_instantiation_placeholders.erase(
              suppressed);
        }
        p_suppressed_implicit_function_instantiation_placeholder_aliases.erase(
            suppressed_aliases);
        if (exact_completed_placeholder_family ||
            exact_completed_placeholder_replacement) {
          // Population of an enclosing semantic class specialization can
          // complete a queued method before Phase C reaches it.  The mapping
          // can either advance within the recorded declaration family or
          // atomically publish a typed instantiation family that replaces the
          // earlier hidden shell.  Retire every stale shell alias and consume
          // the suppression transaction without rebuilding either completed
          // declaration.
          p_decl_translation_map.replaceAllAliases(
              suppressed_declaration, completed_placeholder_declaration,
              "Issue115 Phase C completed placeholder");
          inst_node = completed_placeholder_declaration;
        } else {
          // Clang can publish the specialization and its instantiated
          // declaration-pattern as distinct Decl objects that are not
          // redeclarations of one another.  During signature construction
          // both keys may legitimately name the one suppressed semantic
          // shell.  Once Phase C owns the concrete instantiation transaction,
          // however, no cache key may keep that incomplete ordinary-function
          // identity alive: such an alias makes Traverse re-enter through the
          // stale shell instead of constructing the typed instantiation.
          p_decl_translation_map.eraseAllAliases(
              suppressed_declaration,
              "Issue115 Phase C incomplete placeholder");
          inst_node = Traverse(pending);
        }
      } else if (existing != p_decl_translation_map.end()) {
        inst_node = existing->second;
        SgNode *semantic_node = inst_node;
        if (SgTemplateInstantiationDirectiveStatement *directive =
                isSgTemplateInstantiationDirectiveStatement(semantic_node)) {
          semantic_node = directive->get_declaration();
        }
        SgFunctionDeclaration *published =
            isSgFunctionDeclaration(semantic_node);
        SgFunctionDeclaration *published_definition =
            published != nullptr
                ? isSgFunctionDeclaration(published->get_definingDeclaration())
                : nullptr;
        const bool clang_has_body = readClangApiValueDefined(
            [&]() { return pending->doesThisDeclarationHaveABody(); });
        const bool sage_has_body =
            published_definition != nullptr &&
            published_definition->get_definition() != nullptr;
        if (clang_has_body && !sage_has_body) {
          // Population of a semantic class-template specialization first
          // publishes exact member-function identities so member references
          // can bind while the class is incomplete.  A later call queues the
          // same Clang member for Phase C.  The cache hit above is therefore
          // only a declaration shell, not completed translation: invoke the
          // function producer directly while the pending-set membership makes
          // the body transaction an explicit semantic instantiation.
          SgNode *completed = nullptr;
          const bool completed_translation =
              llvm::isa<clang::CXXConstructorDecl>(pending)
                  ? VisitCXXConstructorDecl(
                        llvm::cast<clang::CXXConstructorDecl>(pending),
                        &completed)
                  : translateFunctionDeclCommon(
                        pending, pending->getDescribedFunctionTemplate(),
                        &completed);
          if (!completed_translation || completed == nullptr) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[function-instantiation-phase-c]: "
                    "queued function=%s retained an incomplete cached "
                    "declaration shell\n",
                    pending->getQualifiedNameAsString().c_str());
            ROSE_ABORT();
          }
          inst_node = completed;
        }
      } else {
        inst_node = Traverse(pending);
      }
      SgNode *semantic_instantiation_node = inst_node;
      if (SgTemplateInstantiationDirectiveStatement *directive =
              isSgTemplateInstantiationDirectiveStatement(
                  semantic_instantiation_node)) {
        semantic_instantiation_node = directive->get_declaration();
      }
      SgFunctionDeclaration *func_decl =
          isSgFunctionDeclaration(semantic_instantiation_node);
      if (func_decl != nullptr) {
        SgTemplateInstantiationDirectiveStatement *directive =
            isSgTemplateInstantiationDirectiveStatement(inst_node);
        const bool source_backed_instantiation =
            directive == nullptr &&
            declaration_has_exact_source_surface_ownership(func_decl);
        const bool semantic_only_instantiation =
            !source_backed_instantiation &&
            (pending_is_implicit || pending_is_deferred_semantic_member ||
             (pending_is_explicit && directive == nullptr));
        if (semantic_only_instantiation) {
          // A queued instantiation without an exact directive surface is a
          // semantic product, including an explicit instantiation written in
          // a suppressed header. Its producer must publish every declaration-
          // chain peer through the auxiliary owner before returning. Phase C
          // verifies that completed transaction and never repairs ownership.
          std::unordered_set<SgFunctionDeclaration *> visited;
          std::vector<SgFunctionDeclaration *> declarations{func_decl};
          for (size_t i = 0; i < declarations.size(); ++i) {
            SgFunctionDeclaration *candidate = declarations[i];
            if (candidate == nullptr || !visited.insert(candidate).second) {
              continue;
            }
            declarations.push_back(isSgFunctionDeclaration(
                candidate->get_firstNondefiningDeclaration()));
            declarations.push_back(
                isSgFunctionDeclaration(candidate->get_definingDeclaration()));
            SgScopeStatement *owner = validate_exact_auxiliary_owner(
                candidate, "Issue115 Phase C semantic function");
            if (owner == nullptr || candidate->get_scope() != owner ||
                owner->statementExistsInScope(candidate) ||
                declaration_has_exact_source_surface_ownership(candidate)) {
              fprintf(stderr,
                      "REX_FRONTEND_INVARIANT[semantic-function-owner]: "
                      "Phase C function=%p type=%s kind=%d has no exact "
                      "semantic auxiliary owner\n",
                      static_cast<void *>(candidate),
                      candidate->class_name().c_str(),
                      static_cast<int>(pending_kind));
              ROSE_ABORT();
            }
          }
        } else if (source_backed_instantiation) {
          // A source-spelled friend template-id can cause Clang to queue the
          // same implicit specialization for Phase C.  That family contains
          // one FriendDecl-owned lexical surface and may also retain semantic
          // auxiliary peers constructed before the class was traversed.
          // Validate each published role exactly; the absence of an explicit
          // instantiation directive does not make the lexical friend semantic.
          std::unordered_set<SgFunctionDeclaration *> visited;
          std::vector<SgFunctionDeclaration *> declarations{func_decl};
          size_t source_declarations = 0;
          for (size_t i = 0; i < declarations.size(); ++i) {
            SgFunctionDeclaration *candidate = declarations[i];
            if (candidate == nullptr || !visited.insert(candidate).second) {
              continue;
            }
            declarations.push_back(isSgFunctionDeclaration(
                candidate->get_firstNondefiningDeclaration()));
            declarations.push_back(
                isSgFunctionDeclaration(candidate->get_definingDeclaration()));
            const bool exact_source =
                declaration_has_exact_source_surface_ownership(candidate);
            SgScopeStatement *auxiliary_owner = validate_exact_auxiliary_owner(
                candidate, "Issue115 Phase C source-backed function");
            if (exact_source == (auxiliary_owner != nullptr) ||
                candidate->get_scope() == nullptr ||
                (exact_source && !declaration_has_real_source(candidate)) ||
                (auxiliary_owner != nullptr &&
                 (candidate->get_scope() != auxiliary_owner ||
                  candidate->get_scope()->statementExistsInScope(candidate) ||
                  declaration_has_real_source(candidate)))) {
              fprintf(stderr,
                      "REX_FRONTEND_INVARIANT[source-function-owner]: Phase "
                      "C function=%p type=%s kind=%d source=%d auxiliary=%p "
                      "does not have one exact lexical or semantic role\n",
                      static_cast<void *>(candidate),
                      candidate->class_name().c_str(),
                      static_cast<int>(pending_kind), exact_source ? 1 : 0,
                      static_cast<void *>(auxiliary_owner));
              ROSE_ABORT();
            }
            source_declarations += exact_source ? 1 : 0;
          }
          if (source_declarations == 0) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[source-function-owner]: Phase C "
                    "queued source-backed function=%p has no exact lexical "
                    "declaration in its canonical family\n",
                    static_cast<void *>(func_decl));
            ROSE_ABORT();
          }
        } else {
          SgScopeStatement *lexical_owner =
              directive != nullptr ? isSgScopeStatement(directive->get_parent())
                                   : nullptr;
          const bool exact_typed_child =
              directive != nullptr &&
              directive->get_declaration() == func_decl &&
              func_decl->get_parent() == directive &&
              exact_direct_structural_successor_count(directive, func_decl) ==
                  1;
          const bool exact_directive_owner =
              lexical_owner != nullptr &&
              directive->get_scope() == lexical_owner &&
              declaration_has_exact_lexical_source_ownership(directive);
          const bool exact_child_source =
              func_decl->get_scope() != nullptr &&
              declaration_has_real_source(func_decl);
          const bool exact_directive_source =
              directive != nullptr && declaration_has_real_source(directive);
          if (!exact_typed_child || !exact_directive_owner ||
              !exact_child_source || !exact_directive_source) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[explicit-function-owner]: "
                    "Phase C function=%p/%s directive=%p lexical-owner=%p "
                    "does not retain one exact directive-owned source "
                    "surface child=%d directive-owner=%d child-source=%d "
                    "directive-source=%d child-scope=%p directive-scope=%p\n",
                    static_cast<void *>(func_decl),
                    func_decl->class_name().c_str(),
                    static_cast<void *>(directive),
                    static_cast<void *>(lexical_owner),
                    exact_typed_child ? 1 : 0, exact_directive_owner ? 1 : 0,
                    exact_child_source ? 1 : 0, exact_directive_source ? 1 : 0,
                    static_cast<void *>(func_decl->get_scope()),
                    directive != nullptr
                        ? static_cast<void *>(directive->get_scope())
                        : nullptr);
            ROSE_ABORT();
          }
        }
      } else {
        fprintf(stderr,
                "REX_FRONTEND_INVARIANT[function-instantiation-phase-c]: "
                "queued function=%s translated to %p/%s instead of one exact "
                "function declaration\n",
                pending->getQualifiedNameAsString().c_str(),
                static_cast<void *>(semantic_instantiation_node),
                semantic_instantiation_node != nullptr
                    ? semantic_instantiation_node->class_name().c_str()
                    : "<null>");
        ROSE_ABORT();
      }

      auto pending_references =
          p_pending_deduced_template_function_references.find(pending);
      if (pending_references !=
          p_pending_deduced_template_function_references.end()) {
        if (func_decl == nullptr || pending_references->second.empty()) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[deduced-template-reference]: "
                  "queued Clang specialization=%p translated to %p/%s "
                  "without one Sage function or reference set\n",
                  static_cast<void *>(pending),
                  static_cast<void *>(semantic_instantiation_node),
                  semantic_instantiation_node != nullptr
                      ? semantic_instantiation_node->class_name().c_str()
                      : "<null>");
          ROSE_ABORT();
        }
        for (SgTemplateFunctionRefExp *reference : pending_references->second) {
          SgTemplateFunctionSymbol *source_symbol =
              reference != nullptr ? reference->get_symbol() : nullptr;
          SgTemplateFunctionDeclaration *source_template =
              source_symbol != nullptr ? isSgTemplateFunctionDeclaration(
                                             source_symbol->get_declaration())
                                       : nullptr;
          SgTemplateFunctionDeclaration *reference_source_template =
              reference != nullptr
                  ? isSgTemplateFunctionDeclaration(
                        reference->get_semantic_function_declaration())
                  : nullptr;
          SgTemplateFunctionDeclaration *canonical_source_template =
              source_template != nullptr
                  ? isSgTemplateFunctionDeclaration(
                        source_template->get_firstNondefiningDeclaration())
                  : nullptr;
          SgTemplateFunctionDeclaration *canonical_reference_source_template =
              reference_source_template != nullptr
                  ? isSgTemplateFunctionDeclaration(
                        reference_source_template
                            ->get_firstNondefiningDeclaration())
                  : nullptr;
          if (reference == nullptr || source_template == nullptr ||
              reference_source_template == nullptr ||
              canonical_source_template == nullptr ||
              canonical_reference_source_template !=
                  canonical_source_template) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[deduced-template-reference]: "
                    "queued reference=%p symbol=%p source-template=%p "
                    "reference-template=%p canonical=%p/%p has no exact "
                    "primary-template source identity before semantic "
                    "binding\n",
                    static_cast<void *>(reference),
                    static_cast<void *>(source_symbol),
                    static_cast<void *>(source_template),
                    static_cast<void *>(reference_source_template),
                    static_cast<void *>(canonical_source_template),
                    static_cast<void *>(canonical_reference_source_template));
            ROSE_ABORT();
          }
          SgType *old_reference_type = reference->get_type();
          SgCastExp *decay = isSgCastExp(reference->get_parent());
          if (decay != nullptr) {
            SgType *old_decay_type = decay->get_type();
            SgPointerType *old_result =
                old_decay_type != nullptr
                    ? isSgPointerType(
                          old_decay_type->stripTypedefsAndModifiers())
                    : nullptr;
            SgType *old_decay_base =
                old_result != nullptr ? old_result->get_base_type() : nullptr;
            // The primary template's declaration type can be replaced by its
            // final canonical function type after the reference and its
            // transparent function-pointer conversion are constructed.  The
            // cast builder already validated the exact construction-time
            // operand/base identity for both an ordinary function decay and
            // Clang's builtin-function-to-pointer conversion; Phase C is the
            // transaction that replaces both with the concrete callable.
            // Require the displaced base to remain a function type and
            // validate the final concrete identity below.
            const bool exact_deferred_source_type =
                old_decay_base == old_reference_type ||
                (old_decay_base != nullptr && old_reference_type != nullptr &&
                 isSgFunctionType(
                     old_decay_base->stripTypedefsAndModifiers()) != nullptr &&
                 isSgFunctionType(
                     old_reference_type->stripTypedefsAndModifiers()) !=
                     nullptr);
            const SgCastExp::semantic_conversion_kind_enum conversion_kind =
                decay->get_semantic_conversion_kind();
            const bool exact_function_pointer_conversion =
                conversion_kind ==
                    SgCastExp::e_semantic_conversion_FunctionToPointerDecay ||
                conversion_kind ==
                    SgCastExp::e_semantic_conversion_BuiltinFnToFnPtr;
            if (decay->get_operand() != reference ||
                decay->get_cast_type() != SgCastExp::e_implicit_cast ||
                !exact_function_pointer_conversion || old_result == nullptr ||
                !exact_deferred_source_type) {
              fprintf(
                  stderr,
                  "REX_FRONTEND_INVARIANT[deduced-template-reference-"
                  "decay]: reference=%p parent=%p/%s old-type=%p "
                  "source-template=%p/%s source-type=%p "
                  "reference-template=%p/%s reference-type=%p "
                  "semantic-specialization=%p/%s semantic-type=%p "
                  "operand=%p cast-kind=%d semantic-kind=%d "
                  "result=%p/%s pointer=%p base=%p equivalent=%d does "
                  "not own one "
                  "exact deferred function decay\n",
                  static_cast<void *>(reference), static_cast<void *>(decay),
                  decay->class_name().c_str(),
                  static_cast<void *>(old_reference_type),
                  static_cast<void *>(source_template),
                  source_template->class_name().c_str(),
                  static_cast<void *>(source_template->get_type()),
                  static_cast<void *>(reference_source_template),
                  reference_source_template->class_name().c_str(),
                  static_cast<void *>(reference_source_template->get_type()),
                  static_cast<void *>(func_decl),
                  func_decl->class_name().c_str(),
                  static_cast<void *>(func_decl->get_type()),
                  static_cast<void *>(decay->get_operand()),
                  static_cast<int>(decay->get_cast_type()),
                  static_cast<int>(decay->get_semantic_conversion_kind()),
                  static_cast<void *>(old_decay_type),
                  old_decay_type != nullptr
                      ? old_decay_type->class_name().c_str()
                      : "<null>",
                  static_cast<void *>(old_result),
                  static_cast<void *>(old_decay_base),
                  exact_deferred_source_type ? 1 : 0);
              ROSE_ABORT();
            }
          }

          reference->set_semantic_function_declaration(func_decl);
          SgType *semantic_type = reference->get_type();
          if (reference->getAssociatedFunctionDeclaration() != func_decl ||
              semantic_type != func_decl->get_type() ||
              isSgFunctionType(semantic_type) == nullptr) {
            fprintf(stderr,
                    "REX_FRONTEND_INVARIANT[deduced-template-reference]: "
                    "reference=%p did not retain semantic specialization=%p "
                    "and its exact function type=%p/%p\n",
                    static_cast<void *>(reference),
                    static_cast<void *>(func_decl),
                    static_cast<void *>(semantic_type),
                    static_cast<void *>(func_decl->get_type()));
            ROSE_ABORT();
          }
          if (decay != nullptr) {
            decay->set_type(SageBuilder::buildPointerType(semantic_type));
            decay->validate_semantic_conversion();
          }
        }
        p_pending_deduced_template_function_references.erase(
            pending_references);
      }

      auto pending_member_references =
          p_pending_deduced_template_member_function_references.find(pending);
      if (pending_member_references !=
          p_pending_deduced_template_member_function_references.end()) {
        SgMemberFunctionDeclaration *semantic_member =
            isSgMemberFunctionDeclaration(func_decl);
        if (semantic_member == nullptr ||
            isSgTemplateMemberFunctionDeclaration(semantic_member) != nullptr ||
            pending_member_references->second.empty()) {
          fprintf(stderr,
                  "REX_FRONTEND_INVARIANT[deduced-template-member-reference]: "
                  "queued Clang specialization=%p translated to %p/%s "
                  "without one concrete Sage member function or reference "
                  "set\n",
                  static_cast<void *>(pending),
                  static_cast<void *>(semantic_instantiation_node),
                  semantic_instantiation_node != nullptr
                      ? semantic_instantiation_node->class_name().c_str()
                      : "<null>");
          ROSE_ABORT();
        }
        for (SgTemplateMemberFunctionRefExp *reference :
             pending_member_references->second) {
          SgTemplateMemberFunctionSymbol *source_symbol =
              reference != nullptr ? reference->get_symbol() : nullptr;
          SgTemplateMemberFunctionDeclaration *source_template =
              source_symbol != nullptr ? isSgTemplateMemberFunctionDeclaration(
                                             source_symbol->get_declaration())
                                       : nullptr;
          SgTemplateMemberFunctionDeclaration *reference_source_template =
              reference != nullptr
                  ? isSgTemplateMemberFunctionDeclaration(
                        reference->get_semantic_member_function_declaration())
                  : nullptr;
          SgTemplateMemberFunctionDeclaration *canonical_source_template =
              source_template != nullptr
                  ? isSgTemplateMemberFunctionDeclaration(
                        source_template->get_firstNondefiningDeclaration())
                  : nullptr;
          SgTemplateMemberFunctionDeclaration
              *canonical_reference_source_template =
                  reference_source_template != nullptr
                      ? isSgTemplateMemberFunctionDeclaration(
                            reference_source_template
                                ->get_firstNondefiningDeclaration())
                      : nullptr;
          if (reference == nullptr || source_template == nullptr ||
              reference_source_template == nullptr ||
              canonical_source_template == nullptr ||
              canonical_reference_source_template !=
                  canonical_source_template) {
            fprintf(
                stderr,
                "REX_FRONTEND_INVARIANT[deduced-template-member-reference]: "
                "queued reference=%p symbol=%p source-template=%p "
                "reference-template=%p canonical=%p/%p has no exact "
                "primary-template source identity before semantic "
                "binding\n",
                static_cast<void *>(reference),
                static_cast<void *>(source_symbol),
                static_cast<void *>(source_template),
                static_cast<void *>(reference_source_template),
                static_cast<void *>(canonical_source_template),
                static_cast<void *>(canonical_reference_source_template));
            ROSE_ABORT();
          }
          SgType *old_reference_type = reference->get_type();
          SgCastExp *decay = isSgCastExp(reference->get_parent());
          if (decay != nullptr) {
            SgType *old_decay_type = decay->get_type();
            SgPointerType *old_result =
                old_decay_type != nullptr
                    ? isSgPointerType(
                          old_decay_type->stripTypedefsAndModifiers())
                    : nullptr;
            SgType *old_decay_base =
                old_result != nullptr ? old_result->get_base_type() : nullptr;
            const bool exact_deferred_source_type =
                old_decay_base == old_reference_type ||
                (old_decay_base != nullptr && old_reference_type != nullptr &&
                 isSgFunctionType(
                     old_decay_base->stripTypedefsAndModifiers()) != nullptr &&
                 isSgFunctionType(
                     old_reference_type->stripTypedefsAndModifiers()) !=
                     nullptr);
            const SgCastExp::semantic_conversion_kind_enum conversion_kind =
                decay->get_semantic_conversion_kind();
            const bool exact_function_pointer_conversion =
                conversion_kind ==
                    SgCastExp::e_semantic_conversion_FunctionToPointerDecay ||
                conversion_kind ==
                    SgCastExp::e_semantic_conversion_BuiltinFnToFnPtr;
            if (decay->get_operand() != reference ||
                decay->get_cast_type() != SgCastExp::e_implicit_cast ||
                !exact_function_pointer_conversion || old_result == nullptr ||
                !exact_deferred_source_type) {
              fprintf(
                  stderr,
                  "REX_FRONTEND_INVARIANT[deduced-template-member-reference-"
                  "decay]: reference=%p parent=%p/%s old-type=%p "
                  "source-template=%p/%s source-type=%p "
                  "reference-template=%p/%s reference-type=%p "
                  "semantic-specialization=%p/%s semantic-type=%p "
                  "operand=%p cast-kind=%d semantic-kind=%d "
                  "result=%p/%s pointer=%p base=%p equivalent=%d does not own "
                  "one exact deferred function decay\n",
                  static_cast<void *>(reference), static_cast<void *>(decay),
                  decay->class_name().c_str(),
                  static_cast<void *>(old_reference_type),
                  static_cast<void *>(source_template),
                  source_template->class_name().c_str(),
                  static_cast<void *>(source_template->get_type()),
                  static_cast<void *>(reference_source_template),
                  reference_source_template->class_name().c_str(),
                  static_cast<void *>(reference_source_template->get_type()),
                  static_cast<void *>(semantic_member),
                  semantic_member->class_name().c_str(),
                  static_cast<void *>(semantic_member->get_type()),
                  static_cast<void *>(decay->get_operand()),
                  static_cast<int>(decay->get_cast_type()),
                  static_cast<int>(decay->get_semantic_conversion_kind()),
                  static_cast<void *>(old_decay_type),
                  old_decay_type != nullptr
                      ? old_decay_type->class_name().c_str()
                      : "<null>",
                  static_cast<void *>(old_result),
                  static_cast<void *>(old_decay_base),
                  exact_deferred_source_type ? 1 : 0);
              ROSE_ABORT();
            }
          }
          reference->set_semantic_member_function_declaration(semantic_member);
          SgType *semantic_type = reference->get_type();
          if (reference->getAssociatedMemberFunctionDeclaration() !=
                  semantic_member ||
              semantic_type != semantic_member->get_type() ||
              isSgMemberFunctionType(semantic_type) == nullptr) {
            fprintf(
                stderr,
                "REX_FRONTEND_INVARIANT[deduced-template-member-reference]: "
                "reference=%p did not retain semantic specialization=%p "
                "and its exact member-function type=%p/%p\n",
                static_cast<void *>(reference),
                static_cast<void *>(semantic_member),
                static_cast<void *>(semantic_type),
                static_cast<void *>(semantic_member->get_type()));
            ROSE_ABORT();
          }
          if (decay != nullptr) {
            decay->set_type(SageBuilder::buildPointerType(semantic_type));
            decay->validate_semantic_conversion();
          }
        }
        p_pending_deduced_template_member_function_references.erase(
            pending_member_references);
      }

      p_pending_function_body_completions_set.erase(pending);
      if (trace_phase_c_functions) {
        const double elapsed_ms =
            std::chrono::duration<double, std::milli>(
                std::chrono::steady_clock::now() - phase_c_function_start)
                .count();
        fprintf(stderr,
                "ROSE_PHASE_C_FUNCTION end ordinal=%zu elapsed_ms=%.3f "
                "remaining=%zu kind=%s name=%s\n",
                phase_c_function_ordinal, elapsed_ms,
                p_pending_function_body_completions.size(),
                static_cast<clang::Decl *>(pending)->getDeclKindName(),
                pending->getQualifiedNameAsString().c_str());
        fflush(stderr);
      }
    }
    if (!p_active_function_body_completions.empty()) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[function-instantiation-phase-c]: "
              "translation unit ended with an active body completion\n");
      ROSE_ABORT();
    }
    p_decl_translation_map.validate("Phase C function body completion");
    if (!p_suppressed_implicit_function_instantiation_placeholders.empty() ||
        !p_suppressed_implicit_function_instantiation_placeholder_aliases
             .empty()) {
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[function-instantiation-placeholder]: "
              "Phase C ended with forward/reverse suppressed aliases=%zu/%zu\n",
              p_suppressed_implicit_function_instantiation_placeholders.size(),
              p_suppressed_implicit_function_instantiation_placeholder_aliases
                  .size());
      ROSE_ABORT();
    }
    if (!p_pending_deduced_template_function_references.empty()) {
      const auto &unbound =
          *p_pending_deduced_template_function_references.begin();
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[deduced-template-reference]: "
              "translation unit ended with unbound Clang "
              "specialization=%p reference-count=%zu\n",
              static_cast<void *>(unbound.first), unbound.second.size());
      ROSE_ABORT();
    }
    if (!p_pending_deduced_template_member_function_references.empty()) {
      const auto &unbound =
          *p_pending_deduced_template_member_function_references.begin();
      fprintf(stderr,
              "REX_FRONTEND_INVARIANT[deduced-template-member-reference]: "
              "translation unit ended with unbound Clang member "
              "specialization=%p reference-count=%zu\n",
              static_cast<void *>(unbound.first), unbound.second.size());
      ROSE_ABORT();
    }
    roseClangPhaseTrace(
        "clang_main.HandleTranslationUnit.tuDecl.phaseCFunctionBodies.end");
  }
  if (!p_on_demand_source_publication_state.empty()) {
    const auto &pending = *p_on_demand_source_publication_state.begin();
    clang::NamedDecl *pending_named =
        llvm::dyn_cast_or_null<clang::NamedDecl>(pending.first);
    std::string pending_name =
        pending_named != nullptr ? getDeclNameSafe(pending_named) : "<unnamed>";
    std::string pending_source = "<invalid>";
    unsigned pending_line = 0;
    if (pending.first != nullptr && p_compiler_instance != nullptr) {
      clang::PresumedLoc presumed =
          p_compiler_instance->getSourceManager().getPresumedLoc(
              pending.first->getLocation());
      if (presumed.isValid()) {
        pending_source = presumed.getFilename();
        pending_line = presumed.getLine();
      }
    }
    fprintf(stderr,
            "REX_FRONTEND_INVARIANT[on-demand-source-publication]: "
            "translation unit ended with %zu incomplete source publication "
            "transactions; first=%p/%s name=%s source=%s:%u state=%d\n",
            p_on_demand_source_publication_state.size(),
            static_cast<void *>(pending.first),
            pending.first != nullptr ? pending.first->getDeclKindName()
                                     : "<null>",
            pending_name.c_str(), pending_source.c_str(), pending_line,
            static_cast<int>(pending.second));
    ROSE_ABORT();
  }
  validate_semantic_declaration_ownership_contracts(global_scope);
  SageBuilder::popScopeStack();

  // Traverse the class hierarchy

  return VisitDecl(translation_unit_decl, node) && res;
}
